INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-09', '요한계시록', '11장 11절 ~ 19절', '&nbsp;', '(요한계시록 11장)
11. 삼 일 반 후에 하나님께로부터 생기가 그들 속에 들어가매 그들이 발로 일어서니 구경하는 자들이 크게 두려워하더라
12. 하늘로부터 큰 음성이 있어 이리로 올라오라 함을 그들이 듣고 구름을 타고 하늘로 올라가니 그들의 원수들도 구경하더라
13. 그 때에 큰 지진이 나서 성 십분의 일이 무너지고 지진에 죽은 사람이 칠천이라 그 남은 자들이 두려워하여 영광을 하늘의 하나님께 돌리더라
14. 둘째 화는 지나갔으나 보라 셋째 화가 속히 이르는도다
15.  일곱째 천사가 나팔을 불매 하늘에 큰 음성들이 나서 이르되 세상 나라가 우리 주와 그의 그리스도의 나라가 되어 그가 세세토록 왕 노릇 하시리로다 하니
16. 하나님 앞에서 자기 보좌에 앉아 있던 이십사 장로가 엎드려 얼굴을 땅에 대고 하나님께 경배하여
17. 이르되 감사하옵나니 옛적에도 계셨고 지금도 계신 주 하나님 곧 전능하신 이여 친히 큰 권능을 잡으시고 왕 노릇 하시도다
18. 이방들이 분노하매 주의 진노가 내려 죽은 자를 심판하시며 종 선지자들과 성도들과 또 작은 자든지 큰 자든지 주의 이름을 경외하는 자들에게 상 주시며 또 땅을 망하게 하는 자들을 멸망시키실 때로소이다 하더라
19. 이에 하늘에 있는 하나님의 성전이 열리니 성전 안에 하나님의 언약궤가 보이며 또 번개와 음성들과 우레와 지진과 큰 우박이 있더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 7월06일 요한계시록 11장11절~19절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
두려워함: 11절 13절
경배/경외: 16절 18절
화(지진, 망함) : 13절 14절(2) 18절 19절

4.주제만들기: 
하나님께 경외하는 자들에게는 상을 불신자들에게는 화 를 주시는 하나님

5.하나님 찾기 (관찰): 
하나님을 경외하는 자에게 상 을 주시는 하나님
회개치 않은 자들에게 화 를 내리시는 하나님

6.인간 찾기 (관찰)
하나님을 경뫼히는 사람들
하나님을 두려워하는 사랑들
구름타고 하늘위를 올라가는 두 선지자
멸망하는 불신자들 

7.하나님 찾기(해석):
전능하신 하나님은 누구든지 회개하고 돌아오는 자들을 살피사 용서하시고 받아주신다. 끝까지 회개하지 않고 세상을 망가뜨리는 자들은 반드시 멸망케 하시는 심판자 하나님이시다.

8.인간(해석):
작은자나 큰자나 가리지 않으시는 하나나님을 경외히는 자는 결국 상급을 받는 영화로운 축복된 존재가 된다. 하나님을 경외한다는 뜻은 두려움을 갖는 마음이다. 하나님을 진심으로 두려워할줄 안다는것은 보이지 않는 영 이신 하냐님을 믿는다는 또다른 의미일것이다. 

9.적용(나):
하나님을 더욱 경외하는 삶을 살아내야겠다 

10. 영적터치(단어/구절)
18절: 주의 이름을 경외하는 자들에게 상 주시며 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-10', '요한계시록', '12장 1절 ~ 10절', '&nbsp;', '(요한계시록 12장)
1.  하늘에 큰 이적이 보이니 해를 옷 입은 한 여자가 있는데 그 발 아래에는 달이 있고 그 머리에는 열두 별의 관을 썼더라
2. 이 여자가 아이를 배어 해산하게 되매 아파서 애를 쓰며 부르짖더라
3. 하늘에 또 다른 이적이 보이니 보라 한 큰 붉은 용이 있어 머리가 일곱이요 뿔이 열이라 그 여러 머리에 일곱 왕관이 있는데
4. 그 꼬리가 하늘의 별 삼분의 일을 끌어다가 땅에 던지더라 용이 해산하려는 여자 앞에서 그가 해산하면 그 아이를 삼키고자 하더니
5. 여자가 아들을 낳으니 이는 장차 철장으로 만국을 다스릴 남자라 그 아이를 하나님 앞과 그 보좌 앞으로 올려가더라
6. 그 여자가 광야로 도망하매 거기서 천이백육십 일 동안 그를 양육하기 위하여 하나님께서 예비하신 곳이 있더라
7. 하늘에 전쟁이 있으니 미가엘과 그의 사자들이 용과 더불어 싸울새 용과 그의 사자들도 싸우나
8. 이기지 못하여 다시 하늘에서 그들이 있을 곳을 얻지 못한지라
9. 큰 용이 내쫓기니 옛 뱀 곧 마귀라고도 하고 사탄이라고도 하며 온 천하를 꾀는 자라 그가 땅으로 내쫓기니 그의 사자들도 그와 함께 내쫓기니라
10. 내가 또 들으니 하늘에 큰 음성이 있어 이르되 이제 우리 하나님의 구원과 능력과 나라와 또 그의 그리스도의 권세가 나타났으니 우리 형제들을 참소하던 자 곧 우리 하나님 앞에서 밤낮 참소하던 자가 쫓겨났고

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 7월07일 요한계시록 12장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
여자: 1절 2절 5절 6절
이적: 1절 3절
아이: 4절 5절(2) 6절
큰 붉은 용/밤낮 참소하던 자: 3절 4절 7절 9절 (3) 10절(2)
내쫓김: 9절 10절

4.주제만들기: 
교회를 보호하시고 사탄을 쫓아내시는 하나님

5.하나님 찾기 (관찰): 
이적을 행하시는 하나님
만국을 다스리실 예수그리스도
승리하시는 하나님

6.인간 찾기 (관찰)
광야로 피신하는 여자(교회)
사탄과 싸워 이기는 천사장 미갈
쫓겨날 사탄과 그의 세력들

7.하나님 찾기(해석):
마지막때 교회는 사탄과 그의 세력들의 핍박으로 부터 3년6개월 정도 광야로 피신을 한다. 핍박 받을때에도 하나님은 교회를 보호하시고 충분한 회복을 이루신다.

하나님은 잠시 사탄의 권세를 허용하시지만 결국 이 또한 잠시일뿐 때가 되면 사탄세력은 멸망믜 길로 내쫓으신다.

성도들은 이러한 사실을  믿음으로 받아들이고 다가올 개인과 공동체의 유한적 고난을 슬기롭게 이겨내고 마지막때 크게 반겨주실 영원한 승리의 하나님을 기대하며 사는것이 복된 삶일것이다.

8.인간(해석):
잠시동안 권세를 잡은 사탄은 처음부터 하나님을 배반하고 대적했던 존재이고 스스로가 멸망당할때 까지 그러한 행동을 지속적으로 한다.

뿐만아니라 하나님의 아들 예수까지도 해하려 했으며 할수있다면 모든 사람들을 자신과 같은 멸망의 길로 불러들이는 마치 물귀신 같은 악한 존재이다.

9.적용(나):
하나님편에 서는 자는 결국 영원한 승리의 영광의 자리에 설것이다. 이 세상에서 잠시  맛보는 출세보다는 조금 고단해도 주님의 일에 더욱 충성하는 광야의 삶을 살아내야겠다.

10. 영적터치(단어/구절)
10절: 하나님 앞에서 밤낮 참소하는 자가 쫓겨났고 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-11', '요한계시록', '12장 11절 ~ 17절', '피할 곳 없는 광야에서도 보호하시는 하나님', '[계12:11-17]
11 또 우리 형제들이 어린 양의 피와 자기들이 증언하는 말씀으로써 그를 이겼으니 그들은 죽기까지 자기들의 생명을 아끼지 아니하였도다
12 그러므로 하늘과 그 가운데에 거하는 자들은 즐거워하라 그러나 땅과 바다는 화 있을진저 이는 마귀가 자기의 때가 얼마 남지 않은 줄을 알므로 크게 분내어 너희에게 내려갔음이라 하더라
13 용이 자기가 땅으로 내쫓긴 것을 보고 남자를 낳은 여자를 박해하는지라
14 그 여자가 큰 독수리의 두 날개를 받아 광야 자기 곳으로 날아가 거기서 그 뱀의 낯을 피하여 한 때와 두 때와 반 때를 양육 받으매
15 여자의 뒤에서 뱀이 그 입으로 물을 강 같이 토하여 여자를 물에 떠내려 가게 하려 하되
16 땅이 여자를 도와 그 입을 벌려 용의 입에서 토한 강물을 삼키니
17-18 용이 여자에게 분노하여 돌아가서 그 여자의 남은 자손 곧 하나님의 계명을 지키며 예수의 증거를 가진 자들과 더불어 싸우려고 바다 모래 위에 서 있더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 7월 8일 요한계시록 12장 11절~18절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 땅(12,16절), 여자(14,15,16,17절), 용(13,17절), 
4.주제만들기: 피할 곳 없는 광야에서도 보호하시는 하나님
5.하나님 찾기 (관찰)
- 큰 독수리의 두 날개를 주심
6.인간 찾기 (관찰)
- 형제들이 어린 양의 피와 증언하는 말씀으로 이김
- 땅과 바다는 화가 있음
- 마귀는 자기의 때가 얼마 남지 않은 것을 알고 크게 분내어 내려감
- 용이 자신이 내쫓긴 것을 보고 여자를 박해함
- 뱀이 물을 토해 여자를 떠내려가게 하려 하지만 땅이 입을 벌려 강물을 삼킴
- 용은 분노하며 돌아가고 여자의 남은 자손은 하나님의 계명을 지키며 예수의 증거를 가진 자들과 함께 싸우기 위해 바다 모래 위에 서 있음
7.하나님 찾기 (해석) 
- 하나님은 피할 곳 없는 광야에서도 우리를 보호하신다. 그곳에서 한 때, 두 때, 반 때를 양육하며 더 이상 피하지 못할 절망적인 상황에서 우리를 양육하신다. 
8.인간(해석):
- 광야, 하나님의 보호 아래에서도 사탄의 공격은 계속된다. 그러나 하나님은 땅을 통해 사탄의 공격을 막아주시고 보호하신다. 이는 하나님의 전지전능함. 우리가 생각할 수 없는 방법으로 보호해주시는 것을 깨닫게 한다.
- 여자는 당시 이스라엘 백성이며, 현 시대에 교회와 내가 될 수 있다. 하나님의 보호와 양육으로 우리는 믿음을 지킬 수 있다. 그러나 믿음을 지키는 것에서 끝나는 것이 아니라 사탄과의 영적 전쟁에서 승리해야 하는데, 혼자도 좋지만 믿음을 지키는 수많은 사람과 함께 하면 더 좋을 것이다. 믿음의 동역자는 서로에게 큰 힘이 된다.
9. 적용(나): 
- NKFC 회원과 리더십을 통해 믿음의 동역자를 심어주심에 감사하다. 
- 하나님께선 피할 곳 없는 곳에서도 우리를 양육하신다. 절박한 상황에서 오히려 우리를 강건케하는 분이다. 그분을 의지하며 기도하자.
10. 영적터치(단어/구절): 
- 17-18 용이 여자에게 분노하여 돌아가서 그 여자의 남은 자손 곧 하나님의 계명을 지키며 예수의 증거를 가진 자들과 더불어 싸우려고 바다 모래 위에 서 있더라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-12', '요한계시록', '13장 1절 ~ 10절', '용과 짐승', '요한계시록 13장
1   내가 보니 바다에서 한 짐승이 나오는데 뿔이 열이요 머리가 일곱이라 그 뿔에는 열 왕관이 있고 그 머리들에는 신성모독 하는 이름들이 있더라
2   내가 본 짐승은 표범과 비슷하고 그 발은 곰의 발 같고 그 입은 사자의 입 같은데 용이 자기의 능력과 보좌와 큰 권세를 그에게 주었더라
3   그의 머리 하나가 상하여 죽게 된 것 같더니 그 죽게 되었던 상처가 나으매 온 땅이 놀랍게 여겨 짐승을 따르고
4   용이 짐승에게 권세를 주므로 용에게 경배하며 짐승에게 경배하여 이르되 누가 이 짐승과 같으냐 누가 능히 이와 더불어 싸우리요 하더라
5   또 짐승이 과장되고 신성모독을 말하는 입을 받고 또 마흔두 달 동안 일할 권세를 받으니라
6   짐승이 입을 벌려 하나님을 향하여 비방하되 그의 이름과 그의 장막 곧 하늘에 사는 자들을 비방하더라
7   또 권세를 받아 성도들과 싸워 이기게 되고 각 족속과 백성과 방언과 나라를 다스리는 권세를 받으니
