6.인간 찾기 (관찰)
- 사도 요한이 환상 가운데 
- 바다에서 한 짐승이 나오는 것을 봄
- 용이 이 짐승에게 자기의 능력과 보좌와 큰 권세를 줌
- 이 짐승은 일곱 머리가 있는데 
- 그 중 한 머리가 죽게 된 것 같더니 나으매 온 땅이 놀랍게 여겨 짐승을 따름
- 용이 짐승에게 권세를 주므로 
- 사람들이 용을 경배하고
- 짐승도 경배함
- 짐승이 하나님을 비방하되
- 이름과 장막 곧 하늘에 사는 자들을 비방함
- 생명책에 창세 이후로 이름이 기록되지 못하고 이 땅에 사는 자들은 다 그 짐승에게 경배함
- 사로잡힐 자는 사로잡혀 갈 것이요
- 칼에 죽을 자는 마땅히 칼에 죽을 것임
- 그러므로 성도의 인내와 믿음이 필요함

7.하나님 찾기 (해석) 
- 구원받을 자의 이름을 생명책에 기록하심

8.인간(해석): 
- 용과 짐승을 경배하고 따르는 사람들이 다수 있음
- 이 세력들에게 믿는 자들은 핍박을 받을 것임
- 그러나 그 상황들을 인내와 믿음으로 이겨내면
- 그 성도의 인내와 믿음이 증명될 것이며,
- 최후 승리에 동참하게 될 것이다.

9.적용(나)
- 고난과 핍박이 있을 때,
- 보이지 않는 소망으로 구원을 얻었음을 기억하고,
- 보이는 것이 전부가 아님을 기억하며,
- 보이지 않는 것을 바라니 최후 승리를 참음으로 기다리며,
- 나에게 주어진 길을 걸어가야겠다. 

