6.인간 찾기 (관찰)
첫째 짐승(적그리스도)과 둘째 짐승(거지헌지자) 의 악행을 보며주고 있는 사도요한 
권세를 받은 거짓 선지자(둘째짐승)에게 미혹당하거나 굴복하는 성도들
우상숭배를 하지않는 자들을 죽이는 짐승(거짓선지자)
표를 받지않는 자들은 물건을 매매할수 없다

7.하나님 찾기(해석):

8.인간(해석):
고대사회에서 사용하였던 게마트리아(문자를 숫자화 하여 암호를 해석하는 방식)를 통하여 짐승의 숫자 666을 알아볼수 있다.

666을 게마트리아 방법으로 대입하면 ''네로'' 라는 이름이 나온다
그는  로마시대의 최고 막강한 권세를 가진 황제이었다. 그는 그 힘으로 예수를 믿는 유대인들 을 무자비하게 핍박한 악한 황제였다.

그 시대의 믿는 성도들이 슬기롭게 믿음을 어떻게 지켰는지 또한 얼마나 큰 거짓 선지자로부터 유혹을 당했는지 짐작할수 있다.

오랜 시간이 지난 지금도 마찬가지로   거짓목사들(이단들)이 세상을 혼탁하게 하며 믿는성도조차도 미혹케하는것을 쉽게 볼수있다.

거짓선지자 를 조정하는 배후에는 최고의 짐승인 사탄이 존재함을 보여준다.

사람을 쉽게 흥분케하는 이적을 바라기보다 순수한 복음적 말씀 이해와 깨우침이 얼마나 중요한지 되새기게 된다.

사탄의 공격에 쉽게 노출된  열악한 세상가운데에서도 다행한것은 큰 권세를 잡은 사탄이나 그의 부하들이 성도를 괴롭히는것은 시간적으로 유한하다. 이또한 하나님이 허락하신 시간이다.
성도로써 고난의 환경을 잘 견디고 늘 주님의 말씀을 붙잡고 사는것이 슬기로운 성도의 모습이라 깨우쳐진다.

9.적용(나):
거짓선지자의 가르침이 아닌 참된 주님의 종으로 순수한 복음을 잘 가르쳐야겠다.

