3   그들이 보좌 앞과 네 생물과 장로들 앞에서 새 노래를 부르니 땅에서 속량함을 받은 십사만 사천 밖에는 능히 이 노래를 배울 자가 없더라
4   이 사람들은 여자와 더불어 더럽히지 아니하고 순결한 자라 어린 양이 어디로 인도하든지 따라가는 자며 사람 가운데에서 속량함을 받아 처음 익은 열매로 하나님과 어린 양에게 속한 자들이니
