1:감동받는 단어나 구절 찾기(영적터치)

2024년 7월 12일 요한계시록 14장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 구름 위에 앉은 이(15,16절), 낫(15,16,17,18,19절), 예리한 낫(14,17,18절), 곡식(15,16절), 포도(18,19절), 천사(15,18,19절), 거두다(15,16,19,20절)
4.주제만들기: 하나님 나라와 심판
5.하나님 찾기 (관찰)
- 수고를 그치고 쉬리니 그들의 행한 일을 따름이라 성령님이 말하심
- 구름위에 앉으신 이, 머리에는 금 면류관과 손에 예리한 낫을 들고 나타나시는 예수님
- 땅에 있는 곡식이 다 익어 거둘 때가 이르러 예리한 낫을 휘둘러 땅의 곡식을 거두심
- 포도 송이를 거두어 큰 포도주 틀에 던지심
6.인간 찾기 (관찰)
- 짐승과 우상에게 경배하고 표를 받은 자들은 쉼을 얻지 못함
- 성도들의 인내는 하나님의 계명과 예수님을 믿는 믿음을 지키는 것
- 주 안에서 죽은 자들은 복이 있음
7.하나님 찾기 (해석) 
- 하나님은 불의를 지켜만 보시는 분이 아니시다. 그들이 돌이킬수 있는 기회와 시간을 충분히 주신 후에 악을 심판하신다.
- 반대로 의인의 고난도 지켜만 보지 않으신다. 하나님께선 하나님의 방법으로 의인, 하나님의 계명과 예수님을 믿는 믿음을 지키는 자들을 보호하신다. 그리고 하나님의 때에 복을 주시고 수고한 일들을 쉬게 해주신다.
- 예리한 낫, 예리하다는 것은 끝이 뾰족하거나 날이 선 상태라는 뜻도 있지만 관찰이나 판단이 정확하다는 의미가 있다. 그것은 하나님께서 선과 악을 구분하시는 것으로 거짓된 신앙생활은 반드시 들통나게 되어 있다.
8.인간(해석):
- 세상과 다른 가치관과 기준이라도 하나님의 말씀을 따라 살아가야한다. 하나님께선 우리를 지켜보시고 우리를 보호하시며 하나님이 예비하신 큰 상급이 있기 때문이다. 그것이 이 땅에서 세상 사람들이 바라는 성공의 기준이 아닐지라도 하늘에서 주어지는 상급이 있기 때문에 소망을 가지고 사명을 감당해야 한다.
- 하나님은 반드시 악을 심판하신다. 내가 의인이라는 착각은 버려야 한다. 그리고 심판이 있다는 것을 알고 하나님을 믿지 못하는 자들을 구원해야 한다.
9. 적용(나):
- 어떠한 상황과 환경이라도 하나님의 말씀과 예수님을 믿는 믿음을 잃지 말아야 한다.
- 한 영혼이라도 더 구원 받을 수 있도록 노방 전도에 힘써야겠다.
10. 영적터치(단어/구절): 예리한 낫
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-16', '요한계시록', '15장 1절 ~ 8절', '&nbsp;', '(요한계시록 15장)
1. 또 하늘에 크고 이상한 다른 이적을 보매 일곱 천사가 일곱 재앙을 가졌으니 곧 마지막 재앙이라 하나님의 진노가 이것으로 마치리로다
2. 또 내가 보니 불이 섞인 유리 바다 같은 것이 있고 짐승과 그의 우상과 그의 이름의 수를 이기고 벗어난 자들이 유리 바다 가에 서서 하나님의 거문고를 가지고
3. 하나님의 종 모세의 노래, 어린 양의 노래를 불러 이르되 주 하나님 곧 전능하신 이시여 하시는 일이 크고 놀라우시도다 만국의 왕이시여 주의 길이 의롭고 참되시도다
4. 주여 누가 주의 이름을 두려워하지 아니하며 영화롭게 하지 아니하오리이까 오직 주만 거룩하시니이다 주의 의로우신 일이 나타났으매 만국이 와서 주께 경배하리이다 하더라
5. 또 이 일 후에 내가 보니 하늘에 증거 장막의 성전이 열리며
6. 일곱 재앙을 가진 일곱 천사가 성전으로부터 나와 맑고 빛난 세마포 옷을 입고 가슴에 금 띠를 띠고
7. 네 생물 중의 하나가 영원토록 살아 계신 하나님의 진노를 가득히 담은 금 대접 일곱을 그 일곱 천사들에게 주니
8. 하나님의 영광과 능력으로 말미암아 성전에 연기가 가득 차매 일곱 천사의 일곱 재앙이 마치기까지는 성전에 능히 들어갈 자가 없더라

