7.하나님 찾기(해석):
하나님은 심판의 공의와 더불어 환난 가운데에서도 믿음을 저버리지 않은 성도들에게 예배를 통하여 하나님의 영광을 충분히 느낄수 있는 기회를 제공하신다.

8 인간 찾기(해석)
세상에서 주는 고난은 잠시 유한적인 것을 사도요한은 알려주고 있다. 결국 어려운 시기가 있더라도 잠시 인내하고 견딘다면 "하나님의 거문고"를 가지고 고요한 호수같은 평강안에서 주를 마음껏 높여드리고 찬양할 날 들이 곧 올것이다.

반면에 우상과 사탄 그리고 그의 추종자들은 주님의 큰 재앙으로 말미암아 주의 성전에 들어오지도 못하고 큰 심판을 받을것이다.

