진노하시는 하나님
참되고 의로우신 하나님
심판하시는 하나님

6.인간 찾기 (관찰)
우상에게 경배하는 자들
각종 재앙의 심판받는 사람들
하나님의 이름을 비방하며 회개하지 않는 사람들

7.하나님 찾기(해석):
하나님은 피조물인 인간들에게 한없이 자비로우신 분 이시다. 하지만 하나님의 마지막 심판의 때가 오면 주님의 경고의 약속처럼 심판을 행하신다. 그때는 마지막 이기때문에 더이상 자비를 베풀지 않으신다. 공의와 심판으로 그분의 거룩함과 공의 그리고 의로우심을 나타내신다.

8 인간 찾기(해석)
세상에 도래할 물리적 환경적 마지막 때가 있고 개인에게 다가오는 마지막 순간이 있다.  인간에게는 반드시 둘중 하나를 선택하고 살아간다. 전자는 주님을 배반하지않고 때때로 피흘림을 각오하며 희생적이고 복음적인 삶을 사는것이 있다. 또 다른 후자는 적당히 세상과 타협하며 우상을 섬기며 단지 영혼의 평강이 아닌 육체적 편안과 안위만을 목표로 사는 사람들이 있다. 이러한 사람들은 회개하지 않으면 반드시 하나님의 진노가 임할것이라 사도요한은 받은 진리를 알려주고 있다.

9.적용(나):
주님의 피 흘리신 십자가를 바라보며 더욱 그러한 삶을 살아내야겠다.
늦더라도 마포대교 가서 전도를 해아겠다.

