2024년 7월15일 요한계시록 16장 11절~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-비방(11,21절),입(13절), 영(13,1416잘_. 음성(17,18절), 큰 성(19절), 우박(21절)
4.주제만들기: 회개하지 않는 자들의 최후
5.하나님 찾기 (관찰)
- 도둑 같이 아무도 모르게 하나님의 때에 우리에게 찾아오심
- 큰 음성으로 인간을 심판하심
6.인간 찾기 (관찰)
- 종기가 생겨도 회개하지 않고 비방하는 인간들
- 큰 우박이 내려도 회개하지 않고 비방하는 인간들
- 더러운 세 영이 인간을 미혹함
- 하나님을 대적하기 위해 큰 전쟁을 준비함
7.하나님 찾기 (해석) 
- 하나님은 우리에게 충분한 기회, 환경을 주시지만 하나님의 심판은 반드시 이루어진다. 하나님의 때가 되면 아무도 모르게 오시는데 하나님 앞에서 부끄러움을 보이지 않은 자만이 복을 받을 수 있다. 우리에게 쉬운 일이 아니기 때문에 정신 차리고 하나님을 의지해야 한다. 미혹된 영으로 인해 세상에서 분별하지 못하고 악에 빠져 시간을 허비할 수 있다.
8.인간(해석):
- 나를 포함해 인간은 참으로 어리석다. 하나님께서 수많은 기회를 주시지만 인간은 돌이키지 않는다. 오히려 하나님을 비방하고 하나님을 대적하는 어리석은 영에 사로잡혀 하나님을 따르지 못하는 어리석음 선택을 하게 된다. 하나님께선 사랑이시기에 우리가 어떠한 죄와 환경 가운데 있더라도 하나님께 회개하고 나아오면 우리를 붙잡아주시는 분이다. 
- 회개가 이루어지면 우리는 그 다음 단계로 나아가야 한다. 회개의 단계에서 머무는 것이 아니라 하나님이 우리에게 주신 소명을 다해야 한다. 그것이 우리가 우리의 옷을 지키는 방법이며 하나님이 오실 때에 부끄러움을 보이지 않고 당당하게 하나님 앞에 나아갈 수 있을 것이다.
9. 적용(나):
- 이 세대, 세상은 편한 것에 익숙해져 있다. 신앙생활, 전도, 예배 등. 그런데 그것이 정말 하나님께서 원하시는 것인지 생각해보아야겠다.  
- 노방전도를 깨닫게 하신 하나님께 감사드린다.
10. 영적터치(단어/구절)
- 11 아픈 것과 종기로 말미암아 하늘의 하나님을 비방하고 그들의 행위를 회개하지 아니하더라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-19', '요한계시록', '16장 11절 ~ 21절', '땅의 음녀들과 가증한 것들의 어미', '2024.7.16.

요한계시록 17장
1 또 일곱 대접을 가진 일곱 천사 중 하나가 와서 내게 말하여 이르되 이리로 오라 많은 물 위에 앉은 큰 음녀가 받을 심판을 네게 보이리라
2 땅의 임금들도 그와 더불어 음행하였고 땅에 사는 자들도 그 음행의 포도주에 취하였다 하고
3 곧 성령으로 나를 데리고 광야로 가니라 내가 보니 여자가 붉은 빛 짐승을 탔는데 그 짐승의 몸에 하나님을 모독하는 이름들이 가득하고 일곱 머리와 열 뿔이 있으며
4 그 여자는 자주 빛과 붉은 빛 옷을 입고 금과 보석과 진주로 꾸미고 손에 금 잔을 가졌는데 가증한 물건과 그의 음행의 더러운 것들이 가득하더라
5 그의 이마에 이름이 기록되었으니 비밀이라, 큰 바벨론이라, 땅의 음녀들과 가증한 것들의 어미라 하였더라
6 또 내가 보매 이 여자가 성도들의 피와 예수의 증인들의 피에 취한지라 내가 그 여자를 보고 놀랍게 여기고 크게 놀랍게 여기니
7 천사가 이르되 왜 놀랍게 여기느냐 내가 여자와 그가 탄 일곱 머리와 열 뿔 가진 짐승의 비밀을 네게 이르리라
8 네가 본 짐승은 전에 있었다가 지금은 없으나 장차 무저갱으로부터 올라와 멸망으로 들어갈 자니 땅에 사는 자들로서 창세 이후로 그 이름이 생명책에 기록되지 못한 자들이 이전에 있었다가 지금은 없으나 장차 나올 짐승을 보고 놀랍게 여기리라
9 지혜 있는 뜻이 여기 있으니 그 일곱 머리는 여자가 앉은 일곱 산이요
10 또 일곱 왕이라 다섯은 망하였고 하나는 있고 다른 하나는 아직 이르지 아니하였으나 이르면 반드시 잠시 동안 머무르리라


