- 짐승의 일곱 머리는 여자가 앉은 일곱 산이고 일곱 왕인데
- 다섯은 망하였고 하나는 있고 다른 하나는 아직 이르지 아니하였음
- 이르면 반드시 잠시 동안 머무를 것임

7.하나님 찾기 (해석) 
- 세상에는 큰 음녀가 존재하고 이 큰 음녀가 세상을 다스리고 있다.
그러나 하나님의 심판은 반드시 있으며, 음녀와 짐승은 하나님의 심판을 받을 것이다. 

8.인간(해석): 
- 세상 왕들과 사람들은 큰 음녀와 음행하고 음행의 포도주에 취해 있다.
- 이는 하나님을 섬기지 않고 다른 무언가에 홀려 있다는 것.
- 큰 음녀는 화려하게 치장하고 더러운 것이 가득한 금잔을 들고 있는데,
- 눈에 보이는 화려함과 권력과 권세에 속아서는 안 되고 
- 그 속에 뭐가 있는지 살펴야 함
- 음녀는 성도들과 예수님의 증인을 죽이는 자임
- 지금도 믿는 자들을 죽이거나 괴롭히는 사람들이 있음 
- 짐승의 일곱 머리는 일곱 왕인데, 이중 다섯은 망하였고, 하나는 있으며, 
- 다른 하나는 아직 이르지 않았으나, 잠시 머무를 것임.
- 아직 핍박이 끝나지 않았으나 그 핍박의 시간은 짧고 하나님의 심판이 있을 것임.

9.적용(나)
- 세상에는 사람을 홀리는 것들이 참 많다.
- 하나님을 사랑하지 않고 다른 존재(또는 물질)를 보암직하게 먹음직스럽게 포장하고 있다.
- 음행하는 것이 지혜로운 것처럼 보이게 하기도 한다.
- 그러나 우리 성도는 하나님 아닌 다른 것을 사랑하고 섬기는 것이 
- 무엇인지 잘 생각하고 행동해야 한다.
- 계시록을 보면 사람을 유혹하고 성도를 괴롭히는 존재가 있음을 알 수 있다.
- 이 존재가 어디이고 누구인지 모르지만, 그(녀)는 분명히 있다.
- 늘 성령님을 의지하여 말씀과 기도에 깨어 있어 이들을 잘 분별해야겠다. 

10. 영적터치(단어/구절)  
  10   또 일곱 왕이라 다섯은 망하였고 하나는 있고 다른 하나는 아직 이르지 아니하였으나 이르면 반드시 잠시 동안 머무르리라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

