4.주제 만들기: 멸망하는 바벨론

5.하나님 찾기 (관찰)
- 성도들에게 여자의 죄에 참여하지 말고, 그가 받을 재앙을 받지 말라고 말씀하심
- 여자는 하루 동안에 사망과 애통함과 흉년이 있고 또한 불에 살라질 것임 
- 그를 심판하시는 주 하나님은 강하신 분이다.

6.인간 찾기 (관찰)
- 여자의 음행의 진노의 포도주로 말미암아 만국이 무너짐
- 땅의 왕들이 그 여자와 더불어 음행하였으며
- 땅의 상인들도 그 사치의 세력으로 부자가 됨
- 여자는 자기를 영화롭게 하고 사치하였음
- 여자와 함께 하던 왕들이 여자의 고통을 보고 울고 가슴을 치며 무서워 함

7.하나님 찾기 (해석) 
- 하나님은 여자의 행위와 여자를 따르는 자들을 지켜 보신다.
- 그러나 성도들은 그 행위에 동참하지 말고 그 곳에서 나올 것을 명령하신다.
- 하나님은 오래 참으시지만, 하나님의 때가 되면 심판을 하실 것이다.
- 만군의 하나님은 강력하셔서 세상에서 위세를 떨치며 스스로 영화롭게 하던 여자는 한순간에 고통을 당하며 멸망할 것이다. 

8.인간(해석): 
- 음행과 허영심으로 인간을 무너뜨리는 존재(영적 존재 또는 물질적 존재 등)가 있다.
- 그 음행과 허염심을 조장하는 존재는, 스스로를 높이며 즐거워하는 존재이다.
- 우리 인간은 음행과 허영심, 그리고 스스로를 영화롭게 하는 마음/생각을 조심해야 한다. 
- 하나님을 높이지 않고 자신을 높이는 존재는 결국 멸망하고
- 아버지 하나님을 사랑하고 그곳을 떠나라는 명령에 순종하는 자들은 구원을 받을 것이다.

9.적용(나)
- 일의 성취나 영적 성장을 경험할 때 교만함이 올라올 때가 있다.
- 아니라고 하지만, 마음 속 깊은 곳에 내가 저들 보다 낫다고 여길 때가 분명히 있다.
- 이런 생각들은 앞으로도 있을 것이다. 
- 그때마다 성령님께서 나의 음행과 허영심을, 나를 높이고 있다는 사실을 깨닫게 해 주시길 기도한다.

10. 영적터치(단어/구절)  
  7   그가 얼마나 자기를 영화롭게 하였으며 사치하였든지
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-23', '요한계시록', '18장 11절 ~ 24절', '반드시 임하는 하나님의 심판, 깨닫지 못하는 인간들', '[계18:11-24]
11 땅의 상인들이 그를 위하여 울고 애통하는 것은 다시 그들의 상품을 사는 자가 없음이라
12 그 상품은 금과 은과 보석과 진주와 세마포와 자주 옷감과 비단과 붉은 옷감이요 각종 향목과 각종 상아 그릇이요 값진 나무와 구리와 철과 대리석으로 만든 각종 그릇이요
13 계피와 향료와 향과 향유와 유향과 포도주와 감람유와 고운 밀가루와 밀이요 소와 양과 말과 수레와 종들과 사람의 영혼들이라
14 바벨론아 네 영혼이 탐하던 과일이 네게서 떠났으며 맛있는 것들과 빛난 것들이 다 없어졌으니 사람들이 결코 이것들을 다시 보지 못하리로다
15 바벨론으로 말미암아 치부한 이 상품의 상인들이 그의 고통을 무서워하여 멀리 서서 울고 애통하여
16 이르되 화 있도다 화 있도다 큰 성이여 세마포 옷과 자주 옷과 붉은 옷을 입고 금과 보석과 진주로 꾸민 것인데
17 그러한 부가 한 시간에 망하였도다 모든 선장과 각처를 다니는 선객들과 선원들과 바다에서 일하는 자들이 멀리 서서
18 그가 불타는 연기를 보고 외쳐 이르되 이 큰 성과 같은 성이 어디 있느냐 하며
19 티끌을 자기 머리에 뿌리고 울며 애통하여 외쳐 이르되 화 있도다 화 있도다 이 큰 성이여 바다에서 배 부리는 모든 자들이 너의 보배로운 상품으로 치부하였더니 한 시간에 망하였도다
20 하늘과 성도들과 사도들과 선지자들아, 그로 말미암아 즐거워하라 하나님이 너희를 위하여 그에게 심판을 행하셨음이라 하더라
21 이에 한 힘 센 천사가 큰 맷돌 같은 돌을 들어 바다에 던져 이르되 큰 성 바벨론이 이같이 비참하게 던져져 결코 다시 보이지 아니하리로다
22 또 거문고 타는 자와 풍류하는 자와 퉁소 부는 자와 나팔 부는 자들의 소리가 결코 다시 네 안에서 들리지 아니하고 어떠한 세공업자든지 결코 다시 네 안에서 보이지 아니하고 또 맷돌 소리가 결코 다시 네 안에서 들리지 아니하고
23 등불 빛이 결코 다시 네 안에서 비치지 아니하고 신랑과 신부의 음성이 결코 다시 네 안에서 들리지 아니하리로다 너의 상인들은 땅의 왕족들이라 네 복술로 말미암아 만국이 미혹되었도다
24 선지자들과 성도들과 및 땅 위에서 죽임을 당한 모든 자의 피가 그 성 중에서 발견되었느니라 하더라

