1:감동받는 단어나 구절 찾기(영적터치)

2024년 7월20일 요한계시록 18장 11절~24절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-상품(11,12,15,19절), 영혼(13,14절), 바벨론(14,15,21절), 상인(11,15절), 큰 성(16,18,19,21절), 네 안에서 다시 들리지 아니하니(22,23절), 한 시간에 망하였도다(17,19절)
4.주제만들기: 반드시 임하는 하나님의 심판, 깨닫지 못하는 인간들
5.하나님 찾기 (관찰)
- 심판을 행하심
- 힘센 천사가 바다에 큰 돌을 던져 바다에 던짐
6.인간 찾기 (관찰)
-상품을 사는 자가 없어짐
-상품에는 각종 보물과 식품과 종과 사람의 영혼들이 포함된
-상인들은 고통스러워하고 애통하며 울음
-하나님의 심판으로 선지자와 성도, 땅 위에서 죽임을 당한 모든 자의 피가 성중에 발견됨
7.하나님 찾기 (해석)
- 하나님께선 우리를 심판하실 수 있다. 지금 당장이라도 한 시간안에 이 세상을 멸망시키실 수 있다. 그러나 우리에게 회복의 기회를 주셨다. 
-우리가 살고 있는 이 시대가 악하다고 마지막 때가 다가왔다는 말을 많이들 한다. 하나님께선 마지막 때를 깨닫고 있는 우리에게 어떤 기회를 주셨을까?   
8.인간(해석):
- 상인들은 자신의 보석이 없어지자 고통스러워하고 운다. 그런데 회개하는 사람은 단 한명도 없다. 현 시대와 같은 모습이다. 적어도 그 시대는 하나님을 알기라도 했을 것인데, 지금 시대는 하나님을 알지 못하는 자들이 너무 많다. 
- 상인들이 판매했던 것은 보물과 식품들 그리고 종(사람)이 끝이 아니었다. 사람의 영혼까지 판매했다. 현 시대는 물질 만능주의에 빠져있다. 그리고 한번 사는 삶, 하고 싶은 것을 모두 즐기며 살아가도록 권하고 있다. 결혼도 자유이며 모든 것이 스스로 결정하여 살아가는 삶이 멋진 삶으로 포장하고 있다. 그것이 영혼을 파는 상인들의 목적이다. 사탄의 목적인 것이다. 물질에 빠지고, 의미 없는 것에 시간과 열정을 쏟게 하는 것에 주의해야 한다. 
- 하나님의 심판에 상인들 뿐 만 아니라 선지자와 성도들의 피도 발견된다. 이것은 신앙인들의 희생도 포함되어 있을 수 있다는 것이라 생각한다. 선교사, 사역자 뿐 만 아니라 그들을 섬기며 함께 사역에 동참하는 성도들까지 하나님의 때를 위해 피 흘림으로 사명을 감당하는 분들이 경우도 있을 것이다. 세상이 보기엔 어리석은 피 흘림이라 생각할 수 있지만 하나님의 나라에선 위대한 사명을 감당한 일꾼으로 칭찬 받을 것이다.  
9. 적용(나): 
- 칭찬 받더라도 피 흘리는 일이 내게 일어나는 것은 끔찍할 것이다. 그러나 피 흘림으로 누군가는 하나님을 알고 구원 받을 수 있으니... 이러한 갈등을 뛰어넘는 신앙이 내게 생기길 원한다.
- 물질만능주의에 빠지지 않도록 하나님의 지혜와 은혜가 가득임하길 원한다.
- 하나님의 심판이 하나님을 믿지 않는 자들에게만 임하는 것이 아니다. 내가 잘못하고 있는 죄들은 무엇인지 점검하고 깨닫길 기도해야겠다.
10. 영적터치(단어/구절)
- 13 계피와 향료와 향과 향유와 유향과 포도주와 감람유와 고운 밀가루와 밀이요 소와 양과 말과 수레와 종들과 사람의 영혼들이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-24', '요한계시록', '19장 1절 ~ 10절', '&nbsp;', '(요한계시록 19장)
1.  이 일 후에 내가 들으니 하늘에 허다한 무리의 큰 음성 같은 것이 있어 이르되 할렐루야 구원과 영광과 능력이 우리 하나님께 있도다
2. 그의 심판은 참되고 의로운지라 음행으로 땅을 더럽게 한 큰 음녀를 심판하사 자기 종들의 피를 그 음녀의 손에 갚으셨도다 하고
3. 두 번째로 할렐루야 하니 그 연기가 세세토록 올라가더라
4. 또 이십사 장로와 네 생물이 엎드려 보좌에 앉으신 하나님께 경배하여 이르되 아멘 할렐루야 하니
5. 보좌에서 음성이 나서 이르시되 하나님의 종들 곧 그를 경외하는 너희들아 작은 자나 큰 자나 다 우리 하나님께 찬송하라 하더라
6. 또 내가 들으니 허다한 무리의 음성과도 같고 많은 물 소리와도 같고 큰 우렛소리와도 같은 소리로 이르되 할렐루야 주 우리 하나님 곧 전능하신 이가 통치하시도다
7. 우리가 즐거워하고 크게 기뻐하며 그에게 영광을 돌리세 어린 양의 혼인 기약이 이르렀고 그의 아내가 자신을 준비하였으므로
8. 그에게 빛나고 깨끗한 세마포 옷을 입도록 허락하셨으니 이 세마포 옷은 성도들의 옳은 행실이로다 하더라
9. 천사가 내게 말하기를 기록하라 어린 양의 혼인 잔치에 청함을 받은 자들은 복이 있도다 하고 또 내게 말하되 이것은 하나님의 참되신 말씀이라 하기로
10. 내가 그 발 앞에 엎드려 경배하려 하니 그가 나에게 말하기를 나는 너와 및 예수의 증언을 받은 네 형제들과 같이 된 종이니 삼가 그리하지 말고 오직 하나님께 경배하라 예수의 증언은 예언의 영이라 하더라

