2024년 7월20일 요한계시록 19장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
어린 양의 혼인: 7절  9절
심판/갚다: 2절(2) 
찬양/찬송/경배: 4절 5절 10절(2)
허다한 무리: 1절 6절
음녀: 2절(2)
하나님께: 1절 5절 10절

4.주제만들기: 
어린양 혼인 잔치에 초대받은 성도들

5.하나님 찾기 (관찰): 
구원과  영광과 능력의 하나님
심판자 되신 하나님 
참되고 의로으신 하나님
세마포 옷을 입도록 허락하신 하나님
혼인 잔치에 청하시는 하나님
증언자 되신 예수

6.인간 찾기 (관찰)
하나님께 경배드리는 하늘의 허다한 무리와 이십사 장로 그리고 네 생물들.
혼인잔치에 청함을 받은 성도들
신부로써 새마포 옷을 입는 신부

7.하나님 찾기(해석):
공믜로운 심판자이신 하나님은 때가차매 음녀를 심판하신다. 믿음을 지키며 흘렸던 종들의 피를 기억하시고 반드시 갚아주신다.

세상에서 살면서 주의 일을 행하다 겪는 조그만한 고난과 수고들을 빠짐없이 하나님은 기억하시고 훗날 충분히 위로해 주신다. 세상에서 혹이나 악인으로부터 억울한 핍박 이나 고통을 당했더라도 공이의 하나님은 갚아주신다. 그러므로 승승장구 하는것처럼 보이는 변질자 들이나 권세자들을 부러워할 필요가 전혀없다.

도리어 믿음을 지킨자들은 주님의 신부로써 받아들여지고  어린양 혼인잔치에 청함을 받는 영광을 받는다.
그때를 기대하면 이땅에서 짧은 여정은 즐거움의 광야의 시간으로 여겨질것이다.

8 인간 찾기(해석)
어린양 예수 혼인잔치에 청함을 받은 신부로 받아주시고 베풀어 주시는 하나님의 크신 사랑을 다시 생각하게된다.

죄인인 나를 위해 대신 죽으시고 구원해 주신것만 해도 평생 갚을수 없는 사랑을 받은것인데 신부까지 삼으시는 주님의 사랑을 어찌 갚을수 있을까?

이땅에서 사는 동안 목숨을 다하여 주 하나님을 더욱 사랑하는 사람이 될것을 사도요힌은 알려주고 있다.

9.적용(나):
영혼을 사랑하시는 주님의 마음으로 오늘도 마포대교 한강대교 를 가야겠다 

10. 영적터치(단어/구절)
10절: 오직 하나님께 경배하라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-25', '요한계시록', '19장 11절 ~ 21절', '&nbsp;', '(요한계시록 19장)
11.  또 내가 하늘이 열린 것을 보니 보라 백마와 그것을 탄 자가 있으니 그 이름은 충신과 진실이라 그가 공의로 심판하며 싸우더라
12. 그 눈은 불꽃 같고 그 머리에는 많은 관들이 있고 또 이름 쓴 것 하나가 있으니 자기밖에 아는 자가 없고
13. 또 그가 피 뿌린 옷을 입었는데 그 이름은 하나님의 말씀이라 칭하더라
14. 하늘에 있는 군대들이 희고 깨끗한 세마포 옷을 입고 백마를 타고 그를 따르더라
15. 그의 입에서 예리한 검이 나오니 그것으로 만국을 치겠고 친히 그들을 철장으로 다스리며 또 친히 하나님 곧 전능하신 이의 맹렬한 진노의 포도주 틀을 밟겠고
16. 그 옷과 그 다리에 이름을 쓴 것이 있으니 만왕의 왕이요 만주의 주라 하였더라
17. 또 내가 보니 한 천사가 태양 안에 서서 공중에 나는 모든 새를 향하여 큰 음성으로 외쳐 이르되 와서 하나님의 큰 잔치에 모여
18. 왕들의 살과 장군들의 살과 장사들의 살과 말들과 그것을 탄 자들의 살과 자유인들이나 종들이나 작은 자나 큰 자나 모든 자의 살을 먹으라 하더라
19. 또 내가 보매 그 짐승과 땅의 임금들과 그들의 군대들이 모여 그 말 탄 자와 그의 군대와 더불어 전쟁을 일으키다가
20. 짐승이 잡히고 그 앞에서 표적을 행하던 거짓 선지자도 함께 잡혔으니 이는 짐승의 표를 받고 그의 우상에게 경배하던 자들을 표적으로 미혹하던 자라 이 둘이 산 채로 유황불 붙는 못에 던져지고
21. 그 나머지는 말 탄 자의 입으로부터 나오는 검에 죽으매 모든 새가 그들의 살로 배불리더라

