2024년 7월21일 요한계시록 19장11절~21절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
백마: 11절 14절 
살: 18절(3) 21절
짐승: 19절 20절 
싸우다/전쟁: 11절 19절 
잡히다/죽다: 20절 21절

4.주제만들기: 
백마를 타신 승리의 예수

5.하나님 찾기 (관찰): 
만왕의 왕이요 만주의 주
백마를 타신 예수
승리케 하시는 하나님

6.인간 찾기 (관찰)
짐승을 섬멸하는 백마를 타신 예수와 그의 군사들

7.하나님 찾기(해석)
때가 차매  백마를 타신 예수께서 그의 군사들과 더불어 땅의 임금이나 권세자들  그리고 짐승같은 존재들을 무찌르시고 유황불에 던지신다.

마지막때는 결코 자비는 없고 오직  심판과 공의 뿐이다.  그러므로 시간적 기회가 주어졌을때 더욱 회개하며 주님의 군사로써의 삶을 사는것이 무엇보다 중요함을 보여주고 있다.

8 인간 찾기(해석)
13절에 등장하는 강력한 하나님의 무기는 "말씀"인것을 사도요한은 일깨워주고 있다.  더욱 마지막 때로 갈수록 악행이 강력해지는 세상을 맞닥뜨리며 승리케 할수 있는 힘은 하나님 말씀이다.

더욱 3331큐티를 소중히 여기며 날마다 진리를 지키며 세상 유혹에 빠지지 않도록 힘써야겠다.

9.적용(나):
