3.반복단어 찾기(형광펜 추천)
- 사탄(2,7절), 천년(2,3,4,5,7절), 미혹(3,8,10절), 부활(5,6,절),  
4.주제만들기
5.하나님 찾기 (관찰)
- 천사가 무저갱의 열쇠와 큰 사슬을 가지고 하늘로부터 내려와 사탄을 잡고 결박함
- 첫째 부활에 참여하는 자들에게 복주심
- 불을 내리셔서 사탄을 태우심
6.인간 찾기 (관찰)
- 하나님의 말씀으로 순교한 자들과
- 이마와 손에 표를 받지 않는 자들은 천년 동안 그리스도와 함께 왕노릇을 하게 됨
- 무저갱에서 풀려난 사탄은 천년이 지난 후에 무저갱을 나와 다시 사람들을 미혹하여 싸우게 함
- 하나님의 심판으로 밤낮 괴로움을 받게 됨
7.하나님 찾기 (해석) 
- 하나님께선 하나님을 위해 사명을 다한 사람을 잊지 않으신다. 하나님께서 주신 상급은 하나님과 같이 왕노릇할 수 있을 정도의 큰 상을 주신다. 그만큼 하나님께서 주신 사명을 감당하는 것은 하나님이 매우 기뻐하신다는 것을 알 수 있다.  
- 하나님께선 반드시 심판하신다. 선은 반드시 승리할 것이다. 세상에 타협하지 말고 하나님을 쫓아 살아가는 삶은 정답임을 잊지 말아야 한다.
8.인간(해석):
- 천년 동안 사탄이 무저갱에 갖혀있을 때 인간은 죄에서 자유로웠을 것이다. 하나님을 마음껏 찬양하고 경배할 수 있을 것 인데, 사탄이 무저갱을 나온 후 인간은 너무 쉽게 미혹되어 어둠의 길에 들어선다. 사탄이 가진 능력도 대단하지만 쉽게 무너지는 인간의 연약함도 대단한 것 같다. 나 또한 그럴 가능성이 높기 때문에 하나님의 보호하심을 구해야 한다.
9. 적용(나): 
- 천년 동안 자유로웠음에도 무너지는 인간의 연약함이 내 안에도 있다. 하나님의 보호하심으로 사탄과의 영적 전쟁에서 승리하는 삶을 살 수 있길 간절히 기도해야겠다. 
- 하나님께서 우리에게 특별한 사명을 주신 것은 엄청난 일이다. 수많은 영혼이 죽어가는 그곳을 우리에게 주신 하나님께 감사하다. 하나님께서 기뻐하시도록 노방전도에 집중해야겠다. 
10. 영적터치(단어/구절): 천년
11. 믿음과 회개 및 감사기도로 마무리', 0, true);

