1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
보좌: 11, 12
보니: 11, 12
죽은 자들: 12, 13(2)
자기 행위: 12, 13
생명책: 12, 15
책: 12(3)
펴: 12(2)
심판: 12, 13
기록: 12, 15
사망과 음부: 13, 14
불못: 14, 15

4.주제 만들기: 하나님의 심판

5.하나님 찾기 (관찰)
- 흰 보좌에 앉으신 하나님
- 죽은 자들의 행위대로 심판하시는 하나님

6.인간 찾기 (관찰)
- 죽은 자들이 흰 보좌 앞에 서서
- 자기 행위를 따라 책들에 기록된 대로 심판을 받음
- 생명책에 기록되지 못한 자는 불못에 던져질 것임.

7.하나님 찾기 (해석) 
- 심판의 하나님은 인간 행위를 지켜보신다.
- 지켜보실 뿐 아니라, 그 행위들을 책들에 기록하고 계신다.
- 그리고 언제일지 모르는 심판의 날 책들에 기록된 대로 심판하신다.
- 생명책에 기록되지 못한 사람은 모두 둘째 사망, 곧 불못에 던져질 것이다.

8.인간(해석): 
- 심판의 날에는 세상에서 큰 자나 작은 자나 구분 없이 
- 하나님 앞에 서서 자신의 행위들에 대해 심판을 받게 될 것이다.
- 세상 누군가는 ‘하나님은 없다.’ ‘내가 내 인생의 주인이다.’라고 주장하며 살아가고 있지만,
- 그들은 두렵고 떨리는 마음으로 하나님을 바라볼 줄 알아야 한다.
- 모든 사람의 행위는 하늘에서 기록되고 있으며,
- 심판의 날 그 기록된 내용에 따라 심판을 받을 것이다.
- 그리고 생명책에 기록되지 않은 모든 이는 불못에 던져질 것이다.

9.적용(나)
- 나와 내 가족, 내 친구들이 불못에 던져지지 않길 바라며,
- 늘 기도하며, 전도해야겠다.
- 내 가족과 내 친구들이 불못에 던져지는 것을 보길 원치 않는다.
- 그들이 하나님을 바라볼 수 있도록, 예수님을 생각할 수 있도록 
- 기도하며 반드시 전도해야 한다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-28', '요한계시록', '21장 1절 ~ 10절', '&nbsp;', '(요한계시록 21장)
1.  또 내가 새 하늘과 새 땅을 보니 처음 하늘과 처음 땅이 없어졌고 바다도 다시 있지 않더라
2. 또 내가 보매 거룩한 성 새 예루살렘이 하나님께로부터 하늘에서 내려오니 그 준비한 것이 신부가 남편을 위하여 단장한 것 같더라
3. 내가 들으니 보좌에서 큰 음성이 나서 이르되 보라 하나님의 장막이 사람들과 함께 있으매 하나님이 그들과 함께 계시리니 그들은 하나님의 백성이 되고 하나님은 친히 그들과 함께 계셔서
4. 모든 눈물을 그 눈에서 닦아 주시니 다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라
5. 보좌에 앉으신 이가 이르시되 보라 내가 만물을 새롭게 하노라 하시고 또 이르시되 이 말은 신실하고 참되니 기록하라 하시고
6. 또 내게 말씀하시되 이루었도다 나는 알파와 오메가요 처음과 마지막이라 내가 생명수 샘물을 목마른 자에게 값없이 주리니
7. 이기는 자는 이것들을 상속으로 받으리라 나는 그의 하나님이 되고 그는 내 아들이 되리라
8. 그러나 두려워하는 자들과 믿지 아니하는 자들과 흉악한 자들과 살인자들과 음행하는 자들과 점술가들과 우상 숭배자들과 거짓말하는 모든 자들은 불과 유황으로 타는 못에 던져지리니 이것이 둘째 사망이라
9.  일곱 대접을 가지고 마지막 일곱 재앙을 담은 일곱 천사 중 하나가 나아와서 내게 말하여 이르되 이리 오라 내가 신부 곧 어린 양의 아내를 네게 보이리라 하고
10. 성령으로 나를 데리고 크고 높은 산으로 올라가 하나님께로부터 하늘에서 내려오는 거룩한 성 예루살렘을 보이니

