7.하나님 찾기(해석)
알파와 오메가 이신 주님께서 마지막때에 악인과 선인을 구분하신다.
믿음의 길을 걸으면서 수많은 고난을을 통해 겪었던 주의 백성들에게는 큰 위로와 더불어 상속자로 삼아주신다.
그들과 더불어 영원한 새 하늘과 새 땅에 거하신다.
그곳은 더이상 고난과 고통 슲픔도 없는 아름다운 곳이다

반면 불신자들은 두번째 사망을 통하여 영원한 불과 유황으로 타는 못에 던져진다
심판의 하나님을 두려워하며 사는것이 복된  살이다

