4.주제 만들기: 거룩한 성 예루살렘

5.하나님 찾기 (관찰)
- 거룩한 성 예루살렘은 하나님의 영광이 있어,
- 그 성의 빛이 지극히 귀한 보석 같고 수정 같이 맑음

6.인간 찾기 (관찰)
- 크고 높은 성곽이 있고 
- 성문이 12개이며 문에는 이스라엘 열두 지파의 이름이 적혀있음
- 성곽에는 열두 기초석이 있고 그 위에는 어린 양의 열두 사도의 이름이 있음.
- 그 성은 네모반듯한 정육면체인데 그 길이는 약2400km이다.
- 성곽은 약65m인데 벽옥으로 쌍였고 
- 성은 정금인데 맑은 유리 같다.
- 성곽의 기초석은 12가지 보석으로 꾸몄다.

7.하나님 찾기 (해석) 
- 거룩한 성 예루살렘에는 하나님이 거하심
- 하나님이 계시기 때문에 그곳의 이름이 거룩한 성이며 천국임.
- 하나님이 계시지 않는다면 그곳이 아무리 아름답고 보석이 가득하더라도 
- 그곳은 거룩한 성도 아니며, 천국도 아님.
- 하나님이 계시기에 그곳이 거룩한 성이 되는 것임.
- 하나님은 말로 표현하기 힘든 아름다운 빛을 발하심.

8.인간(해석): 
- 끝까지 믿음을 지키면 
- 하나님의 영광이 가득한 거룩한 성 예루살렘에 거하게 된다. 

9.적용(나)
- 이 땅에 살면서 
- 찰나의 순간 천국을 맛본다.
- 그 찰나의 순간에, 천국에서 누리는 감정의 일부를 경험한다. 
- 음식을 먹기 전에 은은한 향기를 맡는 정도일까? 
- 그럼에도 나는 말로 표현하기 힘든 날아갈 듯한 기쁨을 느낀다.
- 놀라움과 기쁨이 뒤섞인 듯한 감정.
- 향기만 맡아도 이렇게나 기쁜데,
- 거룩한 성 예루살렘에 가면 어떤 기분이 들까?
- 하나님과 영원히 함께하는 천국을 바라보며 
- 믿음을 끝까지 지켜야겠다. 

10. 영적터치(단어/구절)  
  11   하나님의 영광이 있어 그 성의 빛이 지극히 귀한 보석 같고 벽옥과 수정 같이 맑더라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-07-31', '요한계시록', '21장 21절 ~ 27절', '생명책의 중요성', '[계21:21-27]
21 그 열두 문은 열두 진주니 각 문마다 한 개의 진주로 되어 있고 성의 길은 맑은 유리 같은 정금이더라
22 성 안에서 내가 성전을 보지 못하였으니 이는 주 하나님 곧 전능하신 이와 및 어린 양이 그 성전이심이라
23 그 성은 해나 달의 비침이 쓸 데 없으니 이는 하나님의 영광이 비치고 어린 양이 그 등불이 되심이라
24 만국이 그 빛 가운데로 다니고 땅의 왕들이 자기 영광을 가지고 그리로 들어가리라
25 낮에 성문들을 도무지 닫지 아니하리니 거기에는 밤이 없음이라
26 사람들이 만국의 영광과 존귀를 가지고 그리로 들어가겠고
27 무엇이든지 속된 것이나 가증한 일 또는 거짓말하는 자는 결코 그리로 들어가지 못하되 오직 어린 양의 생명책에 기록된 자들만 들어가리라

