2024년 7월26일 요한계시록 21장 21절~27절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 진주(21절), 성전(22절), 어린양(22,23,27절), 영광(24,26절), 들어가리라(24,26,27절) 
4.주제만들기: 생명책의 중요성
5.하나님 찾기 (관찰)
- 전능하신 이와 어린양이 성전이 되심
- 해와 달이 필요없이 하나님의 영광이 비치고 어린 양이 등불이 되심
- 어린 양의 생명책에 기록하심
6.인간 찾기 (관찰)
- 사람들이 만국의 영광과 존귀를 가지고 들어감
- 속된 것, 가증한 일, 거짓말하는 자는 들어가지 못함
7.하나님 찾기 (해석) 
- 하나님께선 우리를 구원하기 위해 인간의 몸으로 이 땅에 오셨고 십자가를 지심으로 세상을 구원하셨다. 우리를 위해 친히 성령을 주셨고 우리 안에 성전을 만드사 거하시는 은혜도 베푸셨다.
- 새 하늘과 새 땅에는 해와 달이 필요가 없는데 하나님의 영광과 예수님의 보호 아래 어둠은 완전히 사라지기 때문이다. 
- 어린 양의 생명책은 우리에게 소망을 준다. 우리가 맡은 사명을 잘 감당할 수 있는 힘이 된다. 하나님께선 우리를 위해 생명책을 준비하셨다.
8.인간(해석):
- 새 하늘과 새 땅엔 성문이 닫혀있지 않다. 그 곳은 어둠이 존재하지 않기 때문에 언제든 누구나 들어갈 수 있다. 참으로 감사한 일이다. 
- 반면 세상에서 속되고 가증한 일, 거짓말하는 자들은 새 하늘과 새 땅에 들어가지 못한다. 하나님께선 반드시 선과 악을 심판하는 분이시다.
9. 적용(나): 
- 새 하늘과 새 땅을 소망하며 감사한 마음으로 소명을 감당하고 싶다. 
- 하나님은 심판하시는 분이라는 것을 잊지 말고 하루 하루 살아가기 원한다.
- 속되고 가증한 일, 거짓말하는 자들로부터 미혹된 영혼들이 돌아올 수 있도록 또는 미혹되지 않도록 노방전도에 힘써야겠다.
10. 영적터치(단어/구절): 생명책
11. 믿음과 회개 및 감사기도로 마무리
