8 인간 찾기(해석)
사도요한은 보고 들은 은혜가 너무커서 하나님이 보낸 천사를 향하여 경배 하려고  했다. 그때 그 천사는 자신 또한 선지자 처럼 그저 하나님의 종 이라고 밣히며 사도요한어 과한 행동을 말렸다.

이 땅에서의 최고의 은혜를 받았다고 하더라도 이미 천국에 거하며 사는 천사들이나 선지자들이 체험하는 하나님에 대한 태도는 다소 차이가 있다고 볼수 있다

조그만한 죄와 그늘도 없는 완벽한 천국 은 온전한 하나님의 영광만 있는 곳임을 알게된다.

이 땅에 사는 동안 늘 겸손하며 주님만 바라보며 의지햐고 사는 인생이 가장 복된 인새민것을 깨우친다

속히 되어질일, 속히 오리라 하신말씀을 보면 하나님은 믿고 따르는 그의 자녀들이 세상에서 받는 고난을 원하지 않으심을 알수있다.

