거룩한 행위를 자는 거룩한 모습으로
아멘 주 예수여 오시옵소서 말하는 사도요한

7.하나님 찾기(해석)
마지막때는 새로운 세상에서 주님은 오직 그의 백성들과 더불어 속히 만나시기를 원하신다

한 영혼이라도 더 구원하시기 위해 오래참으시고 심지어 그의 자녀들이 세상에서 받는 고통을 감내하셨던 주님이시다. 그러하신 주님이 이제는 심판이 결정된 날에는 마음껏 그의 백성들을 빨리 보시기를 바라심을 알수있다.

8 인간 찾기(해석)
사도요한은 인간적인 측면에서 보면 실패자요 무능한 사람처럼 보여진다.
당시 대 제국 로마의 권세보다 힘없이 죽으신 예수의 복음의 길을 가고있었기  때문이다.

하지만 진리의 시각으로 보면 사도요한은 매우 지혜롭고 현명한 사람임이 분명하다

그는 예수그리스도께서  때가 되면 세상의 모든 권세자들 이라도 불신자들 이라고 하면 심판하시는 심판자 이심을 분명히 깨우치고 있었다

반면에 잠시 핍박 가운데 있는 믿음의 사람들이 주님으로 부터 받을 상급과 영광이 상상을 초월한다는 사실이다.

이제는 사도요한은 마지막 성경 요한계시록을 마무리하면서 자신과 모든 사람들에게 진리를 선포하고있다.
"여러분들이여 예수그리스도는 참다운 우리의 구원자 이시요 주인 이십니다. 그 분은 이제는 속히 오셔서 우리를 천국으로 인도하십니다. 우리도 세상의 욕심을 버리고 오직 그분을 의지하고 바라며 속히오실 그분을 간절히 기다립시다!!  아멘!!

9.적용(나):
속히 오실 예수를 바라며 믿음생활 더욱 잘해야겠다

