5.하나님 찾기 (관찰)
- 태초에 하나님이 천지를 창조하심
- 땅이 혼돈하고 공허하며 흑암이 깊음 위에 있지만 하나님의 영은 수면 위에 운행하심
- 하나님께서 빛을 만드심
- 빛과 어둠을 나누어 빛을 낮이라 부르시고, 어둠을 밤이라 부르심
- 물 가운데 궁창이 있어 물과 물로 나누심
- 궁창을 만드사 궁창 아래의 물과 궁창 위의 물로 나뉘게 하심
- 궁창을 하늘이라 부르심
- 천하의 물이 한 곳으로 모이고 뭍이 드러나라 하심
- 뭍을 땅이라 부르시고 물을 바다로 부르심
- 하나님께서 보시기에 좋으심
6.인간 찾기 (관찰)
7.하나님 찾기 (해석) 
- 하나님께서 천지를 창조하셨다. 진화론이 실존인 듯 창조론을 믿지 않는 사람들이 많아지고 있지만 하나님께서 창조하신 이 세상은 변하지 않는 진리이다.
- 하나님께선 혼돈 가운데 있는 이곳에 운행하시며 이 땅을 만드셨다. 어둡고 무질서한 이 땅에 하나님의 계획 아래 완벽한 세계가 탄생한 것이다.
- 하나님께서 빛을 처음 만드셨는데 어둠 가운데 있는 우리에게 주시는 소망의 빛과 같은 느낌이다. 하나님께선 빛을 만드시고 좋아하셨다. 그것은 우리를 위한 계획이 시작되었음을 생각해본다. 하나님께선 우리에게 빛과 같은 존재시고 하나님께선 본인의 존재를 매우 기뻐하셨다. 
- 빛이 생기므로 낮과 밤이 구분되게 되었다. 밝은 빛도 있으나 칠흙같은 어둠도 존재한다. 하나님께선 세상을 창조하심과 동시에 어둠도 알고 계셨다.
- 하나님께선 둘째날 하늘을 만드시고 땅과 바다를 만드셨다. 그리곤 좋아셨다. 하나님께선 인간들이 살아갈 세상을 만드시고 기뻐하셨다.  
8.인간(해석):
9. 적용(나): 
- 창조론은 비과학적이고 진화론이 과학적이라는 지성인들의 주장은 증명하지 못한 가설에 불가하다. 하나님께서 창조하셨다는 것을 인정할 수 있음에 감사 기도를 해야겠다. 
- 하나님께서 이 땅을 만드시며 기뻐하셨다는 사실에 감사하다. 나같은 죄인을 구원하시고자 세상을 창조하신 하나님께 감사와 영광 올려드린다.
