7.하나님 찾기 (해석) 
- 하나님은 시간과 공간을 만드시고 그 시공간을 채워가신다.
- 창조는 하나님의 계획대로 그리고 하나님이 말씀하신 대로 이루어진다.
- 하나님은 셋째 날과 넷째 날 창조하신 것들을 감상하며 좋아하셨다.
- 하나님은 오늘도 계획하신 대로 말씀으로 역사하고 계신다.
- 그리고 그 역사를 보시며 좋아하실 것이다.

