9.적용(나)
- 자녀에게 또는 사랑하는 사람에게 선물을 줬을 때 받는 사람이 기뻐하면 주는 사람의 마음이 얼마나 기쁜가.
- 하나님이 보시기에 좋은 것들을 보며, 누리며 나도 좋아해야겠다.
- 내가 감탄하거나 즐거워할 때마다 그 모습을 보고 하나님 아버지께서 기뻐하실 것이기 때문이다.
- ‘아들아 내가 만든 것들을 보며 네가 좋아하는 것을 보니 내가 너무나 기쁘구나.’
- 내가 보고 듣고 만지는 모든 시공간은 참으로 경이로운 것이다.
- 걷고 달리며 쉬고 자며 또는 누군가와 대화하며 늘 감사해야 한다.
- 그리고 나의 삶을 통해서 이루시는 하나님을 발견하며 기뻐해야 한다.
- 이것이 아들 된 도리이며 자세이다.
- 오늘도 하나님이 창조하신 시공간을 누리며,
- 하나님이 이루시는 것을 발견하고 기뻐해야겠다. 

