사람들에게 다스리는 역할을 주시는 하나님

6.인간 찾기 (관찰)

7.하나님 찾기(해석)
하나님은 모든 가축과 생물들을 창조하실때 방식으로는 ''종류''별로 하셨다. 그리고 좋아하셨다.

반면에 인간을 창조하실때는 종류별이 아닌 하나님 자신의 형상을따라 창조하셨다. 그리고 후에 심히 좋았다고 표현하셨다 하나님은 창조물 중에 최고의 걸작품을 인간 으로 삼으신 것이다.  그러한 최고의 피조물이 얼마나 좋으섰는지 그의 생기도 주시고 다른 피조물들도 다스릴 권한도 주셨다.
모든 만물을 다스릴 역할도  허락하셨다  얼마나 크신 하나님의 베푸심인가?

인간을 향하신 하나님!!  모든것을 주시는 하나님! 더 나아가서 죄에빠진 인간을 구원하시기 위해 자신을 십자가에 죽으셨던 주님!!

그러한 하나님이 나의 아버지 이심에 큰 감사와 찬양을 그분께 드릴수밖에 없다!!

8 인간 찾기(해석)
하나님의 형상대로 창조됐다는 의미는 분명 다른 피조물과 구분됨이 분명히 있다는 것을 알수있다. 

인간은 가축이나 다른 생물체가 없는 ''영'' 이 있음을 분명히 알고 육적인 만족감을 넘어선 영적 충만함을 추구하고 찾을때 비로써 창조된 목적을 발견하게된다고 할수있다.

그러므로 인간은 영적인 양식인 말씀과 영적호흡인 기도 그리고 하나님나라 번영을 위한 영혼구혼을 필수적인 하나님의 뜻 으로 알고 행할때 진정한스스로 살아있는 존재성을 발견할수 있다.

9.적용(나):
창조주 하나님과 늘 동행하는 삶을 살아야겠다 

10. 영적터치(단어/구절)
31절: 하나님이...보시기에 심히 좋았더라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

