7.하나님 찾기 (해석) 
- 휴식이 필요 없으신 하나님께서 육일 동안 천지를 창조하신 후에 안식을 하셨다. 
- 이 일곱째 날을 복되고 거룩하게 하셨다고 하는데, 
- 이것은 우리 인간을 위하여 복되고 거룩하게 하신 것이라고 볼 수 있다.
- 우리는 주일에 하나님을 예배하고 휴식을 취함으로 참된 안식을 조금이나마 맛볼 수 있다.
- 세상 속에서 하나님을 예배하고 휴식을 취하는 것이 복되고 거룩한 일이다.
- 하나님께서는 흙으로 사람을 지으시고 코에 생기를 불어 넣으셨다.
- 창조주 하나님의 작품 중에서 으뜸가며 귀하게 여기시는 작품이 우리 인간이다.
- 하나님은 우리 인간을 사랑하시고 인간에게 사랑받으시고자 우리를 창조하셨다.
- 우리는 이런 하나님을 찬양하는 생명체가 되어야 한다.
- 귀하디 귀하고 너무나 소중한 사람을 
- 에덴이라는 하나님이 일구신 최고로 좋은 동산에 두셨고
- 그 동산에는 먹기 좋은 열매를 맺는 좋은 나무로 가득했다. 
- 나쁜 것이라곤 하나도 없는 좋은 것으로 가득찬 곳 에덴.
