4.주제만들기: 지키라 명령하신 하나님
5.하나님 찾기 (관찰)
- 아담을 이끌어 에덴 동산에 두고 그것을 경작하며 지키게 하심
- 동산 각종 나무의 열매는 임의로 먹되 선악을 알게하는 나무의 열매는 먹지 말라고 명하심
- 흙으로 각종 들짐승과 공중의 각종 새를 지으심
- 아담이 그것을 무엇이라 부르는지 지켜보심
6.인간 찾기 (관찰)
- 각 생물을 부르는 것이 생물의 이름이 됨
- 아담에게 돕는 베필이 없음
7.하나님 찾기 (해석) 
- 하나님께선 인간을 만드셨고 에덴동산에 거하게 하셨다. 그리곤 에덴동산에서 경작하며 지키게 하셨는데 에덴동산엔 먹을 것이 충분했지만 하나님께선 경작하고 지키게 명하신 것은 인간이 자유의지를 선하게 이용할 수 있도록 훈련을 시켜주셨다. 
- 선악과를 두심으로 하나님의 존재를 인식하게 하셨고, 하나님을 의지하게 하셨는데 각종 생물을 만드시고 아담이 어떻게 부르는지 보시는 것처럼, 선악과를 두고 인간이 어떻게 하실지 지켜보셨을 것이다. 그것은 인간을 테스트하기 위함이 아니라, 인간이 하나님을 의지하기 바라는 마음으로 보호하시기 위해 지켜보셨을 것이다. 
8.인간(해석):
- 인간은 자유롭게 생물의 이름을 정했다. 하나님께서 주신 자유의지, 아담에게만 주어진 것이 아니라 오늘을 살아가는 모두에게 주어진 것이다. 하나님께선 우리를 지켜보고 계시고 하나님께서 주신 것들을 잘 지키길 원하신다. 그리고 우리를 보호하신다.
9. 적용(나): 
- 하나님께서 에덴동산을 인간에게 주시고 그것을 지키길 원하셨다. 하나님을 믿는 믿음과, 자녀의 양육, 직장에서의 역할과 하나님께서 명령하신 소명을 잘 지켜야겠다.
- 하나님께서 내게 주신 것들이 참으로 많음을 감사하고 그것을 자유롭게 이용할 수 있는 권한도 주셨지만 선하게 지켜야 하는 것을 깨닫는다. 하나님을 의지하여 주어진 것들을 선하게 사용하여야겠다.
