4.주제만들기: 
불순종 하여 선악과를 먹은 아담과 하와

5.하나님 찾기 (관찰): 
에덴 동산에 거니시는 하나님
숨은 아담을 부르시는 하나님 

6.인간 찾기 (관찰)
선악과를 따먹은 아담과 하와
선악과를 먹으라고 유혹한 뱀
원죄를 행한후 부끄러움을 느끼는 최초의 인간들
원죄를 행한후 하나님의 낯을 피하여 나무 사이에 숨는 아담과 하와

7.하나님 찾기(해석)
하나님은 에덴동산 중앙에 선악과를 두신 이유는  무엇일까?
이성적으로 생각하면 이해하기 쉽지않지만 깊이 묵상하면 쉽게 알수있다.

하나님은 스스로 창조자 이심을 인간을 통하여 알리기를 원하신다. 또한 그분의 생기를 인간에 주신것처럼 영적으로 관계성을 갖기를 원하셨기때문이다.

선악과는 단순하게 인간을 테스트하기 위한 용도가 아닌 창조주 "하나님"이라는 존재성을 인간스스로가 지각하며 인지하도록 알리기위한 바로미터  같은 도구인것이다. 

원죄를 행한후 두려움과 부끄러움속에 숨어 있는 인간들을 향하여 다가오시고 찾으시는 하나님의 성품을 볼수있다.

하나님의 자녀라고 하더라도 실수로 죄를 짓게 됐을경우라도 숨지말고 용기를 내어 주님께 회개하고 나아가는 자세가 영적회복을 위한 자세라 보여진다

8 인간 찾기(해석)
사탄은 인간의 성공을  화려함(명예 돈 학위 인기등)으로 마음속에 유혹을 이 시대에도 속삭이고 있다.

인간의 참된 성공은 창조주 하나님을 진심으로  매순간 인정하고 주인으로 받아들이는 모습이라 확신한다

그러한 삶을 살아가는 사람은 하나님이 최초의 인간들에게 공급한 선악과가 아닌 ''생명의 과실''을 먹는 모습이라 볼수있다 

9.적용(나):
하나님을 더욱 인지하며 살아야겠다 

10. 영적터치(단어/구절)
9절: 네가 어디있느냐

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

