2024년 8월5일 창세기 3장 11절~24절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-나무 열매(11,12,17,22,24절), 먹다(11,12,13절), 먹지말라 명한(11, 17절)뱀(13,14절), 여자(13,15,16,17절), 에덴동산(23,24절), 생명 나무(22,24절), 흙(14,19절)
4.주제만들기: 하나님의 명령을 지키지 못한 결과, 그럼에도 사랑하시는 하나님
5.하나님 찾기 (관찰)
-벌거벗음을 누가 알려주었는지 물으시는 하나님
-뱀에게 저주를 내리시는 하나님
-여자에게 임신의 고통을 더하시고 남편이 다스릴 것이라 말하심
-아담에게 땅은 아담으로 인해 저주를 받고 평생 수고해야 소산을 먹을 수 있다고 말하심
-흙으로 돌아갈 때까지 땀을 흘려야 먹을 것을 먹으리라 말하심
-아담과 하와를 위해 가죽옷을 지어 입히심
-아담과 하와를 에덴 동산에서 내쫓으심
-불 칼을 두어 생명 나무의 길을 지키게 하심
6.인간 찾기 (관찰)
-선악과를 먹은 이유를 하나님이 주신 여자가 주어 먹었다 변명하는 아담
-아담이 여자의 이름을 하와라 부름
7.하나님 찾기 (해석) 
-하나님께선 이미 알고 있는 사실을 아담에게 물어본 것은 어쩌면 아담이 하나님 앞에 죄를 고백할 수 있는 기회를 주셨을 수도 있다. 그러나 인간은 하나님의 탓인 것처럼 변명하는 또다른 죄를 지었다. 
-하나님은 인간을 즉시 처벌할 수 있지만 그러지 않으시고 원죄를 찾으셨다. 여자를 유혹한 뱀에게 저주를 내리고 여자의 후손을 통해 머리가 상하게 하리라고 말씀하셨다. 뱀에게 속은 여자를 위해 하나님이 직접 갚아주시고자 하신 것이다. 
-하나님은 자신이 만드신 인간을 사랑하셨지만 명령을 어긴 일에 대해선 책임을 주셨다. 여자는 임신의 고통을 크게 하셨고, 남자는 일을 해야 소산을 먹도록 하셨다. 죄가 없었다면 임신으로 인한 출산의 고통도 수고해서 일을 해야하는 수고로움도 없었을 것이다. 하나님이 조건 없이 우리에게 주신 환경이 얼마나 대단했는지 생각해본다. 하지만 인간은 연약하기에 그러한 환경에서도 누군가가 또 죄를 지엇을 것 같다.
-죄지은 인간을 위해 하나님은 직접 가죽 옷을 만드셔서 입히셨다. 하나님의 사랑은 인간이 해석할 수 없다.
8.인간(해석):
-아담은 하나님의 질문에 하나님을 탓하는 듯한 변명을 했다. 아담의 모습은 내 모습과도 같다. 죄를 지을 때 마다 환경과 상황 탓을 하는 어리석은 내 모습 
9. 적용(나): 
-하나님이 우리를 얼마나 사랑하시는지 매일 매일 묵상하며 하나님의 사랑에 감사해야겠다. 
-원죄의 해결 없인 죄를 없애기 힘들다. 하나님의 은혜로 죄에서 벗어나길 기도한다.
-하나님께서 인간을 얼마나 사랑하시는지 많은 사람들이 알았음 좋겠다. 전도에 힘써야겠다.
10. 영적터치(단어/구절)
-15절 여자의 후손을 네 머리를 상하게 할 것이요
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

