2024년 8월 6일 창세기 4장 1~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
가인: 1, 2(2), 3, 5(2), 6, 8(2), 9
여호와: 1, 3, 4, 6, 9
아벨: 2, 4(2), 8(2), 9
