안색이 변함: 5, 6
선을 행함: 7(2)
죄: 7(3)
아우: 8(2), 9(2), 10

4.주제 만들기: 죄의 결과, 가인과 아벨

5.하나님 찾기 (관찰)
- 하나님께서 아벨과 그의 제물을 받으셨으나 
- 가인과 그의 제물은 받지 않으심
- 가인을 책망하시는 하나님
- 가인에게 아벨이 어디 있느냐 물으심
- 무엇을 하였느냐 물으심

6.인간 찾기 (관찰)
- 하와가 임신하여 가인을 낳고 하나님을 찬양함
- 하와가 아벨을 낳음
- 아벨은 양치는 자로서 양의 첫 새끼와 그 기름으로 하나님께 제물을 드림
- 가인은 농사하는 자로서 땅의 소산으로 하나님께 제물을 드림
- 하나님께서 아벨과 그의 제물을 받으셨으나 
- 가인과 그의 제물은 받지 않으심으로 인해
- 가인은 몹시 분하여 안색이 변함
- 하나님의 책망하심을 듣는 가인
- 아벨을 쳐 죽이는 가인 
- 아벨이 어디 있느냐 물으시는 하나님께 대드는 가인

7.하나님 찾기 (해석) 
- 양을 치면서 가장 소중한 첫 새끼와 그 기름을 드린 아벨.
- 하나님은 아벨이 드린 제물과 아벨의 제물을 드릴 때의 마음가짐, 
- 그리고 아마도 평소 양을 치며 기뻐하면서 하나님을 찬양한 아벨을 받으신 것.
- 가인과 땅의 소산으로 드린 제물은 받지 않으신 것은
- 소산을 하나님께 드렸으나, 
- 첫 소산을 드리지 않은 가인의 마음가짐과 
- 아마도 평소 농사지을 때의 불평 등을 받지 않으신 것.
- 분해하는 가인을 책망하시며 죄를 깨닫게 하고 회개할 기회를 주시는 하나님
- 아벨을 죽인 가인에게 죄를 고백하고 회개할 기회를 주시는 하나님

8.인간(해석): 
- 처음으로 임신하고 가인을 낳는 과정을 거치면서
- 하와는 큰 기쁨을 누렸을 것이며, 하나님의 도우심에 감사가 넘쳤을 것이다.
- 그래서 하와는 하나님이 아들을 주셨다며 하나님을 찬양하였다.
- 가인은 농사를 지으며 ‘부모님의 죄로 인해 내가 이렇게 힘든 노동을 하게 되었다.’ 생각하는 등 불평이 많았을 것이다.
- 가인은 노동을 즐거워하지 못했기 때문에, 
- 하나님을 사랑하지 않았기 때문에, 
- 가인은 첫 소산을, 가장 귀한 것을 하나님께 드리지 못했다.
- 아벨은 아마도 양을 치며 소소한 기쁨과 보람을 누렸을 것이다.
- 양을 치면서 첫 새끼를 받은 큰 기쁨을 누렸을 것이며, 
- 첫 새끼를 하나님께 드림으로 하나님이 자기의 주인이심을 고백한 것.
- 하나님이 아벨과 그의 제물은 받고 가인과 그의 제물은 받지 않으시자,
- 가인은 하나님도 싫고 아벨도 싫었을 것.
- 자기를 인정해 주지 않은 하나님이 아벨은 인정해 주시자 분노가 일었을 것.
- 하나님께 인정받은 아벨에게 질투와 시기가 일어났을 것
- 가인의 이런 태도를 하나님이 책망하시지만, 회개하지 않음.
- 가인은 부정적인 감정과 생각들을 이기지 못하고 아벨을 죽임
- 죄의 고백과 회개를 거부하고 악한 결정을 계속하는 가인  

9.적용(나)
- 가인의 모습은 내게도, 인류의 모두에게도 마음속 어딘가에 있을 것이다.
- 어쩌면 가인이 저지른 죄보다 더 더럽고 악한 것이 내 마음속 어딘가에 있을 것이다.
- 가인의 모습이 아니라,
- 아벨의 모습을 닮을 수 있도록,
- 하나님을 사랑하고 맡기신 일에 만족하며 감사하는 삶을 살아가도록 노력해야겠다.
- 임용고시에 합격 후 3월 첫 봉급을 하나님께 드렸던 때가 생각난다.
- 그때 그 마음을 찾아야겠다.
- 비록 아벨과 같지는 못하겠으나, 
- 하나님을 즐거워한 아벨을 따라가려고 노력해야겠다.

10. 영적터치(단어/구절)  
  4   아벨은 자기도 양의 첫 새끼와 그 기름으로 드렸더니 여호와께서 아벨과 그의 제물은 받으셨으나

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-08-13', '창세기', '4장 11절 ~ 20절', '', '(창세기 4장)
11. 땅이 그 입을 벌려 네 손에서부터 네 아우의 피를 받았은즉 네가 땅에서 저주를 받으리니
12. 네가 밭을 갈아도 땅이 다시는 그 효력을 네게 주지 아니할 것이요 너는 땅에서 피하며 유리하는 자가 되리라
13. 가인이 여호와께 아뢰되 내 죄벌이 지기가 너무 무거우니이다
