7.하나님 찾기(해석)
동생 아벨을 죽인 가인은 완전범죄 라고  생각할수 있었을 것이다. 하지만 전능하신 하나님은 아벨의 피를 받은즉 가인에게 저주를 내리신다. 그러므로 가인은 세상에서 유랑하는 인생으로 전락한다. 
가인은 스스로 정죄를 받고 다른 사람들로부터 자신이 저지른 것처럼 죽임을 당할것이라는 불안감을 갖는다.
그러한 가인에게 최소한 육신의 살인을 받지 않을 것이라는  표를 하나님은 주셨다. 

8 인간 찾기(해석)
최초의 살인을 저지른 가인은 내면적으로 죽음의 공포와 외적으로는 하나님을 떠나 유랑하는 저주를 받는다.
가장 큰 저주는 하나님을 떠나 살아가는 인생일것이다.  가인은 조그만하게 시작한 시기질투가 의인 아벨을 죽이고 이제는 돌이킬수 없는 비참한 인생을 살아간다.  
나도 조그만한 마음속에 죄의 씨앗들이 있는지 늘 점검하고 또 확인하는 일을 부지런하게 해야겠다.
발견되면 십자가의 보혈로 늘 씻는 자세가 매우  중요함을 깨우친다. 가장 큰 복은 주님의 임재를 경험하고 그분과 동행하는 것임이 확실하다.

9.적용(나):
늘 스스로를 성찰하며 겸비하는 삶을 살아내야겠다 

