5.하나님 찾기 (관찰)
- 사람을 창조하심
- 하나님의 모양대로 지으시고 남자와 여자를 창조하심
- 인간을 창조한 날 그들에게 복 주시고 사람이라 부르심
6.인간 찾기 (관찰)
- 아담의 족보
- 아담은 셋을 낳고 셋은 에노스를 낳고 에노스는 게난을 낳고 게난을 자녀들을 낳음
7.하나님 찾기 (해석) 
- 하나님께선 우리를 창조하셨고 남자와 여자를 만드셨다.
- 우리를 만드실 때 하나님의 형상대로 만드셨는데 하나님의 형상을 따르는 복을 이미 받았음에도 사람이라 부르시고, 복을 주심
- 하나님은 우리를 만드신 것을 기뻐하신 것에 그치지 않고 복까지 주셨다. 우리의 존재 자체가 하나님의 기쁨이다.그리고 우린 복된 존재다.
8.인간(해석):
- 하나님의 형상대로 지음을 받은 아담의 족보는 자기의 모양, 자기의 형상과 같은 셋을 낳았다는 것으로 시작한다. 이것은 하나님으로부터 창조 받은 정체성을 의미하는 것 같은데, 내가 자녀를 낳으면 나의 모습을 닮은 것 같이 우리는 하나님의 모습을 닮았다.
- 자녀는 부모의 영향을 많이 받는데 어느 새 부모님과 같은 외형과 성격을 닮아있는 자신을 볼 수 있다. 그런데 우리는 왜 하나님을 닮아가진 못할까? 그것은 하나님과 가까이 있지 않기 때문이다. 매일 보는 가족처럼 하나님을 매일, 매시간 보아야 하나님을 찾지 않기 때문에 하나님을 닮아가는 것은 어렵다. 매일 하나님을 만난다면 우리는 하나님을 닮은 삶을 살아갈 것이다. 그것이 가능한 이유는 하나님께서 자신의 형상대로 지으셨고 복을 주셨기 때문이다.
9. 적용(나):
- 하나님께서 나를 창조해주신 것에 감사드린다.
- 우리는 하나님의 형상대로 지음 받았음을 잊지 말고 선한 하나님의 모습을 닮아가도록 노력해야겠다.
- 나를 통해 하나님을 느낄 수 있도록 노력해야겠다. 
