7.하나님 찾기(해석)
아담의 후손들의 끊어지지 않는 계보를 보면서 보이지 않는 하나님의 둘보심을 깨우친다

이시대에 살고있는 우리도 마찬가지로 하루하루 무탈하게  세월을 보낼수 있는것은 하나님의 보호하심을 기억해야 될것이다. 무탈하게 보낸 하루또한 기적의 하루이다.

8 인간 찾기(해석)
그 당시는 대부분의 사람들이 장수한것을 볼수있다. 대략 구백세 때까지 살았다. 그리고 자녀를을 보통 육 칠십세  쯤 출산  하였다. 

그런데 유달리 에녹의 아버지인 야렛은 백육십이 세에 에녹을 그의 아내가 출산했다 기록되어있다.

야렛은 그의 부모나 조부모보다 첫 아이 출산이 약 100년이나  늦게 가진셈이다.

야렛은 나름 오랜시간을 불평하지 않고 인내하여 끝내 기다림의 열매로 믿음의 의인인 "에녹"을 선물로 받았다.

9.적용(나):
평범한 일상생활 속에서 기적의 하나님께 늘 감사하며 기쁨으로 살아내야겠다 

