7.하나님 찾기(해석)
에녹과 더불어 300년동안 동행하신 하나님이 에녹을 하늘로 들어올리셨다.

모든 인류의 인간을 포함한 생물들은 반드시 죽음을 숙명처럼 겪음에도 에녹은 기본법칙에서 벗어났다.

전능하신 하나님의 능력을 제한할 어느존재가 없다.

8 인간 찾기(해석)
에녹은 당시 동시대에 살았던 사람들보다는 세상에서 짧은 삶을 살았다. 그러나 다른 사람들이 겪었던 죽음을 맛보지 않고 하나님 나라로 올라가는 특권을 가졌다. 세상에서 장수하는 삶이 반드시 복된 인생이 아니고 주님과 늘 동행하는 삶이 복된 인생임을 알수있다.

에녹은 65살 까지는 하나님과 동행하는 삶을 살지 못했지만 66살에 첫아이를 낳은 이후에 하나님과 동행하는 복돠 인생으로 거듭났다. 구체적으로 성경에는 기록되어 있지않지만 분명 그는 하나님을 전적으로 신뢰하고 교제하는 계기가 있었을 것이다!!

하나님은 자신을 진심으로 찾고 의지하는 에녹을 만나주시고 동행하여 주셨을 것이다.

9.적용(나):
에녹같이 늘 주님과 동행하는 삶을 살도록 노력해야겠다 

