2024년 8월13일 창세기 6장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 사람(1,2,3,4,5,6,7절), 하나님의 아들들(2,3,4절), 딸들(1,4절), 한탄(6,7절), 지었음(6,7절)
4.주제만들기: 사람 지으셨음을 한탄하신 하나님
5.하나님 찾기 (관찰)
- 여호아의 영이 영원히 사람과 함께 하지 아니하실 것을 말씀하시고
- 하나님의 아들들이 육신이되며 백이십년이 될 것이라 말하심
- 사람의 죄악이 세상에 가득하고 마음으로 생각하는 모든 계획이 항상 악할뿐임을 보시고
- 땅 위에 사람 지으셨음을 한탄하심
- 마음에 근심하시고 창조한 사람을 지면에서 쓸어버릴 것을 말하심
- 그 대상에는 가축과 기는 것과 공중의 새까지 포함됨
6.인간 찾기 (관찰)
- 하나님의 아들들이 사람의 딸들의 아름다움을 보고 자기가 좋아하는 여자들을 모두 아내로 삼음
- 땅에는 네피림이 있었고 하나님의 아들들이 사람의 딸들에게 들어와 자식을 낳음. 그들은 용사고 고대의 명성이난 사람들임
- 노아는 여호와께 은혜를 입음
- 노아는 의인이고 당대 완전한 자였으며, 하나님과 동행하였음
- 세 아들을 낳았는데 셈과 함과 야벳임
7.하나님 찾기 (해석) 
- 하나님께서 아담과 하와를 불쌍히 여기고 가죽 옷을 지어주셨음에도 불구하고 인간은 하나님을 쉽게 잊는 존재다. 여러 족보를 거쳐 노아의 시대에는 하나님을 의지하는 하나님의 아들들은 노아를 제외하곤 없었다. 그들은 어리석게도 인간의 딸들의 아름다움에 현혹되어 멋대로 아내를 취하는 선택을 하여 하나님과 점점 멀어졌다.
- 마치 아담과 하와가 선악과를 먹었던 것처럼 인간은 유사한 선택을 한다. 하나님의 마음이 얼마나 아프셨을까... 지금 시대는 다르지만 같은 모습과 행동을 보이는 나의 행동에 하나님은 얼마나 마음이 아프셨을까?
- 하나님께선 한탄하시고 마음에 근심하실 정도로 가슴 아파하셨다. 죄라는 것이 그렇다. 죄의 뿌리까지 뽑지 않는다면 죄는 반복된다. 그렇기 때문에 지면에 있는 모든 것을 없앨 수 밖에 없다. 그것으로 인해 하나님께선 근심하셨다.
- 하나님께선 노아에게 은혜를 주셨다.  
8.인간(해석):
- 인간은 반복된 죄를 지었다. 몇 세대를 지난 후 하나님과의 관계는 느슨해졌다. 하나님과의 관계가 느슨해지자 여지없이 죄를 선택한다. 
- 그러나 하나님께선 노아를 선택하시고 은혜를 부어주셨다. 노아는 의인이었고 완전한 자였는데 하나님과 동행할 정도였다고 하니 노아가 어떤 사람이었는지 알 수 있을 것 같다. 내가 생각했던 것보다 더 위대한 사람이었다. 나는 성령님과 함께 하는 특권을 누리고 있는데 과연 성령님이 동행하심을 느끼며 살고 있을까?
9. 적용(나): 
- 악함 중에도 선은 있다. 선을 지킬 수 있는 것은 하나님의 은혜다. 선을 지킬 수 있도록 기회를 주심에 감사드리고 선을 지키기 위해 노력해야겠다.
- 하나님을 모르는 영혼이 많은 이 세대를 하나님께선 얼마나 가슴 아파하실까? 인간을 위해 하나님이신 자신이 이 땅에 내려와 십자가로 인간의 죄를 대속하셨음에도 변하지 않는 인간을 보며 어떤 생각을 하실까? 하나님을 영접하는 영혼, 하나님께 돌아오는 영혼들이 생기도록 맡겨주신 사역에 더욱 힘써야겠다.
10. 영적터치(단어/구절)
-5 여호와께서 사람의 죄악이 세상에 가득함과 그의 마음으로 생각하는 모든 계획이 항상 악할 뿐임을 보시고
-6 땅 위에 사람 지으셨음을 한탄하사 마음에 근심하시고
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

