- 혈육 있는 모든 생물을 각기 암수 한 쌍씩 방주에 태우라고 하심
- 먹을 모든 양식을 저축하라고 하심

6.인간 찾기 (관찰)
- 사람과 땅이 썩어버림
- 노아가 하나님의 명령대로 다 준행함

7.하나님 찾기 (해석) 
- 부패하여 냄새가 진동하는 땅과 사람을 보시며 한탄하셨고
- 포악함이 땅에 가득하므로 그 끝 날이 내 앞에 이르렀다 말씀하심
- 우리는 포악함에 대해 주의하며 생각하고 나와 사회의 포악함을 조심해야 한다.
- 노아에게 방주를 짓게 하시되 설계도를 주시고,
- 모든 동물을 종류별로 방주에 태우도록 명령하시되 
- 모든 것이 그 종류대로 노아에게 나아오게 하심
- 하나님은 부르시고 사명을 주시되,
- 사람이 할 수 있도록 안내하시고, 사람이 할 수 없는 일은 하나님이 직접 해 주심. 

8.인간(해석): 
- 인간은 하나님을 찾지 않으면 부패하고 포악해지는 존재이다.
- 하나님을 찾지 않고 자기가 하고 싶은 대로 살면, 
- (그 시작은 즐거울지 모르겠으나) 그 끝은 포악함이라는 것이다.
- 노아가 하나님이 자기에게 명령하신 대로 다 준행한 것처럼.
- 사명자는 하나님의 명령에 순종해야 한다.

9.적용(나)
- 내 삶에서 하나님이 없는 삶과 포악함에 대해 생각해 봐야 한다.
- 하나님을 만난 이후에 하나님과 깊이 교제하고 성령 충만할 때의 내 모습과 
- 예배 시간이 줄어들고 삶에 지쳐있을 때의 내 모습을 비교해 보면,
- 성령 충만과 포악함은 반비례함을 알 수 있다.
- 하나님은 나를 부르시고, 사명을 주셨다.
- 하나님이 허락하신 이 시간과 공간 속에서 
- 나는 성령 충만함으로 살 것인가 포악함으로 살 것인가 선택해야 한다.
- 성령 충만한 삶을 살고 싶다.
- 하나님을 근심하게 하지 않고, 기쁘게 해 드리는 한 사람으로 살아야겠다.
- 하나님은 부르시고 사명을 주실 때,
- 알아서 하라고 하시지 않는다.
- 노아에게 하신 것처럼 설계도를 주시고
- 사람이 할 수 없는 일은 하나님이 직접하신다.
- 사명자는 이것을 믿고 그저 할 수 있는 것을 꾸준히 하면 된다.
- 하나님의 말씀대로 준행하는 삶을 살아야겠다.

10. 영적터치(단어/구절)  
  22   노아가 그와 같이 하여 하나님이 자기에게 명하신 대로 다 준행하였더라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-08-20', '창세기', '7장 1절 ~ 10절', '&nbsp;', '(창세기 7장)
1.  여호와께서 노아에게 이르시되 너와 네 온 집은 방주로 들어가라 이 세대에서 네가 내 앞에 의로움을 내가 보았음이니라
2. 너는 모든 정결한 짐승은 암수 일곱씩, 부정한 것은 암수 둘씩을 네게로 데려오며
3. 공중의 새도 암수 일곱씩을 데려와 그 씨를 온 지면에 유전하게 하라
4. 지금부터 칠 일이면 내가 사십 주야를 땅에 비를 내려 내가 지은 모든 생물을 지면에서 쓸어버리리라
5. 노아가 여호와께서 자기에게 명하신 대로 다 준행하였더라
6. 홍수가 땅에 있을 때에 노아가 육백 세라
7. 노아는 아들들과 아내와 며느리들과 함께 홍수를 피하여 방주에 들어갔고
8. 정결한 짐승과 부정한 짐승과 새와 땅에 기는 모든 것은
9. 하나님이 노아에게 명하신 대로 암수 둘씩 노아에게 나아와 방주로 들어갔으며
10. 칠 일 후에 홍수가 땅에 덮이니

