암수: 2절(2) 9절
정결한 짐승: 2절 8절
부정한 짐승: 2절 8절
홍수: 6절 7절 10절

4.주제만들기: 
홍수

5.하나님 찾기 (관찰)
홍수를 내시는 하나님
노아의 의로움을 보신 하나님
노아에게 그의 가족들과 종류별 동물  암수로 방주로 들어가라 말씀 하시는 하나님

6.인간 찾기 (관찰)
방주에 들어가는 노아와 그의 가족들
하나님 말씀에 순종하여 모든 동물 종류별로 방주로 들여보낸 노아

7.하나님 찾기(해석)
거룩하신 하나님은 의로운 노아와 그의 가족을 제외한 모든 사람들을 물로 심판하셨다.

그런데 거룩하신 하나님은 왜 방주에 부정한 짐승을 구태여 들여보내셨을까?

아마도 하나님은 노아가 부정한 동물을 보면서  비교 대상인 완전하신 하나님 거룩하신 하나님을 더욱 의지하게 함이 아닌가 생각해본다.

8 인간 찾기(해석)
암흑같은 죄가 범람한 세상가운데에서도 하나님께 의인 이라 칭찬 받은 노아가 있음을 보게된다.

노아에게는 아들 세명과 며느리가 세명 있었는데 어쩌면 아빠를 노아로둔 자녀들과 시아버지를 노아로 둔 며느리들은 노아로 인하여 구원의 축복을 받지 않았나 생각하게 된다.

한 가족 한공동체 안에서 강력한 의인 한명이 줄수있는 생명의 영향력은 결코 간과할수 없을것이다.

나도 그러한 선한 영향력을 나눌수 있는 주님의 자녀가 되고싶다.

9.적용(나):
노아같이 주님께 의로움을 나타낼수 있는 자녀가 되도록 더욱 노력해야겠다 

10. 영적터치(단어/구절)
1절: 내 앞에 의로움을 내가 보았음이니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

