4.주제 만들기: 하나님의 심판

5.하나님 찾기 (관찰)
- 노아의 가족과 모든 생물이 그 종류대로 노아에게 나아왔고 방주에 들어갔다.
- 노아가 마지막으로 들어갔으며, 하나님께서 방주의 문을 직접 닫으셨다.
- 사십 주야 동안 홍수를 내리셨다.

6.인간 찾기 (관찰)
- 노아의 가족은 방주에 탔고
- 홍수는 사십 주야 동안 내렸다.
- 홍수로 인해 방주에 타지 못한 모든 사람과 코로 숨을 쉬는 모든 생물은 죽었다.

7.하나님 찾기 (해석) 
- 말씀하신 대로 모든 종류의 생물이 노아 앞에 한 쌍씩 나아오게 하셨다.
- 하나님은 말씀하신 것을 이루시는 분이시다.
- 노아를 방주에 마지막에 태우시고, 
- 문을 직접 닫으셨다.
- 방주를 보호하시는 이는 하나님이시라는 것을 보여준다.
- 아마 늦게나마 방주에 타려고 사정하거나, 또는 발악하는 사람들이 있었을 것이다. 
- 그들은 여호와의 손으로 굳게 닫힌 문을 열 수는 없었을 것이다.
- 부수려고 해도 부술 수가 없었을 것이다. 

8.인간(해석): 
- 하나님의 말씀대로 모든 종류의 생물이 한 쌍씩 나아오는 것을 보며
- 노아는 하나님의 위대하심을 절실히 느꼈을 것이다.
- 문을 직접 닫아주신 하나님을 경험하며 
- 이 방주는 앞으로 안전하다는 것을 느꼈을 것이다.
- 첫째는 방주로부터, 둘째는 공격하는 사람으로부터.
- 엄청난 훙수와 폭풍 속에서 하나님의 위대하심을 몸으로 체험하며 전율했을 것이다.
- 하나님 없이 큰소리 치며 살다가 홍수를 맞은 사람들은,
- 특히 권력자들은 방주를 부수고 들어와 살고자 했을 것이다.
- 그러나 하나님의 심판은 사람의 힘으로 벗어날 수 있는 것이 아니다.

9.적용(나)
- 하나님의 위대하심을 노아만큼 느껴본 사람이 있을까?
- 아마도 생전에는 그 누구도 노아만큼 느껴본 사람이 없을 것이다.
- 죽고 나서야 하나님 앞에 서서 하나님의 위대하심을 제대로 경험할 것이다. 노아가 홍수 당시 느꼈던 것과는 비교가 되지 않는 그 위대하심을 말이다.
- 나는 하나님이 얼마나 위대하신지 알지 못한다.
- 그저 내가 생각하는 만큼, 경험한 만큼만 느낄 뿐이다.
- 위대하시고 광대하신 하나님을 조금 더 느낄 수 있도록 
- 오늘부터 힘을 내어 기도해야겠다.

10. 영적터치(단어/구절)  
   16   들어간 것들은 모든 것의 암수라 하나님이 그에게 명하신 대로 들어가매 여호와께서 그를 들여보내고 문을 닫으시니라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

