5.하나님 찾기 (관찰)
- 노아와 들짐승, 가축을 기억하심
- 바람을 땅 위에 불게 하시고 물이 줄어듦
- 깊음의 샘과 하늘의 창문이 닫히고 하늘에서 비가 그침
- 물이 땅에서 물러남
6.인간 찾기 (관찰)
- 노아는 방주에 만든 창문을 열고 까마귀를 놓음
- 까마귀는 물이 마르기까지 방주를 왕래함
- 노아는 비둘기를 내놓아 물이 줄어들었는지 확인함
- 비둘기는 발 붙일 곳이 없어 다시 방주로 돌아옴
- 칠일 후 노아는 다시 비둘기를 내보냄
7.하나님 찾기 (해석) 
- 하나님께선 인간과 들짐승, 가축들을 기억하시고 구원하신다. 하나님께서 기억하신다는 것은 우리에게 큰 의미가 될 것이다. 고통스러운 고난 가운데 있거나, 절망스러운 날들로 앞이 보이지 않을 때 하나님께선 우리를 기억하고 계신다. 그리고 우리를 보호하사 노아의 홍수처럼 땅 위에 물들을 없애주신다. 
- 하나님께선 방주를 아라랏 산에 머물게 하셨다. 비가 그친 후 두려움에 있는 인간이 하나님의 보호 아래 있음을 깨닫게 하시고자 배려하신 것 같다. 정처 없이 떠도는 배가 아닌 하나님의 구원 계획 아래 있는 배는 하나님의 보호하심을 의지하고 하나님께서 물을 없애실 때를 기다리게 되었을 것이다.
8.인간(해석):
- 노아는 창문을 통해 상황을 확인한다. 노아의 홍수가 지나고 비가 그치고 물이 빠지기까지 하나님을 재촉할 수도 있었다. 그러나 노아는 하나님의 구원의 시간을 전적으로 의지하고 순종한다. 하나님께서 물을 지면에서 없애기 까지 묵묵히 기다린다.
9. 적용(나): 
- 하나님이 우리를 위해 때를 위해 기도한다. 각자마다 다르게 흐를 시간을 위해 묵묵히 자신의 일을 감당하며 하나님을 의지하는 귀한 NKFC 공동체가 되길 소망한다. 
- 하나님께서 우리를 보호하시는 것에 감사한다. 담대히 맡겨주신 소명을 감당하고 싶다.
