그리고 다시는 인간의 죄로인한 땅에대한 저주를  행하시지 않으신다 선포하셨다.

8 인간 찾기 (해석)
노아는 오랜시간동안 방주안에 있었다. 비가 멈추고 이제는 뚜껑을 열고 땅이 말라있는것 까지 직접 눈으로 확인하였다.

얼마나 빨리 땅으로 내려가고 싶었을까?

그러나 당대 의인이었던 노아는 달랐다.
인간어 육적인 본능대로 움직이지 않았고 도리어 하나님이 나오라고 명령하실 때까지 기다렸다.

마치 모든 남자들이 아름다운 여자들을 본능에 이끌릴어 마음대로 취하는 죄악을 범할때도 예외였던 노아의 영적인 모습처럼 이번에도 그렇게 행하였다.

드디어 하나님의 나오라는 명령을 듣고 나온 영적인 사람 노아는 바로 제단을 쌓고 번제를 하나님께 드리는 최초의 예배를 올렸다.

노아가 하나님께 인정받을수 있었던 요인은 육적인 본능을 제어하고 우선적으로 하나님의 음성을 듣고 순종으하며 예배를 통하여 살아게신 하나님을 나타내려 하는 태도이다

