6.인간 찾기 (관찰)


	나온 노아는 포도나무 농사를 시작함


7.하나님 찾기 (해석) 


	몇 번이고 강조해서 언약을 세우셨다. 하나님과 인간, 육체를 가진 땅의 모든 생물 사이에서는 물이 홍수가 되어 다신 이러한 일이 발생되지 않을 것이라 약속을 하셨다. 하나님이 왜 인간에게 언약을 하셨을까? 하나님은 신인데 인간에게 왜 언약을 해주셨을까?  직접 만드신 인간이 악하고 악을 계획하는 모습에 모두 쓸어버리시기 까지 하셨지만 실상은 마음이 많이 아프셨던 것 같다. 그래서 살아남은 인간은 하나님을 경외하더라도 연약한 존재이기 때문에 그들의 두려움을 없애주고자 노력하셨다.



	하나님께선 무지개를 통해 언약의 증거로 세우셨다. 무지개는 한쪽에 떠있는 빗방울로 생기는데 반대쪽에서 오는 햇빛의 굴절로 반사되어 우리에게 보이는 현상이다. 햇빛이 물과 공기 사이를 지나갈 때 여러 가지 색으로 휘어지는데 그것이 무지개처럼 보이는 것이다. 색의 차이는 빛이 여러 가지 속도로 공기와 물을 지나가기 때문이라고 한다. 이처럼 우리가 상상할 수 없는 놀라운 원리도 아름다운 무지개가 만들어진다. 무지개를 보면 아름다움에 매료되 기쁨과 놀라움을 경험하게 되는데 어떠한 상황이더라도 소망을 가지게 되는 마음이 든다. 
	무지개를 통해 남아 있는 인간들에게 소망이 되어주셨다. 무지개를 보며 하나님의 언약을 떠올리고 새롭게 시작될 삶을 소망을 품고 살아가게 하셨다.


8.인간(해석):

9. 적용(나): 


	우리를 사랑하신다. 또한 우리가 고난 받는 것을 슬퍼하신다.  우리를 내버려두지 않으신다. 모든 일에 하나님의 보호하심을 느끼며 살아가길 기도한다.
	통해 소망이 되신 하나님이 우리 가정과 NKFC 회원과 리더십, 임원의 삶에 소망이 되어주시길 기도한다. 


