5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 포도주를 마시고 취하여 벌거벗은 채로 장막 안에서 자는 노아
- 노아의 벌거벗은 하체를 보고 밖으로 나가 셈과 야벳에게 알리는 함
- 겉옷을 가지고 들어가되, 아버지의 하체를 보지 않기 위해 뒷걸음치며 들어가서 하체를 덮는 셈과 야벳
- 술이 깨어 작은 아들 함을 저주하고 셈과 야벳을 축복하는 노아
- 노아는 홍수 후 350년을 더 살고 950세에 죽음   

7.하나님 찾기 (해석) 

8.인간(해석): 
- 노아는 홍수 후 땅에서 포도 등 열매를 수확하고 즐거웠을 것이다.
- 이제 자신의 후손들이 하나님의 언약과 보호하심 속에서 평화롭게 풍요롭게 살 수 있겠구나 기대감이 부풀었을 것이다.
- 흡족한 마음에 포도주를 마셨고 참으로 만족스러웠을 것이다. 
- 하나님께 감사드리며 그 시간을 즐겼을 것이 분명하다.
- 그러나 포도주를 많이 마시게 됐고, 벌거벗은 채 잠들게 되었다.
- 우리 인간은 어떤 동기에서 술을 마시든지, 술에 취하면 실수하게 돼 있다. 
- 술에 취하지 않고, 성령에 충만한 삶을 살도록 주의해야 한다.
- 노아의 벌거벗은 하체를 본 함은 아버지의 실수를 혼자 조용히 알지 못하고 형과 동생에게 가서 말하고 데리고 가서 보이고자 했다.
- 아버지를 사랑하는 마음보다, 아버지를 조롱하고 싶은 마음이 컸던 것이다. 이것은 영적인 사람이 할 일이 아니다.
- 사랑은 허다한 죄를 덮는다고 했다. 
- 우리 인간은 하나님의 사랑으로 가득차지 않으면 함과 같은 실수를 하게 된다.
- 한편 함의 조롱 섞인 정보를 들은 셈과 야벳은 겉옷을 들고 뒤로 돌아 걸어가서 아버지의 하체를 보지 않고 조심히 덮었다.
- 아버지를 사랑한 것이며, 노아의 하나님 아버지를 경외한 것이다.
- 이에 노아는 셈의 하나님을 찬송한 것이다.
- 셈은 하나님을 경외한 사람이었다.
- 우리는 셈과 야벳처럼 아버지의 실수를 알아도 덮을 수 있는 사람이 되어야 한다.
- 사랑하는 사람의 실수를 덮는 것이 우리의 사랑을 실천하는 일이다.
- 노아는 함을 저주하였다. 용서하지 않고 저주한 것에는 여러 가지 이유가 있을 것이다.
- 유아기에는 부모가 훈육할 수 있으나 장성한 자를 어떻게 하겠는가.
- 악으로 치우쳐 장성한 자를 누가 막겠는가.

9.적용(나)
- 하나님이 창조하신 시간과 공간 속에서, 
- 보내신 모든 곳에서 주님께 감사하며 살아가되,
- 술에 취하지 않고 성령에 충만한 삶을 살아가도록 기도와 말씀에 힘써야겠다.
- 주님의 사랑으로 가득 차 남의 허물을 덮을 수 있도록 성령님께 간구해야겠다. 

