8 인간 찾기 (해석)
노아의 아들인 야벳과 함의 계보에 대한 내용을 보여준다.  노아가 포도주를 먹고 취한후 알몸으로 잠을 자는모습을 들어낸  함과 덮어준 야벳의 저주와 축복권이 자손에게 영향을 준다는 시각으로 볼때 함의 자손중에 "용감한 사냥꾼" 이라는 칭호를 받는 니므롯 이 등장한다. 

물론 니므롯은 저주를 직접받은 가나안의  직계는 아니지만 함의 혈통이라는 관점에서 보면 비슷한 점이 있다.

 "용사" 또는 "사냥꾼" 이라는 기록이 있다.  

이것은 아마도 스스로 과시하고 돋보이고자 하고 하는 모습이 다른 사람의 허물을 드러내고자 했던 부분과 오버랩되는 부분이다.

 인간의 교만함의 상징적 표현이라 여겨진다. 성경은 의도적으로 "최초의 용사" 또는 "사냥꾼" 등을 기록한것 같다

하나님은 철저히 겸손한자를 높이시고 스스로 높아지고 주인되려는 자를 낮추시고 세상의 종이 되게 하실수 있으신 분이시다.

