- 함의 손자 니므롯(구스의 아들)이 앗수르 지역에 터전을 잡음
- 함의 손자가 여럿 있는데 그 중 가슬루힘(미스라임의 아들)에게서 블레셋이 나왔다.
- 함의 손자들(가나안의 아들들)은 가나안 족속을 이룬다.
- 가나안의 경계가 나오는데 그 중에는 소돔과 고모라가 있다.

7.하나님 찾기 (해석) 
-  

8.인간(해석)
- 하나님을 사랑하지 않고, 아버지를 조롱했던 함의 자손들에 대한 이야기가 나온다.
- 함은 수백년을 살면서 자기를 믿고 살었던 것으로 보인다.
- (사실 노아의 홍수를 경험하고 하나님의 창조세계를 다시 누릴 수 있는 특권을 받은 자가 그런 행동을 했다는 것은 굉장한 불신이요, 자기 신봉이 아닐 수 없다.)
- 함에게 유전자와 생활 태도를 배운 자손들의 이야기인데 성경에서 굵직한 악인들과 터전이 이 함의 자손들에게서 나왔다.
- 먼저 앗수르는 훗날 북이스라엘을 멸망시키는 아주 잔인한 민족성을 가진 자들이며
- 블레셋은 삼손의 이야기가 대표적으로 이스라엘 백성을 긴 시간동안 괴롭히는 민족이며
- 가나안 족속들은 그 악이 충만하여 하나님께서 이스라엘에게 멸망시키라고 한 민족들이다.
- 그 중 소돔과 고모라는 가나안 족속 중에서도 가장 먼저 너무나 타락하여 아브라함과 롯 이야기에서 하나님께서 먼저 멸망시킨 지역이며, 족속이다.
- 조상 한 명의 영향이 얼마나 큰지, 
- 하나님의 사람 노아의 저주가 얼마나 큰 파괴력을 가졌는지 알 수 있다.
- 물론 노아의 분노와 저주는 하나님의 감동으로 된 것으로 유추된다. 

9.적용(나)
- 내가 함처럼 살면 내 자녀와 손주들이 함처럼 될 경향성이 커질 것이다.
- 정말 무서운 일이다.
- 내가 셈과 야벳처럼 살면 내 자녀와 손주들이 하나님을 경외하며, 하나님의 창조 세계를 누리며 살 것이다.
- 내 자손들이 하나님을 경외하며 하나님이 허락하신 시간과 공간을 누리며 살 수 있도록 성령 안에서 말씀과 기도로 힘써 살아야겠다. 

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

