7.하나님 찾기(해석)
하나님은 자신을 의지하지 않고 스스로의 힘을 과시할 목적으로 사는 인간들을 대적하신다. 하나님을 빼놓고 인간들 끼리 하나 되고 높아지려는 열정과 성실은 헛된 삶인 것을 하나님은 바벨탑 심판을 통하여 일깨움을 주신다
8 인간 찾기 (해석)
본래 인간들이 한 언어로 모여사는 것을 하나님은 막지 않으신다. 다만 인간들이 바벨탑을 쌓는 목적과 동기가 불순하기 때문이다. 동기는 자신들의 이름을 드러내기 위함이라 기록되어 있다. 
그래서 하나님은 모든 인간들을 흩으셨다. 요한계시록 보면 마지막 때에 믿음의 백성들 모든 민족이 모여 주님을 찬양하는 모습이 나온다. 
우리가 살아가는 목적 과 동기는 철저히 주님의 영광을 드러내고 찬양하기 위함이다. 하나님은 자신을 높이는 자들을 높여주시고 스스로 높아지려는 자들을 철저히 흩으시고 심판하시는 모습을 볼 수 있다.
9.적용(나):
