노아홍수사건 이후 인간 수명이 현저히 줄어들었음을 볼수있다. 그럼에도 영원한세상인 천국이라는 시간과 비교한다면  수명이 900년 이나 400년이나 큰 수치적 차이는 느껴지지 않을것이다

아담의 계보와 달리 셈의 계보는 수명이 많이 단축된것은 유추할수 있지만 언제 죽었는지 성경은 기록하지 않았다.

그것은 하나님의 의도성이 있어보인다 하나님은 인간이 원죄를 저지린후  아담의 계보를 기록하실때 계보에  ''죽음 ''을 기록하였지만 노아로 부터 축복받은 셈의 계보에서는 일부러 빠트린  부분은 하나님이 은혜의 영원한 생명을 알려주실 의도가 있어보인다. 

'' 믿음의 조상'' 아브라함도 셈의 후손이요 나아가서는 심지어 성자 하나님이신 예수께서도 이 땅에 육신으로 오실때도   셈의 계보에 위치해 계심을 알수있다.

