8.인간(해석):
- 하나님의 계획은 몇 대에 걸쳐 이루어진다. 우리는 당장 눈앞에 놓여진 상황이 해결되길 바라지만 하나님의 계획은 그것이 아닐 수도 있음을 깨닫는다.
- 데라는 자신의 자녀 하란의 아들인 손자 룻을 아브람과 함께 가나안으로 데려가고자 했다. 아들이 먼저 죽었기에 손주를 보호하고자 했을 것이다. 아버지로서 아들을 사랑한 것 같이 룻을 더 아끼고 사랑했을 것이다.
- 셈의 족보로부터 믿음의 조상 아브라함이 태어난다. 부모의 의로운 믿음과 행동이 자녀를 위한 복이 될 수 있음을 기억해야 한다.
