4.주제 만들기: 하나님의 부르심과 언약

5.하나님 찾기 (관찰)
- 아브람을 부르시고 내가 보여 줄 땅으로 가라고 명하심
- 너로 큰 민족을 이루고 너는 복이 될 것이라 말씀하심
- 땅의 모든 족속이 너로 말미암아 복을 얻을 것이라 말씀하심
- 가나안에 이른 아브람에게 나타나 이르시되 이 땅을 네 자손에게 주리라 말씀하심

6.인간 찾기 (관찰)
- 아브람은 갈바를 알지 못했으나 하나님의 말씀을 따라 
- 가족과 모든 소유와 얻은 사람들을 이끌고 가나안 땅으로 들어감
- 가나안 땅에는 가나안 족속(함의 자손)이 살고 있었다.
- 가나안에서 나타나 이 땅을 네 자손에게 주리라 말씀하신 하나님을 위하여 제단을 쌓음
- 벧엘 동쪽 산으로 옮겨 장막을 치고 그 곳에서도 여호와께 제단을 쌓고 여호와의 이름을 부름
- 그 땅에 기근이 들자 애굽에서 거류하고자 내려감 

7.하나님 찾기 (해석) 
- 모든 민족에게 복을 주시는 통로로 아브람을 택하시고 
- 아브람에게 계획을 말씀하심
- 아브람 자손에게 복을 주신다고 하지 않고 
- 아브람을 통해 모든 민족에게 복을 주신다고 한 것에 주목해야 한다.

8.인간(해석): 
- 아브람은 하나님의 말씀에 순종하여 갈바를 알지 못했으나 가나안 땅으로 갔다.
- 하나님을 만난 아브람은 자신이 어떻게 해야 할지 모르지만,
- 하나님을 의지하면 모든 행사를 하나님이 이루실 것을 믿은 것이다. 
- 전능하신 하나님을 만난 사람에게는 절대적인 믿음이 생기게 되어 있다.
- 복을 주시겠다 말씀하신 하나님께 제단을 쌓으며 예배를 드리기 시작한다.
- 벧엘 동쪽 산으로 옮겨 장막을 치고 거기서도 하나님의 임재를 구하며 제단을 쌓았다.
- 하나님의 임재를 경험한 사람은 그 임재를 구하며 예배드리게 되어 있다.
- 약속하신 땅에 기근이 들자 기근을 피하고자 애굽으로 이동한다.
- 하나님의 섭리 안에서 움직인 것인지 믿음이 약하여 애굽으로 간 것인지 나는 모른다.
 
9.적용(나)
- 갈바를 알지 못하나 하나님의 말씀에 순종한 아브람의 믿음과 행위를 본 받아야 한다.
- 하나님을 경외하여 하나님께 제단을 쌓은 아브람의 태도와 행위를 본 받아야 한다.
- 장소를 옮기고 나서 그 곳에서도 하나님께 제단을 쌓고 예배한 아브람의 태도와 행위를 본 받아야 한다.
- 아브람을 본 받아 하나님을 경외하고 말씀에 순종하며, 
- 예배 중심의 삶을 살도록 노력해야겠다.

10. 영적터치(단어/구절)  
  8절 그가 그 곳에서 여호와께 제단을 쌓고 여호와의 이름을 부르더니
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-03', '창세기', '12장 11절 ~ 20절', '&nbsp;', '(창세기 12장)
11. 그가 애굽에 가까이 이르렀을 때에 그의 아내 사래에게 말하되 내가 알기에 그대는 아리따운 여인이라
12. 애굽 사람이 그대를 볼 때에 이르기를 이는 그의 아내라 하여 나는 죽이고 그대는 살리리니
13. 원하건대 그대는 나의 누이라 하라 그러면 내가 그대로 말미암아 안전하고 내 목숨이 그대로 말미암아 보존되리라 하니라
14. 아브람이 애굽에 이르렀을 때에 애굽 사람들이 그 여인이 심히 아리따움을 보았고
15. 바로의 고관들도 그를 보고 바로 앞에서 칭찬하므로 그 여인을 바로의 궁으로 이끌어들인지라
16. 이에 바로가 그로 말미암아 아브람을 후대하므로 아브람이 양과 소와 노비와 암수 나귀와 낙타를 얻었더라
17. 여호와께서 아브람의 아내 사래의 일로 바로와 그 집에 큰 재앙을 내리신지라
18. 바로가 아브람을 불러서 이르되 네가 어찌하여 나에게 이렇게 행하였느냐 네가 어찌하여 그를 네 아내라고 내게 말하지 아니하였느냐
19. 네가 어찌 그를 누이라 하여 내가 그를 데려다가 아내를 삼게 하였느냐 네 아내가 여기 있으니 이제 데려가라 하고
20. 바로가 사람들에게 그의 일을 명하매 그들이 그와 함께 그의 아내와 그의 모든 소유를 보내었더라

