4.주제만들기: 
아내를 누이라 바로에게 속인 아브람

5.하나님 찾기 (관찰)
바로에게 큰 재앙을 내리신 하나님

6.인간 찾기 (관찰)
아리따운 미모를 가진 사래
아리따운 미모를 본 애굽 사람들
