7.하나님 찾기(해석)
아브람에게 복 주시겠다고 이미 약속하셨던 하나님은 위기에 있는 아브람 가정을 지켜주셨다. 

애굽의 최고의 통치자 바로를 큰 재앙을 내리사 진정한 왕은 여호와 하나님 한분이심을 더욱 꺠우치게 된다

8 인간 찾기 (해석)
아브람은 하란에서 그를 불러 인도하신 하나님을 순간 잊고 두려움속에 있었다  

하나님은 아브람에게 말씀하시기를 축복하는 자에게 복을 그에게 저주하는 자 에게는 저주를 줄것을 약속하셨다 

그리고 모든 민족의 복의 통로로 사용하신다고 하셨다. 그러나 두려움이 너무 컸던 이유로 애굽왕 바로와 백성들에게 스스로 아내를 누이라고 범하는 약한 모습을 보였다

그런까닭에 자신의 아내를 잠시 바로의 아내로 빼앗기는 수치를 당한다 다행히 하나님이 개입하셔서 바로에게 재앙을 내리시면서 다시 아내 사래가 아브람으로 돌아오게 하신다

우리도 세상가운데 살아갈때 복잡하고 두려운 환경이나 인간관계를 맞딱뜨릴때가 있다. 그런경우에는 스스로 잔꾀로 위기를 모면하기보다는 쉽게 문제를 풀어주고 해결하실수있는 전능하신 주님께 도움을 요청하는것이 복된 삶일것이다 

9.적용(나):
위기를 맞닥뜨리게 되는 상황이 오면 스스로의 생각보다 충분히 문제를 해결하실수 있는 주님의 도움을 기도로 더욱 청해야겠다.

10. 영적터치(단어/구절)
18절: 네가 어찌하여 그를 네아내라고 내게 말하지 아니하였느냐 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-04', '창세기', '13장 1절 ~ 10절', '아브라함에게 임한 복', '창세기 13장
1   아브람이 애굽에서 그와 그의 아내와 모든 소유와 롯과 함께 네게브로 올라가니
2   아브람에게 가축과 은과 금이 풍부하였더라
3   그가 네게브에서부터 길을 떠나 벧엘에 이르며 벧엘과 아이 사이 곧 전에 장막 쳤던 곳에 이르니
4   그가 처음으로 제단을 쌓은 곳이라 그가 거기서 여호와의 이름을 불렀더라
5   아브람의 일행 롯도 양과 소와 장막이 있으므로
6   그 땅이 그들이 동거하기에 넉넉하지 못하였으니 이는 그들의 소유가 많아서 동거할 수 없었음이니라
7   그러므로 아브람의 가축의 목자와 롯의 가축의 목자가 서로 다투고 또 가나안 사람과 브리스 사람도 그 땅에 거주하였는지라
8   아브람이 롯에게 이르되 우리는 한 1)친족이라 나나 너나 내 목자나 네 목자나 서로 다투게 하지 말자
9   네 앞에 온 땅이 있지 아니하냐 나를 떠나가라 네가 좌하면 나는 우하고 네가 우하면 나는 좌하리라
10   이에 롯이 눈을 들어 요단 지역을 바라본즉 소알까지 온 땅에 물이 넉넉하니 여호와께서 소돔과 고모라를 멸하시기 전이었으므로 여호와의 동산 같고 애굽 땅과 같았더라
