우, 좌: 9(2)

4.주제 만들기: 아브라함에게 임한 복

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 아브람이 가족과 함께 애굽에서 네게브로 올라감
- 아브람에게 가축과 은과 금이 풍부하였음
- 벧엘 과 아이 사이 전에 장막쳤던 곳, 
- 처음 제단을 쌓은 곳에 이르러 여호와의 이름을 부름
- 롯도 양과 소와 장막이 있어 그 땅에서 함께 살기에는 좁았음
- 아브람의 가축 목자와 롯의 가축 목자가 서로 다투었고,
- 그 곳에는 가나안 사람과 브리스 사람도 거주하였음
- 이에 아브람이 롯에게 친족끼리 다투지 말자고 말하고
- 롯에게 제안하기를 네 앞에 마음에 드는 땅으로 가라고 말함
- 롯은 요단 지역을 바라보았고, 소알 지역까지 온 땅이 마음에 들었음

7.하나님 찾기 (해석) 

8.인간(해석): 
- 아브람은 기근을 피해 애굽으로 갔고,
- 애굽에서 자신의 안전을 위해 거짓말을 하고 
- 아내를 팔기까지 했으나
- 하나님의 섭리 가운데 보호를 받아 아내도 되찾고 가축과 은과 금이 풍부하게 됨
- 하나님의 인도하심에 대해 우리는 알 수가 없음
- 다만, 하나님이 부르신 자가 순종하면 하나님은 그 사람을 보호하시고 책임지신다는 것을 알 수 있음
- 하나님의 섭리 가운데 감사함이 넘친 아브람은 벧엘 일대 처음 제단 쌓은 곳에 이르러 다시 하나님을 부르고 예배함
- 자신과 롯의 소유가 많아지므로 거주하는 땅이 좁아지자,
- 하나님께서 자신의 삶을 주관하심을 깨달은 아브람은 
- 조카 롯에게 마음에 드는 땅을 먼저 선택하고 거기 거주하라고 배려함
- 유추하건데 아브람과 롯의 목자만 다툰 것이 아니라, 
- 가나안 사람과 브리스 사람들도 다투었을 것이다.
- 롯은 삼촌에 말에 주위 땅들을 둘러 보았고
- 요단 강 지역을 바라보며 마음에 들어함

9.적용(나)
- 하나님께서 나를 부르셨다.
- 나는 하나님의 말씀에 순종하는 삶을 살아내야 한다.
- 그러면 하나님께서 놀라운 섭리 가운데 나를 푸른 초장으로 인도하실 것이다.
- 나는 이것을 굳게 믿고, 앞으로 당당하게 나아가야 한다.
- 그리고 나그네 인생길에서 인도하시는 곳이 푸른 초장이 아닐지라도,
- 나는 진정한 푸른 초장인 본향을 바라보며 뚜벅뚜벅 걸어갈 것이다. 

10. 영적터치(단어/구절)  
  4   그가 처음으로 제단을 쌓은 곳이라 그가 거기서 여호와의 이름을 불렀더라
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-05', '창세기', '13장 11절 ~ 18절', '제목 없음', '[창13:11-18]
11 그러므로 롯이 요단 온 지역을 택하고 동으로 옮기니 그들이 서로 떠난지라
12 아브람은 가나안 땅에 거주하였고 롯은 그 지역의 도시들에 머무르며 그 장막을 옮겨 소돔까지 이르렀더라
13 소돔 사람은 여호와 앞에 악하며 큰 죄인이었더라
14 롯이 아브람을 떠난 후에 여호와께서 아브람에게 이르시되 너는 눈을 들어 너 있는 곳에서 북쪽과 남쪽 그리고 동쪽과 서쪽을 바라보라
15 보이는 땅을 내가 너와 네 자손에게 주리니 영원히 이르리라
16 내가 네 자손이 땅의 티끌 같게 하리니 사람이 땅의 티끌을 능히 셀 수 있을진대 네 자손도 세리라
17 너는 일어나 그 땅을 종과 횡으로 두루 다녀 보라 내가 그것을 네게 주리라
18 이에 아브람이 장막을 옮겨 헤브론에 있는 마므레 상수리 수풀에 이르러 거주하며 거기서 여호와를 위하여 제단을 쌓았더라

