4. 주제만들기
5. 하나님 찾기 (관찰)
- 아브람에게 이르시되 눈을 들어 있는 곳의 북쪽과 남쪽과 동쪽과 서쪽을 바라보라고 하심
- 아브람이 보이는 땅을 아브람과 아브람의 자손에게 주시고 영원히 이를 것이라고 말하심
- 아브람의 자손을 티끌 같게 하시겠다고 언약하심
- 아브람에게 일어나 종과 횡으로 다니라고 하시며 그것을 모두 주리라 말씀하심
6. 인간 찾기 (관찰)
- 룻은 요단 지역으로 떠남
- 아브람은 가나안에 머물고, 룻은 요단 지역의 도시에 머무르며 장막을 옮겨 소돔에 이르게 됨
- 소돔 사람은 여호와 앞에서 악하며 큰 죄인이었음
- 아브람은 하나님의 명령대로 따르고, 장막을 옮겨 헤브론에 있는 마무리 상수리 수풀에 이르러 거주하며 여호와를 위한 제단을 쌓음
7. 하나님 찾기 (해석) 
- 하나님께선 아브람에게 언약하시며 축복하셨다. 하나님의 언약은 아브람에게만 머무는 것이 아니라 자손에게까지 이어지는데 하나님의 전적인 구속 사역으로 아브람과 자손들은 삶의 축복뿐 아니라 구원까지 받게 된다.
- 이런 축복은 현대에 사는 우리에게까지 전해지게 되었다.
8. 인간(해석):
- 룻은 요단의 풍요로움을 선택했다. 룻은 도시에 가까운 지역에 머무르며 소돔까지 이르게 되는데 장막을 치고 하나님을 위해 제단을 쌓았다는 구절은 어디에도 없다.
- 반면 아브람은 하나님으로부터 언약의 축복을 받고 장막을 옮겨 여호와를 위한 제단을 쌓았다. 
- 하나님을 의지한 자와 하나님을 의지하는 자의 삶의 결과는 다를 것이다.
9. 적용(나): 
- 눈 앞의 풍요로움에 현혹되지 않도록 기도해야겠다. 
- 모든 일에 하나님의 지혜와 은혜를 간구해야겠다.
- 하나님께서 우리를 붙들어주시는 것에 감사한다.
10. 영적터치(단어/구절)
-18절 여호와를 위하여 제단을 쌓았더라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-06', '창세기', '14장 1절 ~ 10절', '&nbsp;', '(창세기 14장)
1.  당시에 시날 왕 아므라벨과 엘라살 왕 아리옥과 엘람 왕 그돌라오멜과 고임 왕 디달이
2. 소돔 왕 베라와 고모라 왕 비르사와 아드마 왕 시납과 스보임 왕 세메벨과 벨라 곧 소알 왕과 싸우니라
3. 이들이 다 싯딤 골짜기 곧 지금의 염해에 모였더라
4. 이들이 십이 년 동안 그돌라오멜을 섬기다가 제십삼년에 배반한지라
5. 제십사년에 그돌라오멜과 그와 함께 한 왕들이 나와서 아스드롯 가르나임에서 르바 족속을, 함에서 수스 족속을, 사웨 기랴다임에서 엠 족속을 치고
6. 호리 족속을 그 산 세일에서 쳐서 광야 근방 엘바란까지 이르렀으며
7. 그들이 돌이켜 엔미스밧 곧 가데스에 이르러 아말렉 족속의 온 땅과 하사손다말에 사는 아모리 족속을 친지라
8. 소돔 왕과 고모라 왕과 아드마 왕과 스보임 왕과 벨라 곧 소알 왕이 나와서 싯딤 골짜기에서 그들과 전쟁을 하기 위하여 진을 쳤더니
9. 엘람 왕 그돌라오멜과 고임 왕 디달과 시날 왕 아므라벨과 엘라살 왕 아리옥 네 왕이 곧 그 다섯 왕과 맞서니라
10. 싯딤 골짜기에는 역청 구덩이가 많은지라 소돔 왕과 고모라 왕이 달아날 때에 그들이 거기 빠지고 그 나머지는 산으로 도망하매

