8.인간 찾기(해석)
큰 죄악을 범하여 훗날 불의 심판으로 멸망 당하는 소돔과 고모라는 네 왕을 배반하여 도망하는 모습을 기록했다.

세상의 왕들에게도 전쟁 패배로 수치를 당하는 소돔 왕과 고모라 왕이 그때라도 정신차리고 진정한 왕 되신 여호와 하나님을 의지했으면 어떻게되었을까 생각하게 된다.

롯은 애굽 같은 풍요로운 소돔을 선택하였지만 사실 하나님께서는 성적 타락으로 이미 심판을 예정하신 소돔과 고모라를 준비하고 계셨다.

9.적용(나):
이 세상에서 살아갈때 눈에 보이는 화려함 인기  유명함 등 을 쫓기보다는 소박해 보여도 성령 하나님이 기뻐하시는 곳에 머물기 위해 노력해야겠다 

10. 영적터치(단어/구절)
10절: 소돔 왕과 고모라 왕이달아날 때에

