2024년 9월01일 창세기 14장11절~24절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
소돔: 11절 12절 
조카 롯: 12절 14절 
아브람: 13절(2) 14절 17절 19절 22절 23절(2)
뺏다/노략하다: 11절 12절 
쫓다: 14절 15절
살렘 왕 멜기세덱: 18절 19절 20절
분깃: 23절 24절

4.주제만들기: 
조카 롯을 구출한 아브람

5.하나님 찾기 (관찰)
전쟁을 승리케 하신 하나님
아브람을 축복하신 살렘 왕 멜기세덱 

6.인간 찾기 (관찰)
노예로 끌려간 롯과 가족
그 사실을 아브람에게 알린 사람
평상시 아모레 족속 마므레와 더불어 동맹관계를 맺은 아브람
평상시 삼백십팔 명을 훈련시킨 아브람
조카 롯을 구출한 아브람
십의 일조를 멜기세덱 에게 바치는 아브람
소돔왕의 호의를 거절하는 아브람

7.하나님 찾기(해석)
섬세하고도 준비가 잘된것으로 전쟁에서 이긴것처럼 보이지만 싸움의 승리는 절대적인 하나님 손에 달려있다.

20절에 멜기세덱은 명확하게 말씀하고 있다. "너희 대적을 네 손에 붙이신 지극히 높으신 하나님을 찬송할지로다"

그러므로 모든 인간들은 매순간 주를 의지하고 특히 고난을 받을 때는 승리케 하시고 도와주시는 주님께 더욱 매달리는것이 지혜로운 사람임을 성경은 일깨워주고 있다

8.인간 찾기(해석)
아브람은 싸움에도 매우 치밀한  전략가였다.  그는 평상시에 지역에 있는 아모리 족속 마므레와도 동맹을 맺을 정도로 관계성이 좋았다. 그리고 아브람은 스스로 삼백십팔명 훈련된 사람들도 있었다.  롯과 가족을 구하려 갈때 사람들을 나누고 특히 밤에 쳐들어가서 싸움에서 이기고 구출할수 있었다.

아브람이 특별히 대단한 사람인것은 대승을 했음에도 모든 공로를 자신이 아닌 하나님께 영광을 올리는 부분이다

전지 전능하신 예수의 예표인 살렘 왕 멜기세덱은 그의 중심을 아시고 하나님께 아브람을 축복하신다  그때 아브람은 인류 최초로 십일조를 올린다

반면에 아브람은 세상에서 받는 영광보다 하늘의 것만 추구하는 마음으로 소돔왐이 주는 보상  물품을 거절한다.

온전히 하나님만 의지하고 그분의 영광을 올리려하는 아브람을 하나님은 기뻐히신다

9.적용(나):
모든 형통은 주님의 은혜로 이루어짐을 알게 된다. 그러므로 늘 주님을 찬양하며 감사를 드리는 삶을 살아내야겠다 

10. 영적터치(단어/구절)
22절: 네 대적을 네 손에 붙이신 지극히 높으신 하나님을 찬송할지로다 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-08', '창세기', '15장 1절 ~ 10절', '아브람의 지혜와 믿음으로 얻은 상속자', '[창15:1-10]
1 이 후에 여호와의 말씀이 환상 중에 아브람에게 임하여 이르시되 아브람아 두려워하지 말라 나는 네 방패요 너의 지극히 큰 상급이니라
2 아브람이 이르되 주 여호와여 무엇을 내게 주시려 하나이까 나는 자식이 없사오니 나의 상속자는 이 다메섹 사람 엘리에셀이니이다
3 아브람이 또 이르되 주께서 내게 씨를 주지 아니하셨으니 내 집에서 길린 자가 내 상속자가 될 것이니이다
4 여호와의 말씀이 그에게 임하여 이르시되 그 사람이 네 상속자가 아니라 네 몸에서 날 자가 네 상속자가 되리라 하시고
5 그를 이끌고 밖으로 나가 이르시되 하늘을 우러러 뭇별을 셀 수 있나 보라 또 그에게 이르시되 네 자손이 이와 같으리라
6 아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고
7 또 그에게 이르시되 나는 이 땅을 네게 주어 소유를 삼게 하려고 너를 갈대아인의 우르에서 이끌어 낸 여호와니라
8 그가 이르되 주 여호와여 내가 이 땅을 소유로 받을 것을 무엇으로 알리이까
9 여호와께서 그에게 이르시되 나를 위하여 삼 년 된 암소와 삼 년 된 암염소와 삼 년 된 숫양과 산비둘기와 집비둘기 새끼를 가져올지니라
10 아브람이 그 모든 것을 가져다가 그 중간을 쪼개고 그 쪼갠 것을 마주 대하여 놓고 그 새는 쪼개지 아니하였으며

