4.주제 만들기: 하나님이 맺으신 언약

5.하나님 찾기 (관찰)
- 아브라함의 자손이 이방에서 객이 되어 그들을 섬기고 사백 년간 괴롭힘 당할 것을 말씀하심
- 그 섬기는 나라를 징벌할 것이며, 아브람의 자손이 큰 재물을 가지고 나올것이라 말씀하심
- 횃불이 쪼갠 고기 사이로 지나감
- 아브람과 더불어 언약을 세워 이 땅을 애굽 강에서부터 유브라데강까지 자손에게 주겠다 말씀하심

6.인간 찾기 (관찰)
- 아브람이 제물 위에 내려온 솔개를 쫓음
- 아브람에게 깊은 잠이 임하고 큰 흑암과 두려움이 임함

7.하나님 찾기 (해석) 
- 아브람의 자손에게 이 땅을 주실 것과 그들이 당할 일들, 
- 그리고 구원받고 나올 일에 대해, 많은 재물을 가지고 나올 일에 대해 구체적으로 말씀하심
- 아모리 족속의 죄악이 찰 때까지 사백 년을 기다리는 것과
- 자손들이 차지할 땅을 구체적으로 말씀하심  

8.인간(해석): 
- 하나님의 말씀에 순종하여 고기를 쪼갠 아브람은 그것을 먹으려는 솔개를 쫓았다.
- 하나님의 말씀에 순종한 일에도 방해는 있으며, 그것은 자연법칙 일수도 있고 영적인 것일 수도 있다.
- 그것이 무엇이든 우리는 순종하여 행한 일이 방해받지 않도록 노력해야 한다.
- 하나님의 특별한 임재 가운데 아브람은 깊이 잠들었고, 깊은 어둠과 공포가 임했다.
- 하나님의 임재를 몇 번 경험한 아브람이 왜 이때 깊이 잠들었으며, 깊은 어둠과 공포 임했는지 나는 알 수 없다.
- 그러나 언약을 세우시되, 아브람의 자손이 당할 일을 말씀하시는 하나님 앞에 선 아브람을 생각해 보면 아브람이 왜 그런 상태에 놓이게 하셨는지 유추해 볼 수 있다.

9.적용(나)
- 하나님을 굳게 믿고, 
- 말씀에 순종하여 실천하며,
- 이루어진 일이 방해 받지 않도록 노력해야겠다.
- 자연법칙에 의해서든, 영적인 것이든 방해가 있다는 것을 기억하고,
- 날마다 예배하며 맡겨진 일을 묵묵히 해나가야 한다.

10. 영적터치(단어/구절)  
  13   여호와께서 아브람에게 이르시되
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-10', '창세기', '16장 1절 ~ 10절', '&nbsp;', '(창세기 16장)
1.  아브람의 아내 사래는 출산하지 못하였고 그에게 한 여종이 있으니 애굽 사람이요 이름은 하갈이라
2. 사래가 아브람에게 이르되 여호와께서 내 출산을 허락하지 아니하셨으니 원하건대 내 여종에게 들어가라 내가 혹 그로 말미암아 자녀를 얻을까 하노라 하매 아브람이 사래의 말을 들으니라
3. 아브람의 아내 사래가 그 여종 애굽 사람 하갈을 데려다가 그 남편 아브람에게 첩으로 준 때는 아브람이 가나안 땅에 거주한 지 십 년 후였더라
4. 아브람이 하갈과 동침하였더니 하갈이 임신하매 그가 자기의 임신함을 알고 그의 여주인을 멸시한지라
5. 사래가 아브람에게 이르되 내가 받는 모욕은 당신이 받아야 옳도다 내가 나의 여종을 당신의 품에 두었거늘 그가 자기의 임신함을 알고 나를 멸시하니 당신과 나 사이에 여호와께서 판단하시기를 원하노라
6. 아브람이 사래에게 이르되 당신의 여종은 당신의 수중에 있으니 당신의 눈에 좋을 대로 그에게 행하라 하매 사래가 하갈을 학대하였더니 하갈이 사래 앞에서 도망하였더라
7. 여호와의 사자가 광야의 샘물 곁 곧 술 길 샘 곁에서 그를 만나
8. 이르되 사래의 여종 하갈아 네가 어디서 왔으며 어디로 가느냐 그가 이르되 나는 내 여주인 사래를 피하여 도망하나이다
9. 여호와의 사자가 그에게 이르되 네 여주인에게로 돌아가서 그 수하에 복종하라
10. 여호와의 사자가 또 그에게 이르되 내가 네 씨를 크게 번성하여 그 수가 많아 셀 수 없게 하리라

