4.주제만들기: 
사래와 그의 여종 하갈

5.하나님 찾기 (관찰)
사래의 출산을 아직 허락하지 않으시는 여호와 하나님
학대받고 쫓겨난 여종 하갈을 찾아와 위로하시는 하나님

6.인간 찾기 (관찰)
출산을 하지못하여 여종 하갈을 남펀 아브람과 동침하여 대를 이을 씨를 바라는 사래
임신하여 여주인 사래를 멸시하는 하갈
그러한 하갈을 학대하여 내쫓는 사래

7.하나님 찾기(해석)
하나님은 왜 아브람에게 약속하신 자손을 주시지 않으셨을까?
또한 아브람과 사래가 잘못된 결정(여종하갈의 씨)을 하였을 때 막지 않으셨을까?

아마 하나님은 인간의 실수를 통해서도 기다려 주시며 실수를 스스로 깨우치고 하나님 뜻과 약속을 지키심을 몸소 깨우치게 하시는것이 아닌가 생각한다.

그런 까닭에 어느 누구보다 실패자요 실수 투성인 인간들 특별히 나를 늘 기다려 주시고 넘어저도 다시 일으켜 주시는 하나님이야말로 오래 참으심의 완성체이시다.

8.인간 찾기(해석)
하나님은 아브람에게 많은 자손을 주신다고 그의 나이 75세때 약속하셨다. 그 말씀을 들었던 아브람은 10년이 지나도 아내 사래에게 자녀 소식이 없어 그의 여종 하갈을 통하여 이스마엘을 얻게된다. 하나님 약속의 말씀을 믿고 기다림의 실패자인 아브람의 모습을 볼수있다. 이 때문에 중동 지역에는 이스라엘 백성들이 이스라엘 자손들과 더불어 분쟁과 전쟁이 끊어지지 않고 있음을 알수있다.

믿음이란 하나님의 말씀을 믿고 기다리는 것임을 깨우친다. 내가 하고 있는 사역들 중에는 대부분 돌봄사역이다. 문화와 사상이 많이 다른 지체들을 이해하고 섬기는 일은 많은 인내와 기다림이 있어야 함을 현장에서 자주 체험한다. 

내가 자칫 성급하게 일을 진행하면 또다른 이스마엘을 낳을수 있다는 경각심을 갖게된다.


9.적용(나):
과거 받았던 주님의 약속의 말씀을 붙잡고 늘 기다리며 믿음으로 살아내야겠다 

10. 영적터치(단어/구절)
1절: 아브람의 아내사래는 출산하지 못하였고 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

