4.주제 만들기: 들으시고 살피시는 하나님

5.하나님 찾기 (관찰)
- 하갈의 고통을 들으심
- 아들의 이름을 이스마엘이라 하라 말씀하심
- 이스마엘은 모든 사람을 치겠고 모든 사람의 손이 그를 칠지며 그가 모든 형제와 대항해서 살리라 말씀하심

6.인간 찾기 (관찰)
- 하갈이 하나님을 나를 살피시는 하나님이라 부름
- 하갈이 아들을 낳았고 아브람은 그 아들의 이름을 이스마엘이라 지음
- 이스마엘을 낳았을 때에 아브람은 팔십육 세였다.

7.하나님 찾기 (해석) 
- 하갈이 비록 자기 주인을 멸시한 자이지만, 하나님은 고통받는 하갈을 살피셨다.
- 고통속에 있는 하갈에게 아들과 자손에 대해 말씀하시며 희망을 주셨다.
- 하갈은 사래에게 돌아갈 힘을 얻었을 것이다.

8.인간(해석): 
- 자기를 살피시는 하나님을 경험한 하갈은 여호와의 이름을 나를 살피시는 하나님이라 불렀다.
- 하나님의 살피시는 은혜와 자손에 대한 이야기로 희망을 얻은 하갈은 용기를 내어 사래에게 돌아갈 수 있었다.
- 학대하는 주인 밑으로 다시 돌아가겠다는 결정은 쉽지 않은 결정일 것이다.
- 하갈은 아들을 낳았고 아브람은 하나님의 사자의 말대로 아들의 이름을 이스마엘이라 지음
- 하갈이 아브람에게 자기를 살피신 하나님에 대해 이야기(간증) 했을 가능성이 매우 높다.
- 이때 아브람의 나이가 팔십육 세였는데, 하나님께 자손을 약속받은 지 11년째 되는 해이다. 

9.적용(나)
- 사래에게 학대를 당하고 도망친 하갈의 기도를 들으시고 살피신 하나님께서는
- 오늘 나의 기도를 들으시며 살펴보고 계신다.
- 나의 기도를 들으시고, 나의 삶을 살피시는 하나님을 찬양하며
- 오늘도 힘을 내야겠다. 

