4. 주제만들기: 하나님의 영원한 언약
5. 하나님 찾기 (관찰)
- 전능한 하나님이고, 내 앞에서 행하여 완전하라
- 언약을 나와 너 사이에 두고 아브람을 크게 번성하게 하리라
- 내 언약이 너와 함께 있고 여러 민족의 아버지가 되며
- 아브람의 이름을 아브라함이라 하심
- 너로 심히 번성하게 하고 네게서 민족들이 나게 하며 왕들이 네게로 나오리라 하심
- 내 언약을 나와 너, 대대 후손 사이에 세워 영원한 언약을 삼고 너와 네 후손의 하나님이 되리라 
- 너와 네 후손에게 네가 거류하는 땅 가나안 온 땅을 주어 영원한 기업이 되고 그들의 하나님이 되리라 말하심
- 아브람에게 너는 내 언약을 지키고 네 후손도 대대로 지키라 말하심
6. 인간 찾기 (관찰)
- 하나님 앞에 엎드리는 아브람
- 아브람이 아브라함으로 불리기 시작
7. 하나님 찾기 (해석)
- 전능한 하나님께서 아브람 앞에 나타나 자신의 완전하심을 말씀하심으로 죄인인 인간은 하나님의 완전하심을 따라 살아갈 수 있다.
- 하나님께선 아브람에게만 적용되는 언약이 아닌 누구나 받을 수 있는 영원한 언약을 하셨다. 
- 아브람은 여러민족의 아버지로 아브라함이 되며 이를 통해 이스라엘 백성은 번성하고 민족이 세워지며 왕이 나타나게 된다. 왕은 인간을 다스리는 왕도 있지만 세상을 구원하는 왕으로 오신 예수님도 포함되는데 이를 통해 우리는 아브라함과 동일한 언약을 적용받게 된다.
- 하나님께선 아브라함 뿐 아니라 아브라함의 자손들에게도 동일한 하나님이 되겠다고 하셨는데 이 언약으로 우리는 하나님께 구원받는 은혜를 누리는 존재가 되었다.
- 하나님께서 요구하신 것은 단 하나 하나님의 언약을 지키라는 것이다.
8. 인간(해석):
9. 적용(나): 
- 인간은 하나님으로부터 값 없이 은혜를 받았다. 값 없이 주신 은혜로 하나님을 알고 목적 있는 삶을 살아간다는 것이 참으로 감사하다. 
- 하나님은 언약을 지키시는 분이다. 나도 하나님의 언약을 지키기 위해 더욱 노력해야겠다.
10. 영적터치(단어/구절)
- 7 내가 내 언약을 나와 너 및 네 대대 후손 사이에 세워서 영원한 언약을 삼고 너와 네 후손의 하나님이 되리라
