INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-13', '창세기', '17장 11절 ~ 20절', '', 'ㅣ(창세기 17장)
11. 너희는 포피를 베어라 이것이 나와 너희 사이의 언약의 표징이니라
12. 너희의 대대로 모든 남자는 집에서 난 자나 또는 너희 자손이 아니라 이방 사람에게서 돈으로 산 자를 막론하고 난 지 팔 일 만에 할례를 받을 것이라
13. 너희 집에서 난 자든지 너희 돈으로 산 자든지 할례를 받아야 하리니 이에 내 언약이 너희 살에 있어 영원한 언약이 되려니와
14. 할례를 받지 아니한 남자 곧 그 포피를 베지 아니한 자는 백성 중에서 끊어지리니 그가 내 언약을 배반하였음이니라
15. 하나님이 또 아브라함에게 이르시되 네 아내 사래는 이름을 사래라 하지 말고 사라라 하라
16. 내가 그에게 복을 주어 그가 네게 아들을 낳아 주게 하며 내가 그에게 복을 주어 그를 여러 민족의 어머니가 되게 하리니 민족의 여러 왕이 그에게서 나리라
17. 아브라함이 엎드려 웃으며 마음속으로 이르되 백 세 된 사람이 어찌 자식을 낳을까 사라는 구십 세니 어찌 출산하리요 하고
18. 아브라함이 이에 하나님께 아뢰되 이스마엘이나 하나님 앞에 살기를 원하나이다
19. 하나님이 이르시되 아니라 네 아내 사라가 네게 아들을 낳으리니 너는 그 이름을 이삭이라 하라 내가 그와 내 언약을 세우리니 그의 후손에게 영원한 언약이 되리라
20. 이스마엘에 대하여는 내가 네 말을 들었나니 내가 그에게 복을 주어 그를 매우 크게 생육하고 번성하게 할지라 그가 열두 두령을 낳으리니 내가 그를 큰 나라가 되게 하려니와
