1:감동받는 단어나 구절 찾기(영적터치)
2024년 9월07일 창세기 17장11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
할례: 11절 12절 13절 14절 
언약: 11절 13절(2) 14절 19절 
복: 16절 20절
사라: 15절 16절 19절
4.주제만들기: 
언약의 상징 할례
5.하나님 찾기 (관찰)
영원한 표징인 할례를 아브라함과 그의 속한 남자들에게 할것을 명하시는 하나님
사래를 이제는 사라로 부르게 하시는 하나님 
백세에 아들을 주겠다고 하실때 웃고 받아들이지 못하는 아브라함 에게 질타하시는 하나님
아브라함의 아들의 이름을 ''이삭''으로 정해주신 하나님
6.인간 찾기 (관찰)
백세에 아들을 주신다는 하나님 말씀에 믿지 못하여 웃는 아브라함
단호하신 하나님 말씀에 믿고 할례를 거행하는 아브라함
7.하나님 찾기(해석)
하나님은 아브라함을 향하여 단호하게 "아니라" 말씀 하셨다. 90세가 거의 된 아내 사라가 생리학적인 한계로 출산을 하지 못할 것이라 알고 있는 아브라함은 사라를 통하여 출산케 하신다는 하나님의 말씀을 믿지못하여 웃고 만다.
그러한 아브라함에게 전능하신 하나님은 스스로의 권의를 나타내사 강력하게 아브라함이 순종하고 받아들일 수 밖에 없는 능력의 말씀을 선포하신다.
우주 만물을 창조하시고 무에서 유를 만드시는 하나님을 믿는다면 누구든지 전능하신 하나님을 인정할 것이고 구할것이다.
하나님은 아브라함에게 복을 주시고 그를 포함한 많은 민족과 자손들에게도 복을 주실 것을 영원한 언약을 하셨다.
이 시대는 영원한 언약의 표징이신 예수그리스도를 마음으로 믿고 그 마음에 새긴다면 그 자체로 영적 할례 받은 것을 인정받아 영원토록 언약의 복을 누리도록 허락하셨다
8.인간 찾기(해석)
아브라함은 믿기 어려운 사실을 결론적으로 믿고 따랐다. 증거로는 자신과 그의 가족을 포함 한 모든 주변 사람들에게 영원한 할례를 행하였다. 
당장 현실에서 해결할 수 없는 문제처럼 보일지라도 크신 하나님의 언약을 믿고 따른다면 반드시 응답의 역사는 이루어진다
9.적용(나):
하나님이 주시겠다고 하면 아멘으로 화답하며 살아야겠다 
그 내용이 현실적으로 이루기 쉬어보이지 않더라도 굳게믿어야 겠다
내년 8월초에 우리 NKFC M 팀원들과 미국 샌프란시스코 금문교 가서 전도할 것을 선포했다
이 일이 이루어질 것을 믿고 준비해야겠다
10. 영적터치(단어/구절)
19절: 아니라 네 아내 사라가 네게 아들을낳으리니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-14', '창세기', '17장 21절 ~ 27절', '', 'ㅣ(창세기 17장)
21. 내 언약은 내가 내년 이 시기에 사라가 네게 낳을 이삭과 세우리라
22. 하나님이 아브라함과 말씀을 마치시고 그를 떠나 올라가셨더라
23. 이에 아브라함이 하나님이 자기에게 말씀하신 대로 이 날에 그 아들 이스마엘과 집에서 태어난 모든 자와 돈으로 산 모든 자 곧 아브라함의 집 사람 중 모든 남자를 데려다가 그 포피를 베었으니
24. 아브라함이 그의 포피를 벤 때는 구십구 세였고
25. 그의 아들 이스마엘이 그의 포피를 벤 때는 십삼 세였더라
26. 그 날에 아브라함과 그 아들 이스마엘이 할례를 받았고
27. 그 집의 모든 남자 곧 집에서 태어난 자와 돈으로 이방 사람에게서 사온 자가 다 그와 함께 할례를 받았더라

