4.주제만들기: 
할례를 행하는 아브라함 집안 모든 남자들

5.하나님 찾기 (관찰)
일년후 이삭 아들을 아브라함에게 주시겠다고 말씀하시는 하나님
올라가시는 하나님

6.인간 찾기 (관찰)
자신과 이스마엘을 포함해서 집안 모든 남자들에게 할례를 거행케 하는 아브라함

7.하나님 찾기(해석)
하나님은 아브라함에게 영원한 언약의 표징인  ''할례'' 를 할것을 명령하셨다. 그런데 하나님은 본 부인 사라를 통하여 예비하신 혈통인 ''이삭'' 뿐만 아니라 이스마엘과 심지어는 함께 거주하는 이방인들까지 할례를 명령하셨다.

영적 순결한 혈통을 강조하신 하나님은 왜 이렇게 명령하셨을까?

아마 하나님은 육적인 할례를 한 민족으로 국한시키지 않으시고 믿는 모든 이방민족 까지 염두해 놓으신 모든 열방의 하나님이신 것을 일깨워 주고 계심이 확실해 보인다.

8.인간 찾기 (해석)
하나님의 명하시는 말씀(일년후 이삭을 주시겠다고 하심) 이성적으로는 당장 이해는 되지 않더라도 믿고 순종하여 할례를 거행하는 아브라함의 모습을 볼 수 있다.

이러한 모습을 하나님은 기뻐하시는 것 같다.

9.적용(나):
모든 민족을 자신의 자녀로 삼기를 원하시는 하나님의 마음을 품고 오늘도 열심히 한강전도(내국인과 외국인들)에 힘써야겠다.

10. 영적터치(단어/구절)
27절: 이방 사람에게서 사온 자가 다 그와 함께 할례를 받았더라 

