2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 종(3,5절), 떡(5,6절), 송아지(7,8절), 여호와(1,2,5,9,10절), 아브라함(1,2,5,6,7,8,9절), 사라(9,10절), 보다(2절), 장막(2,6,9,10절
4. 주제만들기: 영의 눈으로 하나님을 본 아브라함
5. 하나님 찾기 (관찰)
- 마므레의 상수리나무 있는 곳에서 아브라함에게 나타나심
- 아브라함에게 간청대로 하라고 말하심
- 사라가 어디있는지 물의심
- 내년 이맘때 반드시 네 개로 돌아오리니 사라에게 아들이 있으리라 말씀하심 
6. 인간 찾기 (관찰)
- 아브라함은 날이 뜨거울 때 장막 문에 앉아 있다가 눈을 들어 사람 셋이 맞은 편에 있는 것을 봄
- 장막 문에서 달려나가 영접하며 몸을 땅에 굽혀 여호와를 맞이함
- 은혜를 입었사오면 종을 떠나 지나가지 말게하시고 물을 조금 가져오게 하사 발을 씻으시고 나무 아래에서 쉬길 간청함
- 떡을 조금 가져오리니 마음을 상쾌하게 한 후에 지나가시길 요청함
- 급히 장막으로 들어가 사라에게 고운 반죽으로 떡을 만들라하고 좋은 송아지를 잡아 하인에게 급히 요리를 시킴
- 엉긴 젖과 우유와 요리한 송아지를 그들 앞에 차려 놓고 나무 아래로 모심
- 사라는 장막 문 뒤에서 내년 이맘 때 아들과 함께 있을 것이라는 말을 들음
7. 하나님 찾기 (해석) 
- 하나님은 아브라함이 영의 눈을 뜨길 기다리신 것일까? 17장에 나타나 말씀하셨음에도 다시 아브라함 앞에 나타나셨다. 
- 아브라함의 간청을 못 이긴척 받아주시고 식사를 하시며 다시 사라가 아들을 낳을 것이라고 말씀하시는데 아브라함의 믿음을 시험하신 것이 아니라 사라의 믿음과 순종을 기다리신 것 같은 느낌이 든다. 
8. 인간(해석):
- 17장에서 아브라함은 하나님의 말씀에 웃으며 백세 된 사람이 어찌 자식을 낳으며, 사라는 구십세니 어찌 출산할까라는 모습을 보였지만, 다른 사람이 되었다.
- 아브라함을 하나님을 기다린 것처럼 뜨거운 날에 장막 문에 앉아 있었다. 그리고 여호와를 발견한 후에 달려나가 영접했는데 분명한 하나님의 때를 기다렸던 것 같다.
- 아브라함은 예전과 달리 간절히 사모하는 마음으로 여호와를 맞이한다. 가장 좋은 것으로 여호와께 대접하며 그 곳에 머물러가길 요청한다. 우리가 바라는 것들, 그것을 하나님께서 주시겠다고 언약했다하더라도 하나님께 간절한 마음, 사모하는 마음을 품어야 함을 깨닫는다. 
9. 적용(나): 
- 하나님을 간절히 사모하는 마음이 내 안에 가득하길 원한다.
- 하나님께 가장 좋은 것을 드릴 수 있는 마음과 용기, 결단이 생기길 기도한다.
- 가장으로 영적으로 바로서는 것이 중요하고 가정 안에 배우자도 같은 마음을 품어야함을 깨닫는다. 아내가 성령님과 더욱 친밀해지길 소망한다.
10. 영적터치(단어/구절)
- 2 그가 그들을 보자 곧 장막 문에서 달려나가 영접하며 몸을 땅에 굽혀
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

