4.주제 만들기: 하나님께서 아브라함의 자손을 통해 이루실 일 

5.하나님 찾기 (관찰)
- 사라의 비웃음을 지적하시며, 내년 이 맘 때에 사라에게 아들이 있을 것이다 말씀하심
- 아브라함은 강대한 나라가 되고 천하 만민은 그로 말미암아 복을 받게 될 것이라 말씀하심
- 아브라함의 자식과 권속에게 명하여 여호와의 도를 지켜 
- 의와 공도를 행하게 하려고 아브라함을 택하였다 말씀하심
- 나 여호와가 아브라함에게 대하여 말한 일을 이루려 함이니라 말씀하심
- 소돔과 고모라에 대한 부르짖음이 크고 그 죄악이 심히 무겁다 말씀하심

6.인간 찾기 (관찰)
- 생리가 끊긴 사라가 내게 무슨 즐거움이 있겠느냐 생각하며 속으로 웃음
- 하나님께서 사라의 웃음과 생각에 대해 지적하자,
- 사라는 그런 적 없다고 부인함

7.하나님 찾기 (해석) 
- 믿음이 약하여 비웃는 사라에게 자신의 전능하심에 대해 말씀하심.
- 두려워 웃지 않았다 거짓말하는 사라에게
- 아니다 네가 웃었다 라고 정확하게 말씀하시며 전지하심을 보이심.
- 아브라함을 통해 천하 만민이 복을 받을 것과
- 아브라함을 택하여 그 자손에게 바라시는 것을 말씀하심
- 하나님은 아브라함이 자식과 자손을 잘 가르쳐 
- 자손들이 하나님께 순종하고, 올고 바른 일을 하기를 원하심 
- 이를 통해 하나님은 아브라함에게 말한 일을 이루려 하심
- 소돔과 고모라의 부르짖음과 죄악이 차기를 기다리시던 하나님은
- 이제 소돔과 고모라에 가시는 이유에 대해 말씀하심


8.인간(해석): 
- 자신이 웃으며 생각한 것을 알고 계신 하나님을 보며 
- 하나님은 내 마음속 생각까지도 다 아시는구나 느끼며 두려웠을 것이고, 그 상황을 벗어나고 싶었을 것임.
- 거짓말하는 것을 정확히 아시고 말씀하시는 하나님의 전지하심을 체험했으며,
- 확실한 체험을 한 사라는 믿음이 확고해 지는 계기가 되었을 것이다.
- 아브라함은 하나님의 말씀을 들으며,
- 사람의 마음과 세상에 대해 자세히 알고 계시며
- 일의 진행과 역사하시는 모습을 보며 하나님을 더욱 경외하게 되었을 것이다.

9.적용(나)
- 나의 마음을 감찰하시고 내 뜻을 다 알고 계시는 하나님 앞에서
- 사라와 같이 비웃는 불신앙과 불순종은 없는지 
- 그리고 내 거짓이 드러나 회피하고 싶은 마음은 없는지 점검해야 한다.
- 성령 하나님께서 날 위해 탄식하며 기도하시는 것이 이런 내용이 아닐까 생각해 본다. 

10. 영적터치(단어/구절)  
  19   내가 그로 그 자식과 권속에게 명하여 여호와의 도를 지켜 의와 공도를 행하게 하려고 그를 택하였나니 이는 나 여호와가 아브라함에게 대하여 말한 일을 이루려 함이니라

11. 믿음과 회개 및 감사기도로 마무리
