2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
아브라함: 22절 23절 27절 29절 30절 31절 32절 33절
의인: 23절 24절(2) 25절 26절 27절
악인: 23절 25절(2) 
