4.주제만들기: 
소돔의 멸망을 막기위하여 하나님께 비는 아브라함 

5.하나님 찾기 (관찰)
아브라함 의 간청(의인 10명 있으면 조카 롯이 있는 소돔성을 멸망시키지 않음)을 들어주시는 하나님, 결국 의인 10명이 없어 불의 멸망을 받음

6.인간 찾기 (관찰)
하나님께 조카 롯이 있는 소돔성을 멸망시키시키고자 하는 하나님께 긴청하는 아브라함(의인 50명,45명,40명,30명,20명,10명)

7.하나님 찾기(해석)
하나님은 소돔과 고모라 성을 불의 심판으로 멸망시킬 것을 미리 아브라함 에게 알려주셨다. 기회를 많이 주고 스스로 회개하고 돌아오기를 기다렸던 주님이 이제는 심판의 결정을 내리시기 직전이다.  

하나님은 우리에게 회개할 많은 시간과 기회를 주신다.  그때라도 돌이키고 회개하며 돌아오기를  누구보다 더욱 바라시는 분 이시다.

아브라함 하나님께 소돔성안에 의인 10명 이상 있으면 용서해 달라고 간청할때 들어주신다.

8.인간 찾기 (해석)
조카 롯을 살리기 위하여 끝까지 하나님께 매달리는 아브라함의 조카사랑을 볼수있다.

9.적용(나):
의인 10명을 찾으시는 하나님!!
나로 인하여 가족이 살고 NKFC M 공동체가 함께 복을 받을수 있도록 의인의 반열에 들어가도록 힘써야겠다 

10. 영적터치(단어/구절)
32절: 십명으로 말미암아 멸하지 아니하리라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-18', '창세기', '19장 1절 ~ 10절', '소돔의 더러운 죄', '창세기 19장
1   저녁 때에 그 두 천사가 소돔에 이르니 마침 롯이 소돔 성문에 앉아 있다가 그들을 보고 일어나 영접하고 땅에 엎드려 절하며
2   이르되 내 주여 돌이켜 종의 집으로 들어와 발을 씻고 주무시고 일찍이 일어나 갈 길을 가소서 그들이 이르되 아니라 우리가 거리에서 밤을 새우리라
3   롯이 간청하매 그제서야 돌이켜 그 집으로 들어오는지라 롯이 그들을 위하여 식탁을 베풀고 무교병을 구우니 그들이 먹으니라
4   그들이 눕기 전에 그 성 사람 곧 소돔 백성들이 노소를 막론하고 원근에서 다 모여 그 집을 에워싸고
5   롯을 부르고 그에게 이르되 오늘 밤에 네게 온 사람들이 어디 있느냐 이끌어 내라 우리가 그들을 상관하리라
6   롯이 문 밖의 무리에게로 나가서 뒤로 문을 닫고
7   이르되 청하노니 내 형제들아 이런 악을 행하지 말라
8   내게 남자를 가까이 하지 아니한 두 딸이 있노라 청하건대 내가 그들을 너희에게로 이끌어 내리니 너희 눈에 좋을 대로 그들에게 행하고 이 사람들은 내 집에 들어왔은즉 이 사람들에게는 아무 일도 저지르지 말라
9   그들이 이르되 너는 물러나라 또 이르되 이 자가 들어와서 거류하면서 우리의 법관이 되려 하는도다 이제 우리가 그들보다 너를 더 해하리라 하고 롯을 밀치며 가까이 가서 그 문을 부수려고 하는지라
10   그 사람들이 손을 내밀어 롯을 집으로 끌어들이고 문을 닫고

