2024년 9월 12일 창세기 19장 1~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)

4.주제 만들기: 소돔의 더러운 죄
소돔: 1(2), 4
롯: 1, 3(2), 5, 6, 9, 10
밤: 2, 5
집: 2, 3, 4, 8, 10
문: 6(2), 9, 10
이끌어: 5, 8
사람들: 5, 8(2), 10

5.하나님 찾기 (관찰)
- 소돔을 멸하기 위해 소돔으로 천사 두 명을 보내심

6.인간 찾기 (관찰)
- 소돔 성에 두 천사가 이르자 소돔 성문에 앉아 있던 롯이 일어나 영접하고
- 자신의 집으로 초대함
- 두 천사가 거절하였으나 롯이 간청하여 두 천사가 롯의 집으로 들어감
- 롯이 그들을 위하여 식사를 대접함
- 소돔 사람들이 늙은이 젊은이 할 것 없이 다 모여 롯의 집을 에워싸고
- 롯을 부르며 오늘 밤에 온 사람들과 육체적 관계를 갖겠으니 데려나오라고 말함
- 롯이 나가서 문을 닫고 악을 행하지 말라고 하며
- 자기 딸을 이끌어 오리니 그들과 육체적 관계를 갖으라고 말함
- 소돔 사람들은 거부하며 롯을 조롱하며 밀치고 문을 부수려고 함
- 천사들이 롯을 집으로 끌어들이고 문을 닫음

7.하나님 찾기 (해석) 
- 

8.인간(해석): 
- 롯이 나그네로 보이는 두 천사를 영접함
- 관습대로 모든 나그네에게 그렇게 대했는지 두 천사에게만 그렇게 한 것인지 나는 모르겠으나, 롯은 아브라함과 같이 선한 행동을 했다.
- 소돔 사람들이 롯에게 한 말을 보면 그들이 성적으로 얼마나 타락했는지 유추해 볼 수 있다.
- 새번역 성경을 보면 소돔 사람들은 두 천사를 남자들이라고 부른다. 소돔 사람들은 동성애에 취해 있는 상태이며, 남자 나그네들이 오면 강제로 육체적 관계를 갖은 것으로 보인다.
- 성적으로 이렇게 타락한 것을 보면, 당시 소돔에서 인격 유린이 얼마나 심했으며, 
- 다른 죄들 또한 얼마나 많이 지었을지 짐작할 수 있다.
- 이들에게 두 딸을 주겠다고 말하는 롯을 보면, 첫째 두 천사를 보호하려는 것은 선한 의도이지만,
- 두 딸을 성적 노리개로 희생시키려고 하는 것을 보면 소돔의 문화에 젖어 있었음을 알 수 있다.

9.적용(나)
- 성경의 짧은 내용만 보아도 소돔의 죄는 극에 달했던 것으로 보인다.
- 내 속의 죄가 극에 달한 것은 없는 지 점검해 봐야 하며,
- 롯이 소돔의 문화에 젖어든 것을 보면,
- 나 또한 세상의 타락한 문화에 젖어 있을 가능성이 있다.
- 하나님의 거룩하심을 따라 세상과 구별된 삶을 살아야한다.
- 세상 문화에 젖는 것이 아니라, 세상에 하나님 나라 문화를 전하는 삶을 살아야한다. 

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-19', '창세기', '19장 11절 ~ 20절', '롯을 구원하신 하나님', '[창19:11-20]
11 문 밖의 무리를 대소를 막론하고 그 눈을 어둡게 하니 그들이 문을 찾느라고 헤매었더라
12 그 사람들이 롯에게 이르되 이 외에 네게 속한 자가 또 있느냐 네 사위나 자녀나 성 중에 네게 속한 자들을 다 성 밖으로 이끌어 내라
13 그들에 대한 부르짖음이 여호와 앞에 크므로 여호와께서 이곳을 멸하시려고 우리를 보내셨나니 우리가 멸하리라
14 롯이 나가서 그 딸들과 결혼할 사위들에게 말하여 이르기를 여호와께서 이 성을 멸하실 터이니 너희는 일어나 이곳에서 떠나라 하되 그의 사위들은 농담으로 여겼더라
15 동틀 때에 천사가 롯을 재촉하여 이르되 일어나 여기 있는 네 아내와 두 딸을 이끌어 내라 이 성의 죄악 중에 함께 멸망할까 하노라
16 그러나 롯이 지체하매 그 사람들이 롯의 손과 그 아내의 손과 두 딸의 손을 잡아 인도하여 성 밖에 두니 여호와께서 그에게 자비를 더하심이었더라
17 그 사람들이 그들을 밖으로 이끌어 낸 후에 이르되 도망하여 생명을 보존하라 돌아보거나 들에 머물지 말고 산으로 도망하여 멸망함을 면하라
18 롯이 그들에게 이르되 내 주여 그리 마옵소서
19 주의 종이 주께 은혜를 입었고 주께서 큰 인자를 내게 베푸사 내 생명을 구원하시오나 내가 도망하여 산에까지 갈 수 없나이다 두렵건대 재앙을 만나 죽을까 하나이다
20 보소서 저 성읍은 도망하기에 가깝고 작기도 하오니 나를 그 곳으로 도망하게 하소서 이는 작은 성읍이 아니니이까 내 생명이 보존되리이다

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 문(11절), 롯(12,14,15,16,18절), 성(12,14,15절), 성읍(19,20절), 멸하다(13,15,17절), 딸(14,16절), 도망(17,19,20절)
4. 주제만들기: 롯을 구원하신 하나님
5. 하나님 찾기 (관찰)
- 롯에게 네게 속한자가 더 있느냐고 물으심
- 네게 속한자를 성 밖으로 이끌어내라고 명령하심
- 그들에 대한 부르심이 커 여호와께서 이곳을 멸하시려 천사들을 보냈다고 말함
- 롯과 아내와 두 딸의 손을 잡아 인도하여 성 밖에 둠
- 생명을 보존하고 돌아보거나 들에 머물지 말고 산으로 도망하여 멸망함을 면하라고 명령하심
6. 인간 찾기 (관찰)
- 롯이 천사들의 말을 딸과 사위들에게 전하자 사위들은 농담으로 여김
- 롯이 지체함
- 롯은 산으로 도망하라는 천사들의 명령에 산까지 갈 수 없으니 가까운 성읍으로 도망가도록 요청함
7. 하나님 찾기 (해석)
- 하나님께선 단 한명이라도 더 구원해주시고자 롯을 통해 기회를 주셨다. 예수님께서 오셔서 우리를 위해 십자가를 지신 것처럼 하나님의 사랑은 구약의 때나 신약의 때나 동일했다. 
- 하나님께선 롯을 구원하고자 천사들을 보내셨고, 도망을 주저하여 지체하는 롯을 직접 이끌어 안전한 곳으로 인도해주셨다. 하나님의 값 없는 사랑은 어떠한 조건 없이 무조건 적인 사랑이다. 롯을 구원하지 않더라도 하나님의 일을 이루어질 것이다. 그런데 롯을 위해 천사를 보내시고 롯을 대피시키시며, 롯의 요구를 들어 가까운 곳으로 대피할 수 있도록 해주신다. 
8. 인간(해석):
- 롯은 천사들의 명령에 지체하였다. 그저 도망가는 시간이 늦었다고 생각할 수 있지만 성이 멸망할 것이라는 말에 사위들이 믿지 않자 롯은 의심하며 주저했을 수 있다. 우리가 죄에서 벗어나지 못하고 주저하는 것처럼 예수님을 위해 결단하지 못하는 연약한 믿음을 볼 수 있다.
- 그럼에도 불구하고 하나님은 자비를 더해주셨다. 구원 받을 수 없는 존재, 구원 받을 수 없는 삶을 살았음에도 하나님의 사랑은 모든 상황과 환경을 덮으신다. 두려움에 빠진 롯이 안전한 산으로 도망하기 보다 눈 앞에 가깝고 안전해 보이는 작은 성읍에 들어가고자 함에도 하나님께선 그것을 허락하신다. 
- 하나님은 우리의 어이없는 요청에도 사랑으로 이해하신다.  
9. 적용(나): 
- 롯과 같이 지체하고 있는 나의 죄성을 성령님의 도우심으로 끊어지도록 간구하며 기도해야겠다. 
- 하나님의 사랑에 감사하며 하나님을 경외하고 하나님이 기뻐하시는 삶에 집중해야겠다.
10. 영적터치(단어/구절)
- 13 우리를 보내셨나니 
- 16 여호와께서 그에게 자비를 더하심이었더라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-20', '창세기', '19장 21절 ~ 30절', '&nbsp;', '(창세기 19장)
21. 그가 그에게 이르되 내가 이 일에도 네 소원을 들었은즉 네가 말하는 그 성읍을 멸하지 아니하리니
22. 그리로 속히 도망하라 네가 거기 이르기까지는 내가 아무 일도 행할 수 없노라 하였더라 그러므로 그 성읍 이름을 소알이라 불렀더라
23.  롯이 소알에 들어갈 때에 해가 돋았더라
24. 여호와께서 하늘 곧 여호와께로부터 유황과 불을 소돔과 고모라에 비같이 내리사
25. 그 성들과 온 들과 성에 거주하는 모든 백성과 땅에 난 것을 다 엎어 멸하셨더라
26. 롯의 아내는 뒤를 돌아보았으므로 소금 기둥이 되었더라
27. 아브라함이 그 아침에 일찍이 일어나 여호와 앞에 서 있던 곳에 이르러
28. 소돔과 고모라와 그 온 지역을 향하여 눈을 들어 연기가 옹기 가마의 연기같이 치솟음을 보았더라
29. 하나님이 그 지역의 성을 멸하실 때 곧 롯이 거주하는 성을 엎으실 때에 하나님이 아브라함을 생각하사 롯을 그 엎으시는 중에서 내보내셨더라
30.  롯이 소알에 거주하기를 두려워하여 두 딸과 함께 소알에서 나와 산에 올라가 거주하되 그 두 딸과 함께 굴에 거주하였더니

