4.주제만들기: 
소돔과 고모라를 멸하시는 하나님

5.하나님 찾기 (관찰)
여호와께서 소돔과 고모라를 유황과 불로 심판하심
하나님이 아브라함을 생각하사 롯을 구원하심

6.인간 찾기 (관찰)
뒤를 돌아보아 소금 기둥이 된 롯의 아내
롯이 두딸과 더불어 소알에서 동굴로 피신함

7.하나님 찾기(해석)
오래참으심의 대가 이신 하나님은 소돔과 고모라에 죄악이 가득하여 드디어 말씀대로 그곳에 불의 심판을 내리셨다. 

지금 살고있는 이시대와 당시 소돔과 고모라의 죄악을 비교한다면 과연 이시대가 죄의 무게가 가볍다고 생각할수 있을까?

떨리고 두려운 마음으로 나부터 더욱 거룩하게 살아내야겠다.

8.인간 찾기 (해석)
뒤를 돌아본 롯의 아내는 뒤를 돌아보아 결국 소금기둥이 되었다. 나를 포함해서 누구한테나 적용될수 있는 부분이다. 늘 익숙한곳, 나름 재미있었던 추억의 장소가 심판받는 곳이라면 벗어나야한다.  롯의 아내는 아마 크신 하나님 심판자되신 하나님을 평상시에 알았다면 죄의 달콤함의 영역의 미련에서 싑게 벗어날수 있었을것이다.

롯은 스스로가 의인 이었기 때문에 심판의 자리에서벗어난것 보다 믿음의 사람이요 백부였던 아브라함의 중보의 힘이 더욱 작동되었다고 볼수있다.  평상시 자신을 위하여 조언해주고 진심으로 기도해주는 맨토가 얼마나 중요한지 알게해준다.

9.적용(나):
과거에 조금이라도 느꼈던 거룩하지못한 생각이나 추억들을 돌아보지 말고오직  주님만을 더욱 바라보며 오늘도 전진해야겠다 

10. 영적터치(단어/구절)
26절: 롯의 아내는 뒤를 돌아보았으므로 소금 기둥이 되었더라

