1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 아브라함(1,2,5,7,9,10절), 사라(2,3,4,5,6,7절), 아비멜렉(2,3,4,6,8,9,10절), 하나님(3,4,6절), 누이(2,5절), 온전한 마음(5,6절), 죄(6,9절)
4. 주제만들기: 온전한 자의 죄를 막아주시는 하나님
5. 하나님 찾기 (관찰)
- 아비멜렉에게 나타나 죄를 짓지 않도록 막아주신 하나님
6. 인간 찾기 (관찰)
- 아브라함은 창세기 12장에서처럼 네게브 땅의 아비멜렉 왕에게 자신의 아내를 누이라 속이며 내어주었다.
- 아비멜렉은 꿈에 나타나신 하나님에게 아브라함이 누이라 속였고, 여인을 가까이 하지 않았으며, 온전한 마음과 깨끗한 손으로 하였음을 고백한다.
- 아비멜렉과 종들은 지난밤 꿈의 이야기를 듣고 심히 두려워한다.
- 아비멜렉은 아브라함을 불러 무슨 뜻으로 이렇게 하였는지 묻는다.
7. 하나님 찾기 (해석) 
- 하나님은 운전한 자를 보호하시는 분이다. 아브라함을 보호하기 위하여 아비멜렉에게서 지켜주신 것처럼 보이지만 하나님께선 아비멜렉도 사랑하는 분이다. 
- 그렇기 때문에 아비멜렉의 온전한 마음과 깨끗한 손을 아시고 아비멜렉을 죄에 빠지지 않도록 보호해주셨다. 
- 우리도 하나님을 향한 온전한 마음과 깨끗한 손을 행한다면 하나님께서 죄를 짓지 않도록 보호해주실 것이다.
8. 인간(해석):
- 아브라함은 지난 과오를 다시 저지른다. 하나님과 동행하고 있음에도 불구하고 당장 직면한 현실적인 문제에 인간의 연약함이 수면 위로 떠올랐다. 아마 나여도 같은 선택을 했을 것 같다.
- 그럼에도 하나님께선 아브라함을 보호해주셨다. 하나님이 하고자 하시면 아무 조건 없이 무조건적인 사랑과 은혜가 주어진다. 아브라함뿐 아니라 이 시대를 살아가는 우리 모두가 조건 없는 사랑과 은혜를 받으며 살아가고 있다. 
- 이 사실을 깨닫는 사람과 깨닫지 못한 사람으로 나누어져 있을 뿐이다...
- 아비멜렉은 온전한 마음과 깨끗한 손을 행하는 사람이었다. 그렇기에 하나님은 아비멜렉도 보호해주신다. 아비멜렉은 하나님을 경외하는 마음이 강했던 것 같다. 분명 하나님께서 막아주셨다는 것을 말했음에도 다음날 종들과 이 일에 대해 논의 두려운 마음을 가졌다. 
- 마지막으로 믿는 자들도 이기적인 마음과 욕심에 다른 사람을 곤경에 빠지게 할 수 있음을 깨닫는다. 늘 하나님과 동행하며 하나님의 뜻을 묻고 실천하는 것이 중요하다.
9. 적용(나): 
- 온전한 마음과 깨끗한 손을 실천해야겠다. 
- 나의 행동이 거룩함을 포장해 다른 이에게 곤란하게 할 수 있는 것은 없는지 점검해야겠다.
- 하나님을 알지 못하는 자들을 위해 노방전도에 힘써야겠다.
10. 영적터치(단어/구절)
-  6 너를 막아 내게 범죄하지 아니하게 하였나니 여인에게 가까이 하지 못하게 함이 이 때문이니라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

