16   사라에게 이르되 내가 은 천 개를 네 오라비에게 주어서 그것으로 너와 함께 한 여러 사람 앞에서 네 수치를 가리게 하였노니 네 일이 다 해결되었느니라
17   아브라함이 하나님께 기도하매 하나님이 아비멜렉과 그의 아내와 여종을 치료하사 출산하게 하셨으니
