- 이것이 첫 번째가 아니라 두 번째라는 것은 아브라함이 얼마나 나약한 존재인지를 보여준다.
- (이때의 사라의 나이는 89세이다.)
- 사라를 데려간 일로 하나님을 만난 아비멜렉은 하나님을 경외하게 되었으며,
- 자신의 재산을 아끼지 않고 아브라함과 사라를 위해 내어주었다.
- 하나님의 돌보심을 경험한 아브라함이 아비멜렉을 위해 기도함.

