2024년 9월18일 창세기 21장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
여호와께서 말씀하신대로:1절(2)
낳은 아들: 2절 3절(2) 7절
이삭: 3절 4절 5절 8절 9절 10절

4.주제만들기: 
이삭의 출생

5.하나님 찾기 (관찰)
말씀대로 이삭을 출생시키신 하나님
할례를 명령하신 하나님

6.인간 찾기 (관찰)
이삭을 낳은 사라(90세)
출생 팔 일 만에 이삭을 할례시킨 아브라함 
이삭을 놀리는 하갈의 아들 이스마엘
그러한 이스마엘을 쫓아내기를 원하는 사라

7.하나님 찾기(해석)
하나님은 말씀하신대로 노년의 아브라함 에게 아들 ''이삭''을 득남케 하셨다. 이일로 아내 사라는 웃음을 가졌다. 불과 1년전에는 믿지 못하는 웃음을 보였던 사라는 이제는 은혜의 웃음으로 바뀌었다. 

아들 이삭도 분의기에 걸맞쳐 웃음 이라는 의미로 이미 지어주셨다. 

우리가 이성적으로 받아들이조차 쉽지않은 미래의 일 이라고 하더라도 기적을 통하여 역사하시는 하나님은  우리를 웃게하실수 있는 분이시다.

또한 불가능을 가능케 하신 하나님은 우리의 전능자이심을 일깨움을 주신다.

8.인간 찾기 (해석)
100세에 아이를 갖는것은 기적이다. 하지만 하나님이 말씀하시면 기적이 상식이 되듯 간단하고 쉬운 일임을 성경안에서 쉽게 찾아볼수 있다.

인간편에서 보면 그 일이 상식적인 기적이라고 하더라도 반드시 하나님이 말씀 하심을 받아야 되고 믿음으로 기다려야 한다는 깨우침이다.

그러면 인간이 당장 할 일은 거의 없는듯 하다.

그럼에도 하나님은 분명 당장 할일을 주셨다. 그것은 이삭에게 할례를 명령하신 하나님 말씀에 순종하는 것이다.

이삭을 받는것은 받는 수동적으로 일이지만 할례를 행하는 것은 능동적으로 행하는 일임을 보여준다.

기다림과 행함을 균형있게 생활한다면 더욱 주님과 안정된 교제를 체험하게 될것이라 여겨진다.

9.적용(나):
과거 하나님께 받았던 약속의 말씀을 더욱 굳게 믿고 살아내야겠다 

10. 영적터치 (단어 또는 구절)
1절: 여호와께서 말씀하신 대로 사라를 돌보셨고

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-25', '창세기', '21장 11절 ~ 20절', '쫓겨나는 하갈과 이스마엘', '창세기 21장
11   아브라함이 그의 아들로 말미암아 그 일이 매우 근심이 되었더니
12   하나님이 아브라함에게 이르시되 네 아이나 네 여종으로 말미암아 근심하지 말고 사라가 네게 이른 말을 다 들으라 이삭에게서 나는 자라야 네 씨라 부를 것임이니라
13   그러나 여종의 아들도 네 씨니 내가 그로 한 민족을 이루게 하리라 하신지라
14   아브라함이 아침에 일찍이 일어나 떡과 물 한 가죽부대를 가져다가 하갈의 어깨에 메워 주고 그 아이를 데리고 가게 하니 하갈이 나가서 브엘세바 광야에서 방황하더니
15   가죽부대의 물이 떨어진지라 그 자식을 관목덤불 아래에 두고
16   이르되 아이가 죽는 것을 차마 보지 못하겠다 하고 화살 한 바탕 거리 떨어져 마주 앉아 바라보며 소리 내어 우니
17   하나님이 그 어린 아이의 소리를 들으셨으므로 하나님의 사자가 하늘에서부터 하갈을 불러 이르시되 하갈아 무슨 일이냐 두려워하지 말라 하나님이 저기 있는 아이의 소리를 들으셨나니
18   일어나 아이를 일으켜 네 손으로 붙들라 그가 큰 민족을 이루게 하리라 하시니라
19   하나님이 하갈의 눈을 밝히셨으므로 샘물을 보고 가서 가죽부대에 물을 채워다가 그 아이에게 마시게 하였더라
20   하나님이 그 아이와 함께 계시매 그가 장성하여 광야에서 거주하며 활 쏘는 자가 되었더니

