4.주제 만들기: 쫓겨나는 하갈과 이스마엘

5.하나님 찾기 (관찰)
- 근심하는 아브라함에게 사라의 말대로 하라고 말씀하시며
- 이삭에게서 나는 자가 네 씨라고 말씀하심
- 이스마엘도 네 씨니 이스마엘도 한 민족을 이루게 하리라 말씀하심
- 이스마엘의 소리를 들으심
- 하갈에게 아이의 손을 붙들라 하시며, 
- 이스마엘이 큰 민족을 이룰 것이라 말씀하심
- 하갈의 눈을 밝혀 샘물을 발견하게 하심
- 이스마엘과 함께 계심

6.인간 찾기 (관찰)
- 아브라함이 사라의 말을 듣고 매우 근심함
- 하나님의 말씀을 듣고 떠과 물 한 가죽부대를 하갈에게 주며 이스마엘과 광야로 나가게 함
- 브엘세바 광야에서 방황하던 하갈과 이스마엘은 물이 떨어져 살 소망이 사라짐
- 하갈이 아이과 괴로워 하며 죽는 것을 보지 못하겠어서 멀리 떨어져 이스마엘을 마주 안아 바라보며 소리 내어 울음
- 하나님께서 이스마엘의 소리를 들었고 그로 큰 민족을 일으킬 것이라는 말씀을 들음
- 눈이 밝아진 하갈은 샘물을 발견하고 물을 채워 이스마엘에게 마시게 함
- 이스마엘이 장성하여 광야에서 거주하며 활 쏘는 자가 됨

7.하나님 찾기 (해석) 
- 이삭이 아브라함의 후손이 돼야 함을 말씀하시며 하갈과 이스마엘을 내쫓게 하심
- 아브라함이 하갈과 이스마엘을 불쌍히 여기시는 것을 아시고,
- 그들도 돌보실 것을 말씀하심
- 하갈에게 희망과 용기를 주시고, 
- 눈을 밝혀 샘물을 발견하여 살아가게 하심

8.인간(해석):
- 매우 고민하던 아브라함은 하나님의 말씀에 순종하여 하갈과 이스마엘을 내쫓음
- 아브라함은 하갈과 이스마엘을 돌보실 하나님을 믿음
- 인간 주인에게 버림받은 하갈과 이스마엘은 절망했으나,
- 하나님이 돌보시겠다는 말씀을 듣고 힘을 얻었으며, 
- 눈이 떠져 샘물을 발견하고 마시는 과정을 통해 
- 하나님께서 앞으로 지켜주시고 보호하실 것을 확실히 믿게 되었을 것임 
- 이스마엘은 하나님의 돌보심 아래 광야에서 거주하며 활 쏘는 자가 됨

9.적용(나)
- 하나님의 사람은 주님이 말씀하시면, 그것이 자신의 가치관과 맞지 않더라도 그 말씀에 순종해야 한다.
- 하나님의 계획 안에 있는 자는 하나님의 돌보심 안에 있다.
- 지금 당장 상황이 힘에 겹더라도 도우시는 하나님을 바라며,
- 우리가 할 수 있는 일을 묵묵히 해나가야 한다.
- 하나님은 항상 나와 함께 하신다.

