- 아비멜렉과 군대 장관이 비골이 아브라함에게 네가 무슨 일을 하든지 하나님이 함께 계시낟고 말함
- 아브라함에게 자신의 아들과 손자에게 거짓되게 행하지 않기를 바라며 맹세를 요청함
- 아브라함은 아비멜렉의 종들이 아브라함의 우물을 뺏은 일은 말하며 책망함
- 아비멜렉은 누가 그리했는지 몰랐고 처음 듣는 일이라고 말함
- 아브라함은 양과 소를 가져다 아비멜렉에게 주고 언약을 세움
- 아브라함이 일곱 암양 새끼를 따로 놓았는데 아비멜렉이 묻자 우물 판 증거를 삼으라고 말함
- 두 사람이 서로 맹세하고 그곳을 브엘세바라고 칭함
- 아브라함은 브엘세바에 에셀 나무를 심고 영원하신 하나님 여호와의 이름을 부름 
7. 하나님 찾기 (해석) 
- 하나님은 아브라함과 함께 하시며 아브라함을 이끄시고 보호하심
8. 인간(해석):
- 아비멜렉은 하나님이 동행하는 아브라함이 하나님의 은혜로 민족이 커지는 것을 보고 두려운 마음이 들었을 수 있다. 아브라함에게 동맹을 요청하며 자신의 민족을 보호하려 했다. 
- 이 때 아브라함은 우물 사건을 언급하며 아비멜렉을 책망하는데 억울함이 있었음에도 하나님과 동행했던 아브라함은 그 일을 참았을 것이다. 그리고 아비멜렉에게 말할 수 있는 기회가 왔고 그 일을 언급하며 자신의 의로움을 나타낼 수 있었다. 나도 억울한 일이 생길 때 당장 그 일을 해결하고 억울함을 해소하려는 것 보다 지혜롭고 의롭고 오래참을 수 있는 영적 안목이 생기길 소망한다. 
- 아브라함은 아비멜렉에게 자신의 양과 소를 주고, 우물에 대한 대가로 일곱 암양 새끼까지 주어 아비멜렉을 안심시켰다. 자신의 지난 과오를 조금이나마 갚을 수 있는 기회였을 것이다. 
- 아브라함은 브엘세바에 에셀 나무를 심고 영원하신 하나님 여호와의 이름을 불렀는데 아브라함이 얼마나 하나님과 친밀하고 하나님을 신뢰하는지 알 수 있다. 
9. 적용(나): 
- 억울한 일에 참을 수 있는 인내와 용기를 갖길
- 하나님과 더욱 친밀해지기
