1:감동받는 단어나 구절 찾기(영적터치)

2024년 9월21일 창세기 22장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
독자 이삭: 2절(3) 3절 5절 6절 7절(2) 8절 9절 10절
번제: 2절 7절 8절
제단:9절(2)
아브라함: 1절(2) 3절 4절 5절 6절 7절 8절 9절
어린양: 7절 8절 
동행/함께: 5절 6절 8절 

4.주제만들기: 
독자 이삭을 번제로 드리려하는 아브라함 

5.하나님 찾기 (관찰)
아브라함을 시험(이삭을 번제)하시는 하나님 

6.인간 찾기 (관찰)
하나님 말씀에 순종하여 독자 이삭을 번제로 드리려 떠나는 아브라함 

7.하나님 찾기(해석)
하나님은 아브라함을 테스트 하시려고 독생자 아들 이삭을 번제물로 드릴것을 요구하셨다. 

사랑의 하나님 이시고 생명을 주시는 하나님께서 아끼는 아브라함에게 이러한 시험을 하신다는 것은 이성적으로 납득되지 않는 대목이다. 

하나님에 대하여  모두 이해할수는 없지만 분명한것은 하나님은 자신을 그 무엇보다 더욱 우선적으로 생각하기를 원하신다는 것이다. 

하나님도 자신의 하나밖에 없는 독생자 예수그리스도를 주신것 처럼 피차 최고로 사랑하는 관계성을 갖기를 원하신다.

8.인간 찾기 (해석)
아브라함은 자신의 독자 이삭을 희생제물로 삼으라는 하나님의 말씀을 순종하였다. 

처음 그러한 충격적인 명령을 받았을때 아브라함 심정은 어떠하였을까?

자신의 생명보다 귀한 노년에 얻은 독자 요 사랑하는 아들과 모리아산을 향하여 동행하는 현실은 어떠한 느낌이었을까?

아브라함은 모든 복잡한 생각을 접고 오직  부활의 믿음으로 말씀에 순종하여 다음날 한치의 망설임도 없이 ''일찍이 일어나'' 사랑하는 이삭을 데리고 모리아산 으로 올라갔다. 

결국 아브라함은 이제는 더욱 성숙한 믿음의 사람으로 성장된것을 볼수있다.

과연  하나님이 똑같은 명령을 하신다면 나는 어떻게 반응할까?

아마 많이 망설이고 새로운 타협점을 찾으려고 노력할것 같다.

하나님을 진심으로 믿고 따른다는 것은 결코 간단한 문제는 아닌것 같다.
나는 할수없지만 주님으로부터 더큰 부활과 천국의  소망을 갖는다면 하나님자녀라면 누구나 시험에 통과되지 않을까 생각된다.

평상시 더욱 천국 소망과 부활의 진리를 상고하며 마음에 새기는 훈련을 많이하는것이 중요할듯 하다.

9.적용(나):
부활의 믿음을 붙잡고 늘 주님께 순종하는 삶을 살아내야겠다 

10. 영적터치 (단어 또는 구절)
3절: 아브라함이 아침에 일찍이 일어나

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-28', '창세기', '22장 11절 ~ 24절', '&nbsp;', '(창세기 22장)
11. 여호와의 사자가 하늘에서부터 그를 불러 이르시되 아브라함아 아브라함아 하시는지라 아브라함이 이르되 내가 여기 있나이다 하매
12. 사자가 이르시되 그 아이에게 네 손을 대지 말라 그에게 아무 일도 하지 말라 네가 네 아들 네 독자까지도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라
13. 아브라함이 눈을 들어 살펴본즉 한 숫양이 뒤에 있는데 뿔이 수풀에 걸려 있는지라 아브라함이 가서 그 숫양을 가져다가 아들을 대신하여 번제로 드렸더라
14. 아브라함이 그 땅 이름을 여호와 이레라 하였으므로 오늘날까지 사람들이 이르기를 여호와의 산에서 준비되리라 하더라
15. 여호와의 사자가 하늘에서부터 두 번째 아브라함을 불러
16. 이르시되 여호와께서 이르시기를 내가 나를 가리켜 맹세하노니 네가 이같이 행하여 네 아들 네 독자도 아끼지 아니하였은즉
17. 내가 네게 큰 복을 주고 네 씨가 크게 번성하여 하늘의 별과 같고 바닷가의 모래와 같게 하리니 네 씨가 그 대적의 성문을 차지하리라
18. 또 네 씨로 말미암아 천하 만민이 복을 받으리니 이는 네가 나의 말을 준행하였음이니라 하셨다 하니라
19. 이에 아브라함이 그의 종들에게로 돌아가서 함께 떠나 브엘세바에 이르러 거기 거주하였더라
20.  이 일 후에 어떤 사람이 아브라함에게 알리어 이르기를 밀가가 당신의 형제 나홀에게 자녀를 낳았다 하였더라
21. 그의 맏아들은 우스요 우스의 형제는 부스와 아람의 아버지 그므엘과
22. 게셋과 하소와 빌다스와 이들랍과 브두엘이라
23. 이 여덟 사람은 아브라함의 형제 나홀의 아내 밀가의 소생이며 브두엘은 리브가를 낳았고
24. 나홀의 첩 르우마라 하는 자도 데바와 가함과 다하스와 마아가를 낳았더라

