2024년 9월22일 창세기 22장11절~24절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 사용 추천)
여호와의 사자: 11절 12절 15절
아브라함: 11절(2) 12절13절(2) 14절 15절 17절 19절 20절
이삭: 12절 16절
아끼지 아니함: 12절 16절
숫양: 13절(2)
여호와 이레: 14절(2)

4.주제만들기: 
하나님 시험에 통과된 아브라함 

5.하나님 찾기 (관찰)
사자를 통하여 아브라함을 막으시는 하나님
아브라함의 순종을 인정하시는 하나님
숫양을 미리 준비하신 하나님

6.인간 찾기 (관찰)
하나님께 진심으로 인정받은 아브라함 

7.하나님 찾기(해석)
아브라함 한사람의 큰 믿음을 통하여 육적 혈통 뿐만 아니라 온 민족이 복을 받게 됐다.  

하나님의 시험에 통과한 아브라함의 모습이 많이 부럽다.  사람들에게 인정받는것은 그렇게 어렵지 않다. 조금만 성실하고 친절하면 신뢰감을 줄수있다. 하지만 하나님으로부터 인정받는 것은 나의 최고의 것 어쩌면 나의 육체적 생명보다 더  주님을 사랑해야 될것이다.  

하나님의 마음을 대언한 사자가 "이제야" 라는 말을 사용한것보니 더욱 느껴진다.  

성화단계에서도 하나님이 요구하시는 믿음의 높이가 있다고 여겨진다.

8.인간 찾기 (해석)
여호와이레 하나님은 우리의 모든 필요를 준비하시는 분이시다. 우리가 주의 영광을 위하여 헌신하고 희생한다면 반드시 숫양을 우리 삶 가운데 준비하신다.

9.적용(나):
 전심을 다하여 하나님을 경외하는 삶을 살아내야겠다 

10. 영적터치 (단어 또는 구절)
12절: 이제야

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-29', '창세기', '23장 1절 ~ 10절', '사라의 죽음&nbsp;', '[창23:1-10]
1 사라가 백이십칠 세를 살았으니 이것이 곧 사라가 누린 햇수라
2 사라가 가나안 땅 헤브론 곧 기럇아르바에서 죽으매 아브라함이 들어가서 사라를 위하여 슬퍼하며 애통하다가
3 그 시신 앞에서 일어나 나가서 헷 족속에게 말하여 이르되
4 나는 당신들 중에 나그네요 거류하는 자이니 당신들 중에서 내게 매장할 소유지를 주어 내가 나의 죽은 자를 내 앞에서 내어다가 장사하게 하시오
5 헷 족속이 아브라함에게 대답하여 이르되
6 내 주여 들으소서 당신은 우리 가운데 있는 하나님이 세우신 지도자이시니 우리 묘실 중에서 좋은 것을 택하여 당신의 죽은 자를 장사하소서 우리 중에서 자기 묘실에 당신의 죽은 자 장사함을 금할 자가 없으리이다
7 아브라함이 일어나 그 땅 주민 헷 족속을 향하여 몸을 굽히고
8 그들에게 말하여 이르되 나로 나의 죽은 자를 내 앞에서 내어다가 장사하게 하는 일이 당신들의 뜻일진대 내 말을 듣고 나를 위하여 소할의 아들 에브론에게 구하여
9 그가 그의 밭머리에 있는 그의 막벨라 굴을 내게 주도록 하되 충분한 대가를 받고 그 굴을 내게 주어 당신들 중에서 매장할 소유지가 되게 하기를 원하노라 하매
10 에브론이 헷 족속 중에 앉아 있더니 그가 헷 족속 곧 성문에 들어온 모든 자가 듣는 데서 아브라함에게 대답하여 이르되

