2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 사라(1,2,절), 아브라함(4,6,7,8절), 헷 족속(3,5,10절), 장사(4,6,8절), 죽은 자(4,6,8절) 막벨라 굴(9절)
4. 주제만들기: 사라의 죽음 
5. 하나님 찾기 (관찰)
6. 인간 찾기 (관찰)
- 127세에 사라가 죽음
- 아브라함이 사라를 위해 슬퍼함
- 헷 족속에게 나그네이고 거류하는 자이니 매장할 소유지를 주어 사라를 장사할 수 있게 해달라고 요청함
- 헷 족속은 아브라함에게 하나님이 세우신 지도자이니 묘실 중에 좋은 곳을 선택해 장사하라고 말함
- 아브라함은 헷 족속에 몸을 굽히고 막벨라 굴을 주고 충분한 대가를 받으라 간청함
7. 하나님 찾기 (해석) 
8. 인간(해석):
- 아브라함은 사라의 죽음이 슬펐을 것이다. 평생을 사랑한 동반자의 죽음을 받아들이는 것은 쉬운 것이 아니다. 사라를 장사할 수 있는 곳을 찾았고, 그 곳은 자신의 나그네이지만 안정적으로 유지할 수 있는 장소를 희망했다. 
- 아브라함은 헷 족속에게 정중히 사라를 장사할 곳을 요청한다. 헷 족속은 오히려 하나님이 세운 지도자이니 마음대로 해도 된다고 말한다. 그러나 아브라함은 정당한 대가를 지불하고 사라를 위한 장소를 요청했다. 아브라함의 신앙이 성숙되어 있음을 느낄 수 있다.
9. 적용(나): 
- 내가 가질 수 있는 것이라도 겸손하게 하나님의 뜻을 구해야겠다. 
- 매사에 정직하고 하나님 보시기에 부끄럽지 않게 행동해야겠다.
10. 영적터치(단어/구절)
- 9절 충분한 대가
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-09-30', '창세기', '23장 11절 ~ 20절', '사라의 장지로 헤브론 땅을 사다&nbsp;', '창세기 23장
11   내 주여 그리 마시고 내 말을 들으소서 내가 그 밭을 당신에게 드리고 그 속의 굴도 내가 당신에게 드리되 내가 내 동족 앞에서 당신에게 드리오니 당신의 죽은 자를 장사하소서
12   아브라함이 이에 그 땅의 백성 앞에서 몸을 굽히고
13   그 땅의 백성이 듣는 데서 에브론에게 말하여 이르되 당신이 합당히 여기면 청하건대 내 말을 들으시오 내가 그 밭 값을 당신에게 주리니 당신은 내게서 받으시오 내가 나의 죽은 자를 거기 장사하겠노라
14   에브론이 아브라함에게 대답하여 이르되
15   내 주여 내 말을 들으소서 땅 값은 은 사백 세겔이나 그것이 나와 당신 사이에 무슨 문제가 되리이까 당신의 죽은 자를 장사하소서
16   아브라함이 에브론의 말을 따라 에브론이 헷 족속이 듣는 데서 말한 대로 상인이 통용하는 은 사백 세겔을 달아 에브론에게 주었더니
17   마므레 앞 막벨라에 있는 에브론의 밭 곧 그 밭과 거기에 속한 굴과 그 밭과 그 주위에 둘린 모든 나무가
18   성 문에 들어온 모든 헷 족속이 보는 데서 아브라함의 소유로 확정된지라
19   그 후에 아브라함이 그 아내 사라를 가나안 땅 마므레 앞 막벨라 밭 굴에 장사하였더라 (마므레는 곧 헤브론이라)
20   이와 같이 그 밭과 거기에 속한 굴이 헷 족속으로부터 아브라함이 매장할 소유지로 확정되었더라

