2024년 9월 24일 창세기 23장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
밭: 11, 13, 17(3), 20
굴: 11, 20
당신: 11(3), 13(2), 15(2)
