마므레: 17, 19(2)
확정: 18, 20

4.주제 만들기: 사라의 장지로 헤브론 땅을 사다 

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 헷 족속인 에브론이 자신의 밭과 굴을 
- 아브라함이 사라의 장지로 사용하도록 
- 무상으로 주겠다고 함
- 아브라함이 헷 족속들에게 절하며 
- 에브론에게 밭 값을 받으면, 장지로 사용하겠다고 말함
- 에브론이 밭 값을 은 사백 사겔이라 이야기하며 
- 당신과 나 사이에 밭 값은 문제가 안 된다고 말함
- 아브라함이 에브론이 말한 은 사백 세겔을 에브론에게 주었고
- 이에따라 가나안 땅 마므레 앞 막벨라에 있는 밭과 굴과 그곳에 있는 모든 나무가 
- 헷 족속 백성들이 보는 앞에서 아브라함의 것으로 확정됨
- 그 후에 아브라함이 사라를 막벨라 밭 굴에 장사함
- 이렇게 하여 그 밭과 거기에 있는 굴은 
- 헷 사람으로부터 아브라함의 소유로 확정되었다. 

7.하나님 찾기(해석)

8.인간 찾기 (해석)
- 아브라함이 에브론의 이름과 그 땅의 소유주가 에브론인 것을 알고 말한 것을 보면,
- 에브론은 아브라함과 알고 지내던 사이로 보인다.
- 자신의 땅을 무상으로 주겠노라 백성들 앞에서 말한 것으로 보아,
- 에브론은 평소 아브라함을 지역의 지도자 또는 존경하는 어른으로 여겼던 것으로 보인다.
- 아브라함은 모인 백성들에게 절을 하며,
- 밭 값을 꼭 지불하야 장지로 사용하겠다고 말한다.
- 겸손과 정직함을 볼 수 있으며,
- 이로 인해 헷 족속 모두가 보는 앞에서 소유권을 공식화하게 되었다.
- 이는 훗날 발생할 수 있는 소유권 문제의 발생을 예방한 지혜로운 행동이다.
- 이제 이 가나안 땅은 아브라함의 소유지로 확정이 되었다.
- 아브라함은 하나님께서 약속하신 가나안 땅을 
- 값을 주고 지불하였다.
- 그리고 그곳을 장지로 사용하였다.
- 이것은 하나님께서 가나안 땅을 주실 것을 확실히 믿은 곳이요,
- 이 가나안 땅이 자기와 자손들이 살아갈 터전임을 확실히 믿은 결과이다.

9.적용(나)
- 하나님께서 보내신 가정, 일터, 지역 사회에서
- 아브라함처럼 젊은이들에게 존경받는 믿음의 어른이 되고 싶다.
- 내가 많은 사람들에게 존경받고 싶어서가 아니라, 
- 아브라함의 삶이 내게 본이 되어 그와 같이 살고 싶다.
- 그의 믿음과 겸손, 그리고 정직함과 지혜를 닮아야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-01', '창세기', '24장 1절 ~ 10절', '&nbsp;', '(창세기 24장)
1.  아브라함이 나이가 많아 늙었고 여호와께서 그에게 범사에 복을 주셨더라
2. 아브라함이 자기 집 모든 소유를 맡은 늙은 종에게 이르되 청하건대 내 허벅지 밑에 네 손을 넣으라
3. 내가 너에게 하늘의 하나님, 땅의 하나님이신 여호와를 가리켜 맹세하게 하노니 너는 내가 거주하는 이 지방 가나안 족속의 딸 중에서 내 아들을 위하여 아내를 택하지 말고
4. 내 고향 내 족속에게로 가서 내 아들 이삭을 위하여 아내를 택하라
5. 종이 이르되 여자가 나를 따라 이 땅으로 오려고 하지 아니하거든 내가 주인의 아들을 주인이 나오신 땅으로 인도하여 돌아가리이까
6. 아브라함이 그에게 이르되 내 아들을 그리로 데리고 돌아가지 아니하도록 하라
7. 하늘의 하나님 여호와께서 나를 내 아버지의 집과 내 고향 땅에서 떠나게 하시고 내게 말씀하시며 내게 맹세하여 이르시기를 이 땅을 네 씨에게 주리라 하셨으니 그가 그 사자를 너보다 앞서 보내실지라 네가 거기서 내 아들을 위하여 아내를 택할지니라
8. 만일 여자가 너를 따라 오려고 하지 아니하면 나의 이 맹세가 너와 상관이 없나니 오직 내 아들을 데리고 그리로 가지 말지니라
9. 그 종이 이에 그의 주인 아브라함의 허벅지 아래에 손을 넣고 이 일에 대하여 그에게 맹세하였더라
10. 이에 종이 그 주인의 낙타 중 열 필을 끌고 떠났는데 곧 그의 주인의 모든 좋은 것을 가지고 떠나 메소보다미아로 가서 나홀의 성에 이르러

