8.인간 찾기 (해석)
아브라함은 노년에 독자 이삭의 배필을 구하기 위하여 집안의 늙은 종을 고향 땅으로 떠나보낸다. 

늙은 종은 보통의 일반 종은 아닌듯 하다. 평상시 아브라함의 모든 재산 관리권을 위임할 정도면 얼마나 신뢰감이 깊으면 그럴수 있을까? 

평상시 아브라함은 사람을 어떻게  대하는지 느껴진다.

그러한 종에게 사랑하는 독자 배필을 구하는 집안의 큰 대사까지 맡기는 것은 대단하게 느껴진다.  

한편 아브라함은 자신에게 약속하신 하나님의 말씀을 잊지않고  잘 해석하여 배필을 구할때  이삭이 고향땅으로 가는것이 아닌 배필이 복 받을 땅 가난안으로 올 것을 근거로 데려오도록 지시한다.

아브라함의 말씀 해석 능력을 볼수있다. 몸은 유연성이 다소 떨어지는 노년이 되었지만 하나님의 의도를 분별하는 능력은 더욱 성숙됨을 볼수있다.

