6.인간 찾기(관찰)
- 아브라함의 종을 따라 이삭에게 가는 리브가
- 브엘라헤로이에서 떠나 네게브 지역에 거주하는 이삭
- 들에서 묵상하다가 낙타들이 오는 것을 보는 이삭
- 다가오는 이삭을 바라보고 아브라함의 종에게 다가오는 이가 누구냐고 묻는 리브가
- 듣고 자기 얼굴을 너울로 가리는 리브가
- 종에게 행한 일들을 묻고 듣는 이삭
- 이삭을 맞이하여 아내로 삼고 어머니를 장례한 후에 위로를 얻는 이삭
 
7.하나님 찾기(해석)

8.인간 찾기 (해석)
- 아버지의 집과 가족을 떠나 아브라함의 종을 따라가는 모습을 볼 때
- 리브가는 믿음이 강하고 담대한 마음을 소유한 자로 보인다.
- 이삭은 어머니를 그리워하며 네게브 지역에 거주하고 있었다.
- (노년에 이삭을 낳은 사라가 이삭을 얼마나 아끼고 사랑했을지, 
- 그 사랑을 받은 이삭이 어머니를 여의고 나서 어머니를 얼마나 그리워했을지 우리는 유추할 수 있다.)
- 이삭은 들에 나가 하나님 말씀도 묵상하고 어머니도 그리워하고 있었을 것이다.
- 묵상하던 중 자신의 아내될 사람을 데리고 오는 종과 낙타의 행렬을 보았고,
- 기대하는 마음으로 다가갔을 것이다.
- 다가오는 이삭을 발견한 리브가는 그가 누구인지 물었고, 남편될 사람 이삭임을 확인하고 예를 갖추기 위해 너울로 얼굴을 가렸다
- 종은 있었던 일을 이삭에게 모두 말하였으며,
- (이것으로 종의 임무는 완수되었다. 종은 모든 과정에서 하나님의 역사를 경험했다.)
- 이삭은 리브가를 어머니 사라의 장막으로 들였다.
- (그곳에서 어머니에 대한 이야기와 이런저런 이야기를 나누었을 것이다.) 
- 이삭은 리브가를 아내로 삼았으며, 아내를 사랑했다.
- 이 일로 이삭은 어머니를 잃은 슬픔을 위로받았다.
- (이 모든 일을 하나님께서 하셨음을 이삭과 리브가는 경험하였다.)

9.적용(나) 
