- 이삭은 하나님의 복을 받은 아브라함의 아들로서 부족함 없이 자랐을 것이다.
- 첫 번째 결핍을 어머니를 잃는 것으로 경험한 이삭은 절망 속에서 허우적거렸을지 모르겠다.
- 그런데 그 깊은 수렁 속에 있는 자신을 
- 리브가를 통해 건지신 하나님을 경험하므로 
- 이삭의 믿음은 한 단계 성장했으며, 나아가 하나님을 더욱 경외하게 되었을 것이다.

- 절망과 깊은 수렁에 빠졌을 때, 우리는 역사하시는 하나님을 기대하며 바라봐야한다.
- 이삭에게 역사하신 하나님은,
- 하나님의 자녀인 우리에게도 동일하게 역사하시기 때문이다.

