7.하나님 찾기(해석)
8.인간 찾기 (해석)
하나님이 아브라함에게 과거에 아브라함이 가장 사랑했던 아내 사라를 통하여 독자 이삭을 주시고 그를 통하여 자손들의 영적인 복과 번창을 약속하셨다. 
그때 임종을 얼마 남겨놓지 않은 아브라함의은 나이가 더 많은 이스마엘이 아닌 이삭을 택하여 대부분의 재산을 주었다. 
그리고 다른 서자들에게도 분깃을 정도껏 나누어 주었다
이 또한 9절에 보면 아브라함이 장사될때 이스마엘 이름보다 나이가 어린 이삭의 이름이 서열 앞에 의도적으로 기록 된 것을 통하여 하나님이 인정하시듯이 아브라함은 그대로 이행하고 있었다.
임종 끝까지 하나님의 뜻대로 이행하였던 아브라함은 자녀들이 분깃으로 인한 다툼없이 잘 마무리가 되었다.
한편 세상에서 모든 민족의 영적 믿음의 조상이라 일컬어지는 아브라함이라고 하더라도 모든 생명을 주관하시는 하나님의 역사속에서는 그저 스처지나가는 작은 피조물이라는 생각이 든다. 이방신을 믿고 살았던 작은 집안을 택하사 역사의 위대한 자로 사용하셨던 정말 위대하고 전능하신 하나님을 찬양하게된다.
누구든지 하나님께 사용받는다면 그가 지금은 초라하고 작은자라고 하더라도 아브라함처럼 쓰임받게 될것이다.
설령 아브라함처럼 외부로 들어나는 사람처럼 유명인이 아니더라도 주님을 믿는 자녀라면 그것만으로도 아브라함처럼 멋진 생애를 사는 사람들일 것이다!!
아멘!!
