4.주제 만들기: 야곱과 에서

5.하나님 찾기(관찰)
- 이삭의 간구를 들으심
- 리브가에게 두 아들의 앞날에 대해 말씀하심

6.인간 찾기(관찰)
- 이삭이 임신을 위해 기도함
- 이삭의 기도로 임신한 리브가가 
- 복 중에서 싸우는 쌍둥이를 보며 고민하다가 하나님께 기도함
- 하나님이 두 아들의 앞날에 대해 말씀하심 
- 때가 되어 쌍둥이를 출산함
- 첫째는 털이 많은 에서이고, 
- 둘째는 에서의 발뒤꿈치를 잡고 나온 야곱
- 에서는 사냥을 잘하는 들사람이 되고,
- 야곱은 조용한 사람으로 장막에 거주하였다.
- 야곱은 에서가 잡은 고기를 좋아하므로 에서를 좋아하였고,
- 리브가는 야곱을 좋아하였다.
- 에서가 허기진 채 돌아와서 야곱이 끓여놓은 죽을 먹고 싶어하자,
- 야곱이 죽과 장자의 명분을 바꾸자고 함
- 배가 많이 고팠던 에서는 맹세까지 하며 죽과 장자의 명분을 바꾸겠다고 함
- 그리고 에서는 장자의 명분을 가벼이 여기고 죽과 맞바꿈

7.하나님 찾기(해석)
- 이삭의 기도를 들으시고 리브가가 임신하게 하시되,
- 계획 안에서 쌍둥이를 갖게 하시고,
- 에서가 야곱을 섬기게 될 것을 리브가에게 말씀하심

8.인간 찾기 (해석)
- 이삭은 기도함으로 리브가가 임신됨을 경험함
- 리브가는 하나님께 기도함으로 복중의 태아의 앞날을 알게 됨
- 외모도 성향도 매우 다르게 태어난 두 아들 중
- 에서는 이삭에게 사랑을 받고
- 야곱은 리브가에게 사랑을 받음
- 이삭이 에서를 사랑한 이유는 에서가 잡아온 고기가 좋았기 때문이었고,
- 리브가가 야곱을 사랑한 이유는 장막에 거주하여 리브가와 시간을 많이 보낸 것과
- 하나님께서 큰 자가 작은 자를 섬길 것이라 말씀하신 것을 기억하고 있었기 때문일 것이다.
- 에서는 들사람으로 사냥하는 것을 즐겼을 것이고, 그것에 심취하여 장자의 명분이나 하나님보다 사냥을 즐거워 했을 가능성이 높다.
- 야곱은 어머니 리브가에게 사랑을 받았으며 장막에서 시간을 보냈기에,
- 리브가에게 하나님께서 말씀하시길 에서가 너를 섬길 것이라고 하셨다는 말을 들었을 것임
- 때가 왓고, 
- 야곱은 허기진 에서에게 죽과 장자의 명분을 맞바꾸자는 제안을 하였고,
- (장자의 명분보다 사냥이 즐겁고 중요했던?) 에서는 
- 죽과 장자의 명분을 바꾸는 경솔한 행동을 함 

