리브가: 8절 9절 10절
어찌: 9절 10절

4.주제만들기: 
그랄에 거주하는 이삭

5.하나님 찾기 (관찰)
애굽땅에 거주하지말고 지시하는 땅으로 가라고 이삭에게 말씀하시는 하나님 

6.인간 찾기 (관찰)
그랄에 거주하는 이삭
그곳 사람들에게 아내를 누이라고 속이는 이삭
블레셋왕 아비멜렉에게 그 사실이 드러남
변명하는 이삭

7.하나님 찾기(해석)
하나님은 아브라함에게 하였듯이 이삭에게 갈곳을 인도해 주신다.


8.인간 찾기 (해석)
 반복적으로 인도하심과 비전을 주시는 하나님과 반복적으로 죄를 짓는 약한 인간을 보게된다.  

하나님은 아브라함에게 주신 자손의 번창의 복을 그의 아들 이삭에게도 말씀 하셨다. 

하나님의 말씀에 순종하여 간곳은 그랄 이었다. 그런데 그곳에서 이삭은 큰 실수를 저지른다. 과거에 그의 아버지 아브라함이 두번이나 저지른 행위이다

그것은 이방인들을 무서워하여 아내를 누이라고 속인다. 하지만 그곳 아비멜렉이왕 에게 도리어 책망을 듣는다.

하나님께서 분명히 3절에 "내가 너와 함께 있어" 말씀하신 부분을 스스로 두려움을 갖고 기억하지 못한듯하다.

하나님 자녀라도 믿음을 온전히 지키지못한다면 세상으로부터 수치감을 받을수 있음을 알게된다.

9.적용(나):
나와 동행하시는 주님만 오직 의지하며  오늘도 승리하는 삶을 살아내야겠다 

10. 영적터치 (단어 또는 구절)
9절: 어찌 네 누이라 하였느냐 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-12', '창세기', '26장 11절 ~ 20절', '&nbsp;', '(창세기 26장)
11. 아비멜렉이 이에 모든 백성에게 명하여 이르되 이 사람이나 그의 아내를 범하는 자는 죽이리라 하였더라
12. 이삭이 그 땅에서 농사하여 그 해에 백 배나 얻었고 여호와께서 복을 주시므로
13. 그 사람이 창대하고 왕성하여 마침내 거부가 되어
14. 양과 소가 떼를 이루고 종이 심히 많으므로 블레셋 사람이 그를 시기하여
15. 그 아버지 아브라함 때에 그 아버지의 종들이 판 모든 우물을 막고 흙으로 메웠더라
16. 아비멜렉이 이삭에게 이르되 네가 우리보다 크게 강성한즉 우리를 떠나라
17. 이삭이 그 곳을 떠나 그랄 골짜기에 장막을 치고 거기 거류하며
18. 그 아버지 아브라함 때에 팠던 우물들을 다시 팠으니 이는 아브라함이 죽은 후에 블레셋 사람이 그 우물들을 메웠음이라 이삭이 그 우물들의 이름을 그의 아버지가 부르던 이름으로 불렀더라
19. 이삭의 종들이 골짜기를 파서 샘 근원을 얻었더니
20. 그랄 목자들이 이삭의 목자와 다투어 이르되 이 물은 우리의 것이라 하매 이삭이 그 다툼으로 말미암아 그 우물 이름을 에섹이라 하였으며

