5.하나님 찾기 (관찰)
이삭이 거부가 되도록 복을 주신 하나님

6.인간 찾기 (관찰)
거부가 된 이삭을 시기하는 블레셋 사람들
시기하여 이삭의 종들이 판 우물을 반복적으로 막는 블레셋 사람들

7.하나님 찾기(해석)
하나님은 이삭에게 물질의 풍요로운 복을 허락하셨다. 결국 그랄 땅에서 이삭이 거부가 되었다.

하나님이 마음만 결정하신다면 누구에게나 풍요로움을 주실수 있는 능력의 하나님 이시다.

8.인간 찾기 (해석)
 큰복을 받아 그랄땅에서 거부가 된 이삭이다. 그런데 갑부가 된 이삭을 시기한 블레셋 사람들로부터 스스로 판 우물을 먹지못하게 방해를 받는다.

이렇게 계속되는 방해로 어러움을 받고 작은 다툼도 있었지만 새로운 우물을 계속적으로 찾아다니는 이삭의 태도를 볼수있다.

근동지역에는 특별히 물이 귀한곳인데 그러한 생명수 같은 우물을 블레셋 사람들에게 양보하고 큰 분쟁을 피하는 이삭의 성실성과 지혜를 발견할수있다. 

9.적용(나):
주변에 시기하는 사람들이 있는지 살펴보고 있다면 이삭처럼 지혜롭게 대처해 나가야 겠다. 

