INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-10-13', '창세기', '26장 21절 ~ 30절', '여호와께서 함께하는 이삭', '[창26:21-30]
21 또 다른 우물을 팠더니 그들이 또 다투므로 그 이름을 싯나라 하였으며
22 이삭이 거기서 옮겨 다른 우물을 팠더니 그들이 다투지 아니하였으므로 그 이름을 르호봇이라 하여 이르되 이제는 여호와께서 우리를 위하여 넓게 하셨으니 이 땅에서 우리가 번성하리로다 하였더라
23 이삭이 거기서부터 브엘세바로 올라갔더니
24 그 밤에 여호와께서 그에게 나타나 이르시되 나는 네 아버지 아브라함의 하나님이니 두려워하지 말라 내 종 아브라함을 위하여 내가 너와 함께 있어 네게 복을 주어 네 자손이 번성하게 하리라 하신지라
25 이삭이 그 곳에 제단을 쌓고, 여호와의 이름을 부르며 거기 장막을 쳤더니 이삭의 종들이 거기서도 우물을 팠더라
26 아비멜렉이 그 친구 아훗삿과 군대 장관 비골과 더불어 그랄에서부터 이삭에게로 온지라
27 이삭이 그들에게 이르되 너희가 나를 미워하여 나에게 너희를 떠나게 하였거늘 어찌하여 내게 왔느냐
28 그들이 이르되 여호와께서 너와 함께 계심을 우리가 분명히 보았으므로 우리의 사이 곧 우리와 너 사이에 맹세하여 너와 계약을 맺으리라 말하였노라
29 너는 우리를 해하지 말라 이는 우리가 너를 범하지 아니하고 선한 일만 네게 행하여 네가 평안히 가게 하였음이니라 이제 너는 여호와께 복을 받은 자니라
30 이삭이 그들을 위하여 잔치를 베풀매 그들이 먹고 마시고

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도
2. 본문성경 읽기(3번)
3. 반복단어 찾기(형광펜 추천)
- 우물(21,22절), 아브라함(24절), 여호와(22,24,25,28절), 이삭(22,23,25,26,27,28,29,30절)
  다투다(21,21절)
4. 주제만들기: 여호와께서 함께하는 이삭
5. 하나님 찾기 (관찰)
- 여호와께서 이삭의 가정을 넓게 하심
- 밤에 이삭에게 나타나 아브라함의 하나님이니 두려워말라고 하시며, 너와 함께하며 네게 복을 주어 자손이 번성하게 하리라고 하심
6. 인간 찾기 (관찰)
- 두 번째 우물을 팠더니 또 다툼, 세 번째 우물을 팠더니 다투지 않음
- 이삭은 르호봇이라 불렀고 브엘세바로 올라감. 그곳에 제단을 쌓고 여호와의 이름을 부르며 장막을 침, 이삭의 종들이 그곳에도 우물을 팜
- 아비멜렉이 아훗삿과 군대 장관 비골과 함께 이삭에게 옮
- 이삭은 나를 미워하여 떠났거늘 왜 찾아왔는지 물음
- 그들은 여호와께서 함께 하심을 보고 맹세하여 계약을 맺고자 함을 말함
- 그들은 자신들을 해하지 말고 너희를 범하지 않은 선한 일을 행해 평안히 가게하였으니 여호와께 복을 받은 자이기 때문이라고 함
- 이삭은 잔치를 베품
7. 하나님 찾기 (해석)
- 하나님께선 이삭에게 복을 주셨고 아브라함에게 하셨던 언약을 이삭에게도 동일하게 말씀하신다. 
- 하나님의 언약은 세대를 거쳐 현재 진행형으로 이어질 수 있다.  
8. 인간(해석):
- 이삭은 두 번이나 다툼으로 우물을 잃었지만 다른 곳으로 이동해 다시 우물을 팠다. 화가 났을 법도 하지만 다툼보단 평화를 선택했다. 
- 이삭은 브엘세바로 올라가 하나님을 만나는데 하나님께서 아브라함에게 하셨던 축복을 해주셨다. 이삭이 얼마나 감사했고, 든든했을지 생각해본다. 
- 이삭에게 아비멜렉과 그 친구들이 찾아오는데 이삭은 과거에 참았던 일을 언급할 수 있는 기회를 얻는다. 지금 당장 피해, 손해를 보더라도 하나님을 생각하고 참으면 나에게 선한 일로 돌아올 수 있음을 깨닫는다.
- 그렇지만 아비멜렉은 참으로 얄밉다. 이삭이 두려웠기에 친구들을 데려갔을 것이다. 이삭은 다시 평화를 선택한다. 아마 그들이 여호와의 이름을 언급하며 복을 받은 자라고 말했기 때문일 것이다. 이삭은 그들에게 잔치를 베푸는 너그러움을 보였다.
9. 적용(나): 
- 지금 당장 손해보더라도 하나님을 생각하며 참을 것을 끝까지 참자
- 다툼이 생길만한 일에 평화를 선택하며 하나님의 의를 드러내야겠다.
