8.인간 찾기 (해석)
 이삭은 장자권 축복을 큰아들 에서 에게 주려고 했다. 그러나 하나님은 형 에서가 아닌 쌍둥이 동생 야곱에게 줄것을 이미 예비하셨고 이삭에도 예고하셨었다.

뿐만아니라 형 에서는 장자권을 가볍게 여겨 단팥죽 한 그릇에 동생 야곱에게 팔았다. 이어서 이방 족속인 헷 족속과의 결혼을 하여 부모인 이삭과 리브가를 근심하게 만들었다.

이삭은 어쩌면 인간적인 관습에 따라 큰아들 에서에게 장자권을 주려고 했던 것 같다. 잠시 하나님의 섭리를 잊은 듯 하다. 그는 육체적 노화현상 뿐만 아니라 영적으로 둔해진것 같다.

다행히 아내 리브가는 하나님의 의도하심을 기억하고 둘째아들 야곱에게 장자권을 이행하려 힘쓴다.

 나를 포함해서 현대 기독교인들도 복음의 본질을 왜곡하며 적당히 타협하려는 세상의 관습이나 전통사상을 철저히 경계하며 살아야함을 깨우친다.

