4.주제 만들기: 리브가와 야곱이 이삭을 속이다

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 이삭에게 거짓이 들통날 것이라 말하며
- 축복대신 저주을 받을 것이라 말하는 야곱
- 그 저주는 내가 받을테니 시키는 대로 하라는 리브가
- 야곱이 염소 두 마리를 끌고 오자 
- 리브가는 이삭의 입 맛에 맞게 별미를 만들고
- 에서의 가장 좋은 옷을 야곱에게 입히고, 
- 염소 가죽을 야곱의 손과 목덜미에 둘러 에서로 변장하게 함
- 야곱이 에서로 변장하고 별미를 들고 이삭에게 가서
- 에서라고 속이고 별미를 주며 축복해 달라고 함
- 이삭은 의심하며 어떻게 그렇게 빨리 잡았느냐 물어봄
- 야곱은 아버지의 하나님 여호와께서 나로 순조롭게 만나게 하였다고 속임

7.하나님 찾기 (해석) 
-  

8.인간(해석): 
리브가는 큰 자가 작은 자를 섬길 것이라는 하나님의 말씀을 간직하며 살았을 것이다.
그리고 장막에 긴 시간 머무른 야곱을 사랑하며 살아왔다.
이삭이 축복 받기를 간절히 원한 리브가는 작전을 세우고 야곱이 수행하게 한다.
걱정하는 야곱에게 전술을 지시한다.
이삭에 대해 잘 알고, 에서와 야곱에 대해서도 잘 아는 리브가는 별미와 염소 가죽 등으로 철저하게 준비한다.
야곱은 어머니의 전술 지시를 잘 이행한다.

하나님께서는 야곱을 크게 하시고 에서는 야곱을 섬기게 하실 것이다.
이미 말씀하셨기 때문이다.
리브가와 야곱이 이삭을 속이지 않더라도 그렇게 됐을 것이다.
그런데 두 사람은 굳이 이삭을 속였고, 이 이야기가 성경에 기록되었다.

어쩌면 이삭과 리브가의 편애가 하나님의 역사하심보다 앞섰는지 모르겠다.
이삭이 에서를 편애하자, 리브가는 자신이 편애하는 야곱이 축복받지 못하는 것을 두려워하여 이삭을 속인다.

어찌됐던 야곱을 하나님께 복을 받을 사람이었다.

한편, 이삭에게 축복을 받으면 정말 복을 받을 것이라는 믿음이 리브가와 야곱에게 있었던 것은 확실하다.
이것을 통해 이삭의 믿음과 하나님과 교제의 깊이가 얼마나 깊었는지 간접적으로 알 수 있다.

9.적용(나)
- 자녀를 키울 때 편애하지 않도록 조심해야한다.
- 아버지의 축복을 받는다는 것은 대단한 특권이다.
- 아버지께 축복 기도를 받아야 한다.
- 그리고 복의 근원이신 하나님께 기도할 수 있다는 것은 가장 큰 특권이다.
- 이를 기억하고 기도해야겠다.

10. 영적터치(단어/구절)  
  
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);